window.__CH("c21",["<div class=\"hw\">O, o</div><div class=\"pos\"><i>indecl n</i></div><div class=\"def\">ラテン語アルファベットの第14字.</div>\r\n","<div class=\"hw\">Oasis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オアシス《Libya 砂漠にあった肥沃地で, ローマ帝政期における流刑地》.</div>\r\n","<div class=\"hw\">Oasēnus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://Oasis\">Oasis</a>]</div><div class=\"def\">オアシスの.</div>\r\n","<div class=\"hw\">Oaxēs</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オアクセース《Creta 島の川》.</div>\r\n","<div class=\"hw\">ob</div><div class=\"pos\"><i>prep</i></div><div class=\"def\">〈+<i>acc</i>〉</div><div class=\"def\"><num>①</num> ...の前に, ...の行く手に.</div><div class=\"def\"><num>②</num> ...に向かって, ...の方へ.</div><div class=\"def\"><num>③</num> ...の(利益の)ために, ...の有利になるように</div><div class=\"ex\"><i>～ rem</i> (<author>S<small>ALL</small></author>)<span class=\"ext\">有効に, 有利に.</span></div><div class=\"def\"><num>④</num> ...の理由で, ...のために;...の結果として.</div><div class=\"def\"><num>⑤</num> ...の報いとして;...の代償として.</div>\r\n","<div class=\"hw\">ob-</div><div class=\"pos\"><i>pref</i></div><div class=\"ori\">[↑<a href=\"entry://ob\">ob</a>]</div><div class=\"def\">意味は前置詞 <a href=\"entry://ob\">ob</a> を参照(c, f, g, p の前ではそれぞれ oc-, of-, og-, op- となる).</div>\r\n","<div class=\"hw\">obaerātus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://ob-\">ob-</a>/aes]</div><div class=\"def\">負債のある.</div><hr><div class=\"hw\">obaerātus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">債務者.</div>\r\n","<div class=\"hw\">obambulātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://obambulō\">obambulō</a>]</div><div class=\"def\">行き来.</div>\r\n","<div class=\"hw\">obambulō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>(<i>tr</i>)</div><div class=\"ori\">[ob-/ambulo]</div><div class=\"def\">(前・まわりを)うろつく, 歩きまわる 〈+<i>dat</i> [<i>acc</i>]〉.</div>\r\n","<div class=\"hw\">obarmō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[ob-/armo]</div><div class=\"def\">武装させる 〈alqd re〉.</div>\r\n","<div class=\"hw\">obarō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[ob-/aro]</div><div class=\"def\">すき返す, 掘り返す.</div>\r\n","<div class=\"hw\">obaudiō</div><div class=\"pos\">-īre -īvī -ītum, <i>intr</i></div><div class=\"ori\">[ob-/audio]</div><div class=\"def\">従う.</div>\r\n","<div class=\"hw\">obba</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">底の広い杯.</div>\r\n","<div class=\"hw\">Obba</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">オッバ《Carthago 付近の町》.</div>\r\n","<div class=\"hw\">obbrūtescō</div><div class=\"pos\">-ere -brūtuī, <i>intr</i></div><div class=\"ori\">[ob-/brutesco]</div><div class=\"def\">鈍くなる, 麻痺する.</div>\r\n","<div class=\"hw\">obbrūtuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obbrūtescō\">obbrutesco</a>.</div>\r\n","<div class=\"hw\">obc-</div><div class=\"def\">⇒occ-.</div>\r\n","<div class=\"hw\">obdidī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obdō\">obdo</a>.</div>\r\n","<div class=\"hw\">obditus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obdō\">obdo</a>.</div>\r\n","<div class=\"hw\">obdormiscō</div><div class=\"pos\">-ere -dormīvī, <i>intr inch</i></div><div class=\"ori\">[↑<a href=\"entry://obdormiō\">obdormiō</a>]</div><div class=\"def\">寝入る, 眠り込む.</div>\r\n","<div class=\"hw\">obdormiō</div><div class=\"pos\">-īre -īvī [-iī] -ītum, <i>intr</i>(<i>tr</i>)</div><div class=\"ori\">[ob-/dormio]</div><div class=\"def\">寝入る, 眠り込む.</div>\r\n","<div class=\"hw\">obdormīvī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obdormiō\">obdormio</a>, <a href=\"entry://obdormiscō\">obdormisco</a>.</div>\r\n","<div class=\"hw\">obductiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://obdūcō\">obdūcō</a>]</div><div class=\"def\">おおうこと.</div>\r\n","<div class=\"hw\">obduxī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obdūcō\">obduco</a>.</div>\r\n","<div class=\"hw\">obdō</div><div class=\"pos\">-ere -didī -ditum, <i>tr</i></div><div class=\"ori\">[ob-/<SUP>*</SUP>do(<i>cf</i>. abdo)]</div><div class=\"def\"><num>①</num> 間にはさむ 〈alci rei alqd〉</div><div class=\"ex\"><i>pessulum ostio obdere</i> (<author>T<small>ER</small></author>)<span class=\"ext\">扉にかんぬきを掛ける.</span></div><div class=\"def\"><num>②</num> (戸を)閉める, 戸締まりをする.</div><div class=\"def\"><num>③</num> 結わえる.</div><div class=\"def\"><num>④</num> (危険に)さらす.</div>\r\n","<div class=\"hw\">obdūcō</div><div class=\"pos\">-ere -duxī -ductum, <i>tr</i></div><div class=\"ori\">[ob-/duco]</div><div class=\"def\"><num>①</num> (...の方へ)導く, 率いる.</div><div class=\"def\"><num>②</num> 前方へ伸ばす[広げる]</div><div class=\"ex\"><i>obducere fossam</i> (<author>C<small>AES</small></author>)<span class=\"ext\">壕を掘り進める.</span></div><div class=\"def\"><num>③</num> (戸・かんぬきを)閉める.</div><div class=\"def\"><num>④</num> 間にはさむ</div><div class=\"ex\"><i>obducere posterum diem</i> (<author>C<small>IC</small></author>)<span class=\"ext\">滞在を一日延ばす.</span></div><div class=\"def\"><num>⑤</num> ふさぐ, さえぎる.</div><div class=\"def\"><num>⑥</num> おおう</div><div class=\"ex\"><i>obducta glacie humus</i> (<author>T<small>AC</small></author>)<span class=\"ext\">氷におおわれた地面.</span></div><div class=\"def\"><num>⑦</num> のみ込む, のみ干す.</div>\r\n","<div class=\"hw\">obdūrescō</div><div class=\"pos\">-ere -dūruī, <i>intr inch</i></div><div class=\"ori\">[↓<a href=\"entry://obdūrō\">obdūrō</a>]</div><div class=\"def\"><num>①</num> 堅くなる.</div><div class=\"def\"><num>②</num> 無感覚になる.</div>\r\n","<div class=\"hw\">obdūruī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obdūrescō\">obduresco</a>.</div>\r\n","<div class=\"hw\">obdūrātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[obduro]</div><div class=\"def\">強情, 頑固.</div>\r\n","<div class=\"hw\">obdūrō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>, <i>intr</i></div><div class=\"ori\">[ob-/duro]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>tr</i>)堅くする.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>intr</i>)固執する, 持ちこたえる.</div>\r\n","<div class=\"hw\">obeliscus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> オベリスク, 方尖柱.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> バラのつぼみ</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> =<a href=\"entry://obelus\">obelus</a>.</div>\r\n","<div class=\"hw\">obelus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(古代の写本中, 疑問の箇所に付けた)疑句標.</div>\r\n","<div class=\"hw\">obequitō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"ori\">[ob-/equito]</div><div class=\"def\">馬に乗って来る 〈+<i>dat</i>〉.</div>\r\n","<div class=\"hw\">oberrō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"ori\">[ob-/erro<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 歩きまわる, ぶらつく.</div><div class=\"def\"><num>②</num> (人の)じゃまをする.</div><div class=\"def\"><num>③</num> (目の前に)ちらつく.</div><div class=\"def\"><num>④</num> 誤る, 間違える.</div>\r\n","<div class=\"hw\">obesse</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://obsum\">obsum</a>.</div>\r\n","<div class=\"hw\">obex</div><div class=\"pos\">obicis, <i>m</i>, <i>f</i></div><div class=\"ori\">[obicio]</div><div class=\"def\"><num>①</num> かんぬき, 横木.</div><div class=\"def\"><num>②</num> 防塞.</div><div class=\"def\"><num>③</num> 障害物.</div>\r\n","<div class=\"hw\">obeō</div><div class=\"pos\">-īre -iī -itum, <i>tr</i>, <i>intr</i></div><div class=\"ori\">[ob-/eo<SUP>2</SUP>]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>tr</i>)</div><div class=\"def\"><num>①</num> 顔を合わせる, 会う.</div><div class=\"def\"><num>②</num> 巡回する, 訪問する.</div><div class=\"def\"><num>③</num> 調べる, 検査する;吟味する.</div><div class=\"def\"><num>④</num> 取り巻く, 囲む.</div><div class=\"def\"><num>⑤</num> 携わる, 取り組む</div><div class=\"ex\"><i>munia imperii obire</i> (<author>T<small>AC</small></author>)<span class=\"ext\">皇帝の責務を果たす.</span></div><div class=\"def\"><num>⑥</num> (約束の日に)現われる;出席する, 参加する.</div><div class=\"def\"><num>⑦</num> </div><div class=\"ex\"><i>obire mortem</i> [<i>diem supremum</i>] (<author>P<small>LAUT</small> [N<small>EP</small>]</author>)<span class=\"ext\">死ぬ.</span></div><div class=\"def\"><num0>Ⅱ</num0> (<i>intr</i>)</div><div class=\"def\"><num>①</num> 向かって行く.</div><div class=\"def\"><num>②</num> 死ぬ, 消滅する.</div><div class=\"def\"><num>③</num> (天体が)沈む.</div>\r\n","<div class=\"hw\">obf-</div><div class=\"def\">⇒off-.</div>\r\n","<div class=\"hw\">obfuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obsum\">obsum</a>.</div>\r\n","<div class=\"hw\">obg-</div><div class=\"def\">⇒ogg-.</div>\r\n","<div class=\"hw\">obhaerescō</div><div class=\"pos\">-ere -haesī, <i>intr inch</i></div><div class=\"ori\">[↑<a href=\"entry://obhaereō\">obhaereō</a>]</div><div class=\"def\">付着する, くっつく.</div>\r\n","<div class=\"hw\">obhaereō</div><div class=\"pos\">-ēre, <i>intr</i></div><div class=\"ori\">[ob-/haereo]</div><div class=\"def\">くっついている.</div>\r\n","<div class=\"hw\">obhaesī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obhaerescō\">obhaeresco</a>.</div>\r\n","<div class=\"hw\">obicere</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://obiciō\">obicio</a>.</div>\r\n","<div class=\"hw\">obiciō</div><div class=\"pos\">-ere -jēcī -jectum, <i>tr</i></div><div class=\"ori\">[ob-/jacio]</div><div class=\"def\"><num>①</num> 前へ投げる[置く];差し出す 〈alci alqd〉.</div><div class=\"def\"><num>②</num> (不幸・恐怖などを)もたらす, ひき起こす 〈alci alqd〉.</div><div class=\"def\"><num>③</num> (危険・不幸などに)さらす, あわせる 〈alqm alci rei〉.</div><div class=\"def\"><num>④</num> (<i>pass</i>)向かい合っている, 面している 〈+<i>dat</i>〉.</div><div class=\"def\"><num>⑤</num> 防壁[障害物]として前に置く;(戸を)閉める</div><div class=\"ex\"><i>objecta flumina</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">行く手をはばむ川.</span></div><div class=\"def\"><num>⑥</num> (部隊などを)対峙させる.</div><div class=\"def\"><num>⑦</num> (引合いに出して)責める, 非難する.</div>\r\n","<div class=\"hw\">obiens</div><div class=\"pos\">-euntis, <i>prp</i></div><div class=\"def\">⇒<a href=\"entry://obeō\">obeo</a>.</div>\r\n","<div class=\"hw\">obiter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[ob/iter]</div><div class=\"def\"><num>①</num> 途中で.</div><div class=\"def\"><num>②</num> ついでに, たまたま.</div><div class=\"def\"><num>③</num> 同時に.</div>\r\n","<div class=\"hw\">obitus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obeō\">obeo</a>.</div><hr><div class=\"hw\">obitus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 接近, 訪問.</div><div class=\"def\"><num>②</num> 死去;没落, 消滅.</div><div class=\"def\"><num>③</num> (天体が)沈むこと;日暮れ, 夕方.</div>\r\n","<div class=\"hw\">obiī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obeō\">obeo</a>.</div>\r\n","<div class=\"hw\">objaceō</div><div class=\"pos\">-ēre -jacuī, <i>intr</i></div><div class=\"ori\">[ob-/jaceo]</div><div class=\"def\"><num>①</num> そばに横たわっている, 向かい合っている 〈alci rei〉.</div><div class=\"def\"><num>②</num> さえぎる, 妨げる.</div>\r\n","<div class=\"hw\">objectiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[obicio]</div><div class=\"def\"><num>①</num> 前へ投げる[置く]こと.</div><div class=\"def\"><num>②</num> 非難.</div><div class=\"def\"><num>③</num> 反対, 異議を唱えること.</div>\r\n","<div class=\"hw\">objectum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://objectus\">objectus<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> 告発, 罪(名).</div><div class=\"def\"><num>②</num> 〘哲〙対象, 客体.</div>\r\n","<div class=\"hw\">objectus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obiciō\">obicio</a>.</div><hr><div class=\"hw\">objectus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 前へ置くこと, 対置.</div><div class=\"def\"><num>②</num> 障害物;抵抗.</div>\r\n","<div class=\"hw\">objectātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[objecto]</div><div class=\"def\">非難, 中傷.</div>\r\n","<div class=\"hw\">objectō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr freq</i></div><div class=\"ori\">[obicio]</div><div class=\"def\"><num>①</num> 前へ投げる[置く] 〈alci alqd〉.</div><div class=\"def\"><num>②</num> 突き出す, 突っ込む 〈alqd alci rei〉.</div><div class=\"def\"><num>③</num> (危険などに)さらす, あわせる 〈alqm alci rei〉.</div><div class=\"def\"><num>④</num> (引合いに出して)責める, 非難する.</div>\r\n","<div class=\"hw\">objex</div><div class=\"pos\">-jicis, <i>m</i>, <i>f</i></div><div class=\"def\">=<a href=\"entry://obex\">obex</a>.</div>\r\n","<div class=\"hw\">objiciō</div><div class=\"pos\">-ere, <i>tr</i></div><div class=\"def\">=<a href=\"entry://obiciō\">obicio</a>.</div>\r\n","<div class=\"hw\">objurgitō</div><div class=\"pos\">-āre, <i>tr freq</i></div><div class=\"ori\">[↓<a href=\"entry://objurgō\">objurgō</a>]</div><div class=\"def\">(激しく)非難[叱責]する.</div>\r\n","<div class=\"hw\">objurgātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[objurgo]</div><div class=\"def\">非難, 叱責.</div>\r\n","<div class=\"hw\">objurgātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[objurgo]</div><div class=\"def\">叱責[非難]する人.</div>\r\n","<div class=\"hw\">objurgātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://objurgō\">objurgo</a>.</div>\r\n","<div class=\"hw\">objurgātōrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://objurgātor\">objurgātor</a>]</div><div class=\"def\">叱責の, 非難をこめた.</div>\r\n","<div class=\"hw\">objurgō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[ob-/jurgo]</div><div class=\"def\"><num>①</num> 非難する, 叱責する, とがめる 〈alqm de re;alqd;quod〉.</div><div class=\"def\"><num>②</num> 罰する, 懲らす 〈re〉.</div><div class=\"def\"><num>③</num> 打つ, なぐる.</div>\r\n","<div class=\"hw\">objēcī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obiciō\">obicio</a>.</div>\r\n","<div class=\"hw\">oblanguescō</div><div class=\"pos\">-ere -languī, <i>intr</i></div><div class=\"ori\">[ob-/languesco]</div><div class=\"def\">生気[活気]のないものになる.</div>\r\n","<div class=\"hw\">oblanguī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://oblanguescō\">oblanguesco</a>.</div>\r\n","<div class=\"hw\">oblectāmen</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"def\">《詩》=<a href=\"entry://oblectāmentum\">oblectamentum</a>.</div>\r\n","<div class=\"hw\">oblectāmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[oblecto]</div><div class=\"def\">楽しみ, 娯楽.</div>\r\n","<div class=\"hw\">oblectātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[oblecto]</div><div class=\"def\">楽しませる[喜ばせる]こと.</div>\r\n","<div class=\"hw\">oblectātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[oblecto]</div><div class=\"def\">楽しませる[喜ばせる]者.</div>\r\n","<div class=\"hw\">oblectātōrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://oblectō\">oblectō</a>]</div><div class=\"def\">楽しませる, 喜ばせる.</div>\r\n","<div class=\"hw\">oblectō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[ob-/lacto<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 楽しませる, 喜ばせる.</div><div class=\"def\"><num>②</num> (時を)楽しく過ごす, (暇を)紛らす.</div>\r\n","<div class=\"hw\">obligātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[obligo]</div><div class=\"def\"><num>①</num> 保証.</div><div class=\"def\"><num>②</num> (法的・金銭的)義務.</div><div class=\"def\"><num>③</num> 債務証書.</div>\r\n","<div class=\"hw\">obligātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[↓<a href=\"entry://obligō\">obligō</a>]</div><div class=\"def\"><num>①</num> 義務を負っている.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 責任のある 〈+<i>gen</i>〉.</div><div class=\"def\"><num>③</num> 誓約した.</div>\r\n","<div class=\"hw\">obligātōrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[obligo]</div><div class=\"def\">(法的)義務を課する.</div>\r\n","<div class=\"hw\">obligō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[ob-/ligo<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 結びつける, つなぐ, 縛る.</div><div class=\"def\"><num>②</num> 包帯する.</div><div class=\"def\"><num>③</num> (法的・宗教的に)義務を負わせる, 拘束[束縛]する.</div><div class=\"def\"><num>④</num> 罪を帰する, 責を負わせる 〈alqm re〉.</div><div class=\"def\"><num>⑤</num> 質におく, 抵当[担保]に入れる 〈alci alqd〉.</div><div class=\"def\"><num>⑥</num> 恩義を施す, 義理を負わせる.</div>\r\n","<div class=\"hw\">oblinō</div><div class=\"pos\">-ere -lēvī -litum, <i>tr</i></div><div class=\"ori\">[ob-/lino]</div><div class=\"def\"><num>①</num> 塗りたくる, 塗りつける 〈alqm [alqd] re〉.</div><div class=\"def\"><num>②</num> (目張りをして容器の口・すきまなどを)ふさぐ.</div><div class=\"def\"><num>③</num> よごす;けがす;名誉を傷つける.</div><div class=\"def\"><num>④</num> 消す, 抹消する.</div><div class=\"def\"><num>⑤</num> 飽きあきさせる.</div>\r\n","<div class=\"hw\">oblitescō</div><div class=\"pos\">-ere -lituī, <i>intr</i></div><div class=\"ori\">[ob-/latesco<SUP>2</SUP>]</div><div class=\"def\">隠れる, 見えなくなる.</div>\r\n","<div class=\"hw\">oblitterātiō, oblīte-</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[oblittero]</div><div class=\"def\">忘れること, 忘却.</div>\r\n","<div class=\"hw\">oblitterātus, oblīte-</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://oblitterō\">oblittero</a>.</div>\r\n","<div class=\"hw\">oblitterō, oblīte-</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[ob-/littera]</div><div class=\"def\"><num>①</num> (こすって)消す, 抹消する.</div><div class=\"def\"><num>②</num> (記憶から)消し去る, 忘れさせる.</div><div class=\"def\"><num>③</num> すたれさせる.</div>\r\n","<div class=\"hw\">oblitus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://oblinō\">oblino</a>.</div>\r\n","<div class=\"hw\">oblituī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://oblitescō\">oblitesco</a>.</div>\r\n","<div class=\"hw\">oblocō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i></div><div class=\"def\">賃貸する.</div>\r\n","<div class=\"hw\">oblocūtor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[obloquor]</div><div class=\"def\">(人の)話の腰を折る人.</div>\r\n","<div class=\"hw\">oblocūtus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obloquor\">obloquor</a>.</div>\r\n","<div class=\"hw\">oblongulus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[↓<a href=\"entry://oblongus\">oblongus</a>]</div><div class=\"def\">(やや)細長い.</div>\r\n","<div class=\"hw\">oblongus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ob-/longus]</div><div class=\"def\">細長い.</div>\r\n","<div class=\"hw\">oblongātus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙<i>medulla oblongata</i> 延髄.</div>\r\n","<div class=\"hw\">obloquium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↓<a href=\"entry://obloquor\">obloquor</a>]</div><div class=\"def\">抗言, 反駁.</div>\r\n","<div class=\"hw\">obloquor</div><div class=\"pos\">-quī -locūtus sum, <i>intr</i>(<i>tr</i>)<i>dep</i></div><div class=\"ori\">[ob-/loquor]</div><div class=\"def\"><num>①</num> (人の)話をさえぎる, 話に割り込む;反駁する 〈alci〉.</div><div class=\"def\"><num>②</num> 非難[叱責]する.</div><div class=\"def\"><num>③</num> 《詩》(...に合わせて)歌う, 伴奏する.</div>\r\n","<div class=\"hw\">obloquī</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://obloquor\">obloquor</a>.</div>\r\n","<div class=\"hw\">obluctor</div><div class=\"pos\">-ārī -ātus sum, <i>intr dep</i></div><div class=\"ori\">[ob-/luctor]</div><div class=\"def\">逆らう, 抵抗する 〈+<i>dat</i>〉.</div>\r\n","<div class=\"hw\">oblāta</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[oblatus]</div><div class=\"def\">〘教会〙(<i>sc. </i> hostia)ホスチア, 聖体のパン.</div>\r\n","<div class=\"hw\">oblātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[offero]</div><div class=\"def\"><num>①</num> 提供, 贈呈.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>(競売の)入札.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 奉献, 奉納.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP> 進物, 贈り物.</div>\r\n","<div class=\"hw\">oblātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[offero]</div><div class=\"def\">提供者.</div>\r\n","<div class=\"hw\">oblātrātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[oblatro]</div><div class=\"def\">ののしること, 罵倒.</div>\r\n","<div class=\"hw\">oblātrātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[oblatro]</div><div class=\"def\">ののしる人.</div>\r\n","<div class=\"hw\">oblātrātrix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://oblātrātor\">oblātrātor</a>]</div><div class=\"def\">がみがみ女.</div>\r\n","<div class=\"hw\">oblātrō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>(<i>tr</i>)</div><div class=\"ori\">[ob-/latro<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> (犬が)吠えたてる.</div><div class=\"def\"><num>②</num> ののしる, わめく 〈alci;alqm〉.</div>\r\n","<div class=\"hw\">oblātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://offerō\">offero</a>.</div>\r\n","<div class=\"hw\">oblātīcius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[offero]</div><div class=\"def\">自発的に差し出された.</div>\r\n","<div class=\"hw\">oblātīvus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[offero]</div><div class=\"def\">自発的に与えられた.</div>\r\n","<div class=\"hw\">oblēniō</div><div class=\"pos\">-īre, <i>tr</i></div><div class=\"ori\">[ob-/lenio]</div><div class=\"def\">(怒り・気持ちを)和らげる, 静める.</div>\r\n","<div class=\"hw\">oblēvī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://oblinō\">oblino</a>.</div>\r\n","<div class=\"hw\">oblīcus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://oblīquus\">obliquus</a>.</div>\r\n","<div class=\"hw\">oblīdō</div><div class=\"pos\">-ere -līsī -līsum, <i>tr</i></div><div class=\"ori\">[ob-/laedo]</div><div class=\"def\"><num>①</num> (のどを)締めつける, 窒息させる.</div><div class=\"def\"><num>②</num> 押しつぶす.</div>\r\n","<div class=\"hw\">oblīmō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[ob-/limus<SUP>1</SUP>]</div><div class=\"def\">泥でふさぐ[おおう]</div><div class=\"ex\"><i>rem patris oblimare</i> (<author>H<small>OR</small></author>)<span class=\"ext\">父の財産を浪費する.</span></div>\r\n","<div class=\"hw\">oblīquitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[obliquus]</div><div class=\"def\">斜めであること, 傾斜, 勾配.</div>\r\n","<div class=\"hw\">oblīquus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> 斜めの, 傾斜した.</div><div class=\"def\"><num>②</num> 横目の.</div><div class=\"def\"><num>③</num> 横目で見る;ねたんでいる.</div><div class=\"def\"><num>④</num> (血統が)直系でない, 傍系の.</div><div class=\"def\"><num>⑤</num> 遠まわしの, 婉曲な.</div><div class=\"def\"><num>⑥</num> 〘文〙斜格の;間接的な;直説法現在時称以外の</div><div class=\"ex\"><i>casus ～</i> (<author>Q<small>UINT</small></author>)<span class=\"ext\">斜格.</span></div><div class=\"def\"><num>⑦</num> <SUP>◇</SUP>〘解〙(筋肉などが)斜めの.</div>\r\n","<div class=\"hw\">oblīquē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[obliquus]</div><div class=\"def\"><num>①</num> 斜めに.</div><div class=\"def\"><num>②</num> 横目で.</div><div class=\"def\"><num>③</num> 遠まわしに, それとなく.</div>\r\n","<div class=\"hw\">oblīquō<SUP>1</SUP></div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[obliquus]</div><div class=\"def\"><num>①</num> 斜めにする;ゆがめる.</div><div class=\"def\"><num>②</num> そらす, 転ずる.</div><div class=\"def\"><num>③</num> しらばくれる, 偽って言う.</div><hr><div class=\"hw\">oblīquō<SUP>2</SUP></div><div class=\"pos\"><i>adv</i>(<i>abl</i>)</div><div class=\"ori\">[↓<a href=\"entry://oblīquus\">oblīquus</a>]</div><div class=\"def\">斜めに.</div>\r\n","<div class=\"hw\">oblīsus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://oblīdō\">oblido</a>.</div>\r\n","<div class=\"hw\">oblīsī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://oblīdō\">oblido</a>.</div>\r\n","<div class=\"hw\">oblīterō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"def\">=<a href=\"entry://oblitterō\">oblittero</a>.</div>\r\n","<div class=\"hw\">oblītus<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://oblīviscor\">obliviscor</a>.</div>\r\n","<div class=\"hw\">oblīviscor</div><div class=\"pos\">-scī oblītus sum, <i>intr</i>, <i>tr dep</i></div><div class=\"def\"><num>①</num> 忘れる 〈+<i>gen</i> [<i>acc</i>];+<i>inf</i>;+<i>acc c.inf</i>〉.</div><div class=\"def\"><num>②</num> (故意に)記憶をぬぐい去る.</div><div class=\"def\"><num>③</num> (本分を)顧みない.</div><div class=\"def\"><num>④</num> 言及しないでおく.</div>\r\n","<div class=\"hw\">oblīviscī</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://oblīviscor\">obliviscor</a>.</div>\r\n","<div class=\"hw\">oblīvium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↑<a href=\"entry://oblīviscor\">oblīviscor</a>]</div><div class=\"def\">忘却.</div>\r\n","<div class=\"hw\">oblīvius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[oblivio]</div><div class=\"def\">忘れ去られた.</div>\r\n","<div class=\"hw\">oblīviō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[obliviscor]</div><div class=\"def\"><num>①</num> 忘れる[忘れられる]こと, 忘却.</div><div class=\"def\"><num>②</num> 大赦, 恩赦.</div><div class=\"def\"><num>③</num> (下界の)忘却の川(=<a href=\"entry://Lēthē\">Lethe</a>).</div><div class=\"def\"><num>④</num> <i>Flumen oblivionis</i> (<author>F<small>LOR</small></author>)(Hispania Tarraconensis の)Limia 川.</div>\r\n","<div class=\"hw\">oblīviōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://oblīviō\">oblīviō</a>]</div><div class=\"def\"><num>①</num> 忘れっぽい.</div><div class=\"def\"><num>②</num> 忘れさせる.</div>\r\n","<div class=\"hw\">oblūdiō</div><div class=\"pos\">-āre <i>intr</i></div><div class=\"ori\">[ob-/ludus]</div><div class=\"def\">ばかなまねをする, ふざける 〈alci〉.</div>\r\n","<div class=\"hw\">obmoveō</div><div class=\"pos\">-ēre -mōvī, <i>tr</i></div><div class=\"ori\">[ob-/moveo]</div><div class=\"def\">供え物をする.</div>\r\n","<div class=\"hw\">obmurmurō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"ori\">[ob-/murmuro]</div><div class=\"def\">(...に対して)つぶやく 〈alci〉.</div>\r\n","<div class=\"hw\">obmōlior</div><div class=\"pos\">-īrī -ītus sum, <i>tr dep</i></div><div class=\"ori\">[ob-/molior]</div><div class=\"def\"><num>①</num> 障害物として前へ置く.</div><div class=\"def\"><num>②</num> (防壁の破れ目を)ふさぐ.</div>\r\n","<div class=\"hw\">obmūtescō</div><div class=\"pos\">-ere -mūtuī, <i>intr</i></div><div class=\"ori\">[ob-/mutus]</div><div class=\"def\"><num>①</num> 口がきけなくなる;黙る, 沈黙する.</div><div class=\"def\"><num>②</num> やむ, 静まる.</div>\r\n","<div class=\"hw\">obmūtuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obmūtescō\">obmutesco</a>.</div>\r\n","<div class=\"hw\">obnixus, -nīsus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[obnitor]</div><div class=\"def\">断固とした.</div>\r\n","<div class=\"hw\">obnixē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://obnixus\">obnixus, -nīsus</a>]</div><div class=\"def\">全力を出して, 断固として.</div>\r\n","<div class=\"hw\">obnoxius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> 恩に縛られた, 義理のある;(法的に)責任のある.</div><div class=\"def\"><num>②</num> (悪事などに)ふけっている 〈alci rei〉.</div><div class=\"def\"><num>③</num> (害・危険などに)さらされた, 陥りやすい 〈alci rei〉.</div><div class=\"def\"><num>④</num> 服従[従属]する;屈従的な, 卑屈な 〈+<i>dat</i>〉.</div>\r\n","<div class=\"hw\">obnoxiē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[obnoxius]</div><div class=\"def\"><num>①</num> 罪を犯して.</div><div class=\"def\"><num>②</num> 卑屈に, 屈従的に.</div>\r\n","<div class=\"hw\">obnoxiētās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[obnoxius]</div><div class=\"def\">義務, 責務.</div>\r\n","<div class=\"hw\">obnoxiōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://obnoxius\">obnoxius</a>]</div><div class=\"def\"><num>①</num> 服従[従属]する.</div><div class=\"def\"><num>②</num> 有害な, 危険な.</div>\r\n","<div class=\"hw\">obnoxiōsē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://obnoxiōsus\">obnoxiōsus</a>]</div><div class=\"def\">おずおずと, びくびくして.</div>\r\n","<div class=\"hw\">obnuntiātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://obnuntiō\">obnuntiō</a>]</div><div class=\"def\">凶兆を告げること.</div>\r\n","<div class=\"hw\">obnuntiō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>, <i>intr</i></div><div class=\"ori\">[ob-/nuntio]</div><div class=\"def\"><num>①</num> 凶兆を告げる.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 悪い知らせをもたらす.</div>\r\n","<div class=\"hw\">obnupsī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obnūbō\">obnubo</a>.</div>\r\n","<div class=\"hw\">obnuptus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obnūbō\">obnubo</a>.</div>\r\n","<div class=\"hw\">obnātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ob-/natus<SUP>1</SUP>]</div><div class=\"def\">そばに生えている 〈alci rei〉.</div>\r\n","<div class=\"hw\">obnīsus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">=<a href=\"entry://obnixus\">obnixus</a>(⇒ <a href=\"entry://obnītor\">obnitor</a>).</div><hr><div class=\"hw\">obnīsus<SUP>2</SUP></div><div class=\"pos\">-ūs, <SUP>◇</SUP><i>m</i></div><div class=\"def\">努力, 骨折り.</div>\r\n","<div class=\"hw\">obnītor</div><div class=\"pos\">-tī -nixus</div><div class=\"ori\">[-nīsus]</div><div class=\"def\">sum, <i>intr dep</i></div><div class=\"def\"><num>①</num> 押しつける 〈+<i>dat</i>〉.</div><div class=\"def\"><num>②</num> 逆らう, 抵抗する.</div><div class=\"def\"><num>③</num> 苦闘する 〈+<i>inf</i>〉.</div>\r\n","<div class=\"hw\">obnītī</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://obnītor\">obnitor</a>.</div>\r\n","<div class=\"hw\">obnūbilus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ob-/nubilus]</div><div class=\"def\">曇った, 暗い.</div>\r\n","<div class=\"hw\">obnūbilātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://obnūbilō\">obnūbilō</a>]</div><div class=\"def\">〘病〙朦朧<SUB>もうろう</SUB>.</div>\r\n","<div class=\"hw\">obnūbilō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[ob-/nubilo]</div><div class=\"def\">曇らせる, 暗くする</div><div class=\"ex\"><i>obnubilare animam</i> (<author>A<small>PUL</small></author>)<span class=\"ext\">失神する, 気が遠くなる.</span></div>\r\n","<div class=\"hw\">obnūbō</div><div class=\"pos\">-ere -nupsī -nuptum, <i>tr</i></div><div class=\"ori\">[ob-/nubo]</div><div class=\"def\">おおう, 包む.</div>\r\n","<div class=\"hw\">oboediens</div><div class=\"pos\">-entis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[oboedio]</div><div class=\"def\">服従する, 従順な 〈+<i>dat</i>〉.</div>\r\n","<div class=\"hw\">oboedienter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://oboediens\">oboediens</a>]</div><div class=\"def\">従順に.</div>\r\n","<div class=\"hw\">oboedientia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[oboediens]</div><div class=\"def\">服従, 従順.</div>\r\n","<div class=\"hw\">oboediō</div><div class=\"pos\">-īre -īvī [-iī] -ītum, <i>intr</i></div><div class=\"ori\">[ob-/audio]</div><div class=\"def\"><num>①</num> 耳を傾ける.</div><div class=\"def\"><num>②</num> 服従する, 従順である 〈+<i>dat</i>〉.</div>\r\n","<div class=\"hw\">oboleō</div><div class=\"pos\">-ēre -oluī, <i>intr</i>, <i>tr</i></div><div class=\"ori\">[ob-/oleo]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>intr</i>)匂いがする, 匂う.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>tr</i>)匂わせる 〈alqd〉.</div>\r\n","<div class=\"hw\">obolus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 古代ギリシアの銀貨(=<img class=\"font\" src=\"img/B154.png\"> drachma).</div><div class=\"def\"><num>②</num> 古代ギリシアの重量単位(=<img class=\"font\" src=\"img/B154.png\"> drachma).</div>\r\n","<div class=\"hw\">oborior</div><div class=\"pos\">-īrī -ortus sum, <i>intr dep</i></div><div class=\"ori\">[ob-/orior]</div><div class=\"def\"><num>①</num> のぼる.</div><div class=\"def\"><num>②</num> 現われる, 起こる.</div>\r\n","<div class=\"hw\">obortus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://oborior\">oborior</a>.</div>\r\n","<div class=\"hw\">obp-</div><div class=\"def\">⇒opp-.</div>\r\n","<div class=\"hw\">obrepsī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obrēpō\">obrepo</a>.</div>\r\n","<div class=\"hw\">obreptiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[obrepo]</div><div class=\"def\"><num>①</num> 忍び寄ること, 不意を突くこと.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 詐取.</div>\r\n","<div class=\"hw\">obreptus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obrēpō\">obrepo</a>.</div>\r\n","<div class=\"hw\">obreptō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr freq</i></div><div class=\"ori\">[obrepo]</div><div class=\"def\">忍び寄る, そっと近づく.</div>\r\n","<div class=\"hw\">obrigescō</div><div class=\"pos\">-ere -riguī, <i>intr inch</i></div><div class=\"ori\">[↑<a href=\"entry://obrigeō\">obrigeō</a>]</div><div class=\"def\"><num>①</num> 堅くなる, 硬直する, 凍結する.</div><div class=\"def\"><num>②</num> (乳が)凝固する.</div>\r\n","<div class=\"hw\">obrigeō</div><div class=\"pos\">-ēre, <SUP>◇</SUP><i>intr</i></div><div class=\"def\">硬直している.</div>\r\n","<div class=\"hw\">obriguī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obrigescō\">obrigesco</a>.</div>\r\n","<div class=\"hw\">Obrima</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オブリマ, <SUP>*</SUP>-モス《Phrygia の川;Maeander 川の支流》.</div>\r\n","<div class=\"hw\">obrogātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://obrogō\">obrogō</a>]</div><div class=\"def\">(現行法の)修正, 廃止.</div>\r\n","<div class=\"hw\">obrogō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>, <i>intr</i></div><div class=\"ori\">[ob-/rogo]</div><div class=\"def\"><num>①</num> (現行法を新法によって)修正[廃止]する.</div><div class=\"def\"><num>②</num> (法案の)通過を妨害する 〈+<i>dat</i>〉.</div>\r\n","<div class=\"hw\">obrussa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 試金</div><div class=\"ex\"><i>aurum ad obrussam</i> (<author>S<small>UET</small></author>)<span class=\"ext\">るつぼで試金された金, 純金.</span></div><div class=\"def\"><num>②</num> 試金石.</div>\r\n","<div class=\"hw\">obrutus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obruō\">obruo</a>.</div>\r\n","<div class=\"hw\">obruī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obruō\">obruo</a>.</div>\r\n","<div class=\"hw\">obruō</div><div class=\"pos\">-ere -ruī -rutum, <i>tr</i>, <i>intr</i></div><div class=\"ori\">[ob-/ruo]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>tr</i>)</div><div class=\"def\"><num>①</num> おおう, 包む, 隠す 〈alqd re〉.</div><div class=\"def\"><num>②</num> 埋める, 沈める.</div><div class=\"def\"><num>③</num> 押しつぶす, 打ちのめす;圧倒する.</div><div class=\"def\"><num>④</num> (忘却の中に)埋もれさせる.</div><div class=\"def\"><num>⑤</num> 影をうすくさせる, 効力を失わせる</div><div class=\"ex\"><i>obruere famam alcis</i> (<author>T<small>AC</small></author>)<span class=\"ext\">ある人の名声をしのぐ.</span></div><div class=\"def\"><num0>Ⅱ</num0> (<i>intr</i>)瓦解[崩壊]する.</div>\r\n","<div class=\"hw\">obryzum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(<i>sc. </i> aurum)純金.</div>\r\n","<div class=\"hw\">obrēpō</div><div class=\"pos\">-ere -repsī -reptum, <i>intr</i>(<i>tr</i>)</div><div class=\"ori\">[ob-/repo]</div><div class=\"def\"><num>①</num> 忍び寄る, そっと近づく 〈+<i>dat</i> [<i>acc</i>]〉.</div><div class=\"def\"><num>②</num> 突然訪れる.</div>\r\n","<div class=\"hw\">obrētiō</div><div class=\"pos\">-īre -īvī -ītum, <i>tr</i></div><div class=\"ori\">[ob-/rete]</div><div class=\"def\">網で捕える.</div>\r\n","<div class=\"hw\">obrōdō</div><div class=\"pos\">-ere, <i>tr</i></div><div class=\"ori\">[ob-/rodo]</div><div class=\"def\">かじる.</div>\r\n","<div class=\"hw\">obsaepiō, -sēpiō, -sīpiō</div><div class=\"pos\">-īre -saepsī -saeptum, <i>tr</i></div><div class=\"ori\">[ob-/saepio]</div><div class=\"def\"><num>①</num> 囲い込む, 閉じ込める.</div><div class=\"def\"><num>②</num> ふさぐ, 遮断する.</div>\r\n","<div class=\"hw\">obsaepsī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obsaepiō\">obsaepio</a>.</div>\r\n","<div class=\"hw\">obsaeptus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obsaepiō\">obsaepio</a>.</div>\r\n","<div class=\"hw\">obsaturō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"ori\">[ob-/saturo]</div><div class=\"def\">飽きあきさせる.</div>\r\n","<div class=\"hw\">obscaen-</div><div class=\"def\">⇒obscen-.</div>\r\n","<div class=\"hw\">obscaevō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"ori\">[ob-/scaeva]</div><div class=\"def\">吉兆[凶兆]を示す.</div>\r\n","<div class=\"hw\">obscoen-</div><div class=\"def\">⇒obscen-.</div>\r\n","<div class=\"hw\">Obscus, Opscus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">《古形》=<a href=\"entry://Oscus\">Oscus</a>.</div>\r\n","<div class=\"hw\">obscēna</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[obscenus<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 排泄物, 尿.</div><div class=\"def\"><num>②</num> 陰部.</div><div class=\"def\"><num>③</num> みだらな行為[ことば].</div>\r\n","<div class=\"hw\">obscēnitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[obscenus<SUP>1</SUP>]</div><div class=\"def\">猥褻[下品](な行為).</div>\r\n","<div class=\"hw\">obscēnum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://obscēnus\">obscēnus<SUP>1</SUP></a>]</div><div class=\"def\">陰部(=<a href=\"entry://obscēna\">obscena</a>).</div>\r\n","<div class=\"hw\">obscēnus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> 縁起の悪い, 不吉な.</div><div class=\"def\"><num>②</num> けがらわしい, 忌まわしい.</div><div class=\"def\"><num>③</num> 卑猥な, みだらな, 下品な.</div><hr><div class=\"hw\">obscēnus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 放蕩者, 好色漢.</div><div class=\"def\"><num>②</num> 下品なことばを使う者.</div>\r\n","<div class=\"hw\">obscēnē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[obscenus<SUP>1</SUP>]</div><div class=\"def\">下品に, みだらに.</div>\r\n","<div class=\"hw\">obscūritās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[obscurus]</div><div class=\"def\"><num>①</num> 暗黒, 暗さ.</div><div class=\"def\"><num>②</num> 不分明, 不明瞭.</div><div class=\"def\"><num>③</num> 世に知られないこと;卑賤, 無名.</div>\r\n","<div class=\"hw\">obscūrum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://obscūrus\">obscūrus</a>]</div><div class=\"def\"><num>①</num> 暗さ.</div><div class=\"def\"><num>②</num> 薄明かり.</div>\r\n","<div class=\"hw\">obscūrus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> 暗い, うす暗い.</div><div class=\"def\"><num>②</num> かすかに見える;(色が)黒ずんだ.</div><div class=\"def\"><num>③</num> (表情が)陰気な, 陰鬱な.</div><div class=\"def\"><num>④</num> おおわれた, 隠れた.</div><div class=\"def\"><num>⑤</num> (音が)不明瞭な.</div><div class=\"def\"><num>⑥</num> 目立たない, 世に知られない, 無名の.</div><div class=\"def\"><num>⑦</num> 不確かな, 判然としない.</div><div class=\"def\"><num>⑧</num> 知られていない, 公けにされていない.</div><div class=\"def\"><num>⑨</num> 率直でない, 隠しだてする.</div><div class=\"def\"><num>⑩</num> わかりにくい, 不分明な.</div>\r\n","<div class=\"hw\">obscūrātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[obscuro]</div><div class=\"def\"><num>①</num> 暗くなること.</div><div class=\"def\"><num>②</num> (太陽・月の)食.</div><div class=\"def\"><num>③</num> 見えなくなること.</div>\r\n","<div class=\"hw\">obscūrātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obscūrō\">obscuro</a>.</div>\r\n","<div class=\"hw\">obscūrē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[obscurus]</div><div class=\"def\"><num>①</num> ぼんやりと, 不明瞭に.</div><div class=\"def\"><num>②</num> (表現が)あいまいに, 不明確に.</div><div class=\"def\"><num>③</num> こっそり, ひそかに.</div><div class=\"def\"><num>④</num> 目立たずに, 世に知られずに.</div>\r\n","<div class=\"hw\">obscūrō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[obscurus]</div><div class=\"def\"><num>①</num> 暗くする, おおい隠す.</div><div class=\"def\"><num>②</num> 隠す, 知られないようにする.</div><div class=\"def\"><num>③</num> (目・心を)曇らせる, かすませる.</div><div class=\"def\"><num>④</num> 目立たなくする, 影をうすくさせる.</div><div class=\"def\"><num>⑤</num> 不分明[不明瞭]にする.</div><div class=\"def\"><num>⑥</num> 忘れさせる.</div>\r\n","<div class=\"hw\">obsecrātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[obsecro]</div><div class=\"def\"><num>①</num> 懇願, 嘆願.</div><div class=\"def\"><num>②</num> 祈祷式.</div>\r\n","<div class=\"hw\">obsecrātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↓<a href=\"entry://obsecrō\">obsecrō</a>]</div><div class=\"def\">嘆願者.</div>\r\n","<div class=\"hw\">obsecrō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[ob-/sacro]</div><div class=\"def\"><num>①</num> 懇願[嘆願]する 〈alqm;ut, ne〉.</div><div class=\"def\"><num>②</num> (挿入句として)どうか, お願いです</div><div class=\"ex\"><i>pergite, ～, continuo</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">頼むから, 続けてやってくれ.</span></div>\r\n","<div class=\"hw\">obsecundō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"ori\">[ob-/secundo<SUP>1</SUP>]</div><div class=\"def\">(人の望みに)応ずる, 同意する;(...の)動きに合わせる 〈+<i>dat</i>〉.</div>\r\n","<div class=\"hw\">obsecūtus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obsequor\">obsequor</a>.</div>\r\n","<div class=\"hw\">obsequens</div><div class=\"pos\">-entis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[obsequor]</div><div class=\"def\"><num>①</num> (人の望みに)応ずる, 従順な 〈+<i>dat</i>〉.</div><div class=\"def\"><num>②</num> (神々が)好意的な, 慈悲深い.</div>\r\n","<div class=\"hw\">obsequenter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://obsequens\">obsequens</a>]</div><div class=\"def\">従順に.</div>\r\n","<div class=\"hw\">obsequentia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[obsequens]</div><div class=\"def\">(人の望み・意向などに)応ずること, 従順.</div>\r\n","<div class=\"hw\">obsequiae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"ori\">[obsequor]</div><div class=\"def\">《碑》葬儀(=<a href=\"entry://exsequiae\">exsequiae</a>).</div>\r\n","<div class=\"hw\">obsequibilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[obsequor]</div><div class=\"def\">親切な.</div>\r\n","<div class=\"hw\">obsequium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://obsequor\">obsequor</a>]</div><div class=\"def\"><num>①</num> (要求などに)応ずること, 従順</div><div class=\"ex\">～ <i>ventris</i> (<author>H<small>OR</small></author>)<span class=\"ext\">大食.</span></div><div class=\"def\"><num>②</num> 忠誠, 恭順.</div>\r\n","<div class=\"hw\">obsequiōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://obsequium\">obsequium</a>]</div><div class=\"def\">従順な.</div>\r\n","<div class=\"hw\">obsequor</div><div class=\"pos\">-quī -secūtus sum, <i>intr dep</i></div><div class=\"ori\">[ob-/sequor]</div><div class=\"def\"><num>①</num> (要求・命令などに)従う, 応ずる 〈+<i>dat</i>〉.</div><div class=\"def\"><num>②</num> 専心する, ふける.</div>\r\n","<div class=\"hw\">obsequēla, -ella</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[obsequor]</div><div class=\"def\">(人の望みに)応ずること, 従順.</div>\r\n","<div class=\"hw\">obsequī</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://obsequor\">obsequor</a>.</div>\r\n","<div class=\"hw\">observans</div><div class=\"pos\">-antis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[observo]</div><div class=\"def\"><num>①</num> 気を遣う, 敬意を表する 〈+<i>gen</i>〉.</div><div class=\"def\"><num>②</num> きちょうめんな, 遵守する 〈+<i>gen</i>〉.</div>\r\n","<div class=\"hw\">observanter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://observans\">observans</a>]</div><div class=\"def\">注意深く, きちょうめんに.</div>\r\n","<div class=\"hw\">observantia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[observans]</div><div class=\"def\"><num>①</num> 観察, 注目.</div><div class=\"def\"><num>②</num> 敬意, 配慮.</div><div class=\"def\"><num>③</num> 遵奉, 遵守.</div>\r\n","<div class=\"hw\">observitō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr freq</i></div><div class=\"ori\">[↓<a href=\"entry://observō\">observō</a>]</div><div class=\"def\"><num>①</num> (注意深く)観察する.</div><div class=\"def\"><num>②</num> 注意する, 顧慮する.</div><div class=\"def\"><num>③</num> (儀式を)挙行[執行]する.</div>\r\n","<div class=\"hw\">observābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[observo]</div><div class=\"def\"><num>①</num> 観察できる, 目に見える.</div><div class=\"def\"><num>②</num> 著しい.</div><div class=\"def\"><num>③</num> 遵守する.</div>\r\n","<div class=\"hw\">observātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[observo]</div><div class=\"def\"><num>①</num> 観察, 注目.</div><div class=\"def\"><num>②</num> 見張り, 監視.</div><div class=\"def\"><num>③</num> 遵奉, 遵守.</div><div class=\"def\"><num>④</num> 慣例, 慣行.</div><div class=\"def\"><num>⑤</num> 評言, 所見.</div><div class=\"def\"><num>⑥</num> 敬意.</div>\r\n","<div class=\"hw\">observātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[observo]</div><div class=\"def\"><num>①</num> 観察[監視]者.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 遵奉者.</div>\r\n","<div class=\"hw\">observātrix</div><div class=\"pos\">-īcis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↑<a href=\"entry://observātor\">observātor</a>]</div><div class=\"def\">遵守[遵奉]者《女性》.</div>\r\n","<div class=\"hw\">observātē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[observo]</div><div class=\"def\">注意深く.</div>\r\n","<div class=\"hw\">observō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[ob-/servo]</div><div class=\"def\"><num>①</num> 観察する, 注目する.</div><div class=\"def\"><num>②</num> 監視する, 見張る, 用心する.</div><div class=\"def\"><num>③</num> 向かう, 面する 〈alqd〉.</div><div class=\"def\"><num>④</num> 待ち構える, 待ち受ける.</div><div class=\"def\"><num>⑤</num> 尊重する, 尊敬を払う.</div><div class=\"def\"><num>⑥</num> (規則・慣例などを)守る, 遵守する, 従う;(儀式を)挙行[執行]する.</div><div class=\"def\"><num>⑦</num> (...であると)みなす.</div>\r\n","<div class=\"hw\">obserō<SUP>1</SUP></div><div class=\"pos\">-ere -sēvī -situm, <i>tr</i></div><div class=\"ori\">[ob-/sero<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> (種を)まく.</div><div class=\"def\"><num>②</num> (災難を)生じさせる.</div><hr><div class=\"hw\">obserō<SUP>2</SUP></div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[ob-/sero<SUP>3</SUP>]</div><div class=\"def\"><num>①</num> (戸などに)かんぬきを掛ける, 閉ざす.</div><div class=\"def\"><num>②</num> ふさぐ, さえぎる.</div>\r\n","<div class=\"hw\">obses</div><div class=\"pos\">obsidis, <i>m</i>(<i>f</i>)</div><div class=\"ori\">[ob-/sedeo]</div><div class=\"def\"><num>①</num> 人質.</div><div class=\"def\"><num>②</num> 保証, 抵当.</div>\r\n","<div class=\"hw\">obsessiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"def\">=<a href=\"entry://obsidiō\">obsidio</a>.</div>\r\n","<div class=\"hw\">obsessor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[obsideo]</div><div class=\"def\"><num>①</num> (ある場所を)占拠する者.</div><div class=\"def\"><num>②</num> 包囲[封鎖]者.</div>\r\n","<div class=\"hw\">obsessus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obsideō\">obsideo</a>, <a href=\"entry://obsīdō\">obsido</a>.</div>\r\n","<div class=\"hw\">obsideō</div><div class=\"pos\">-ēre -sēdī -sessum, <i>intr</i>, <i>tr</i></div><div class=\"ori\">[ob-/sedeo]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>intr</i>)すわる, 場所を占める.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>tr</i>)</div><div class=\"def\"><num>①</num> 住む, 占有[占拠]する.</div><div class=\"def\"><num>②</num> 占める, 支配する.</div><div class=\"def\"><num>③</num> 奪取する.</div><div class=\"def\"><num>④</num> 包囲[攻囲]する, 封鎖する.</div><div class=\"def\"><num>⑤</num> 圧迫する, 悩ます, 襲う.</div><div class=\"def\"><num>⑥</num> 厚くおおう, 取り囲む.</div><div class=\"def\"><num>⑦</num> 見張る, 機会をうかがう</div><div class=\"ex\"><i>qui meum tempus obsidet</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私の時間を(取り上げようと)見張っている人(=私のじゃまをする人).</span></div>\r\n","<div class=\"hw\">obsidior</div><div class=\"pos\">-ārī, <i>intr dep</i></div><div class=\"ori\">[↓<a href=\"entry://obsidium\">obsidium<SUP>1</SUP></a>]</div><div class=\"def\">待伏せする 〈+<i>dat</i>〉.</div>\r\n","<div class=\"hw\">obsidium<SUP>1</SUP></div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[obsideo]</div><div class=\"def\"><num>①</num> 包囲, 攻囲, 封鎖.</div><div class=\"def\"><num>②</num> 注意深く見守ること.</div><div class=\"def\"><num>③</num> 待伏せ.</div><div class=\"def\"><num>④</num> (差し迫った)危険.</div><hr><div class=\"hw\">obsidium<SUP>2</SUP></div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[obses]</div><div class=\"def\">人質であること.</div>\r\n","<div class=\"hw\">obsidiālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">=<a href=\"entry://obsidiōnālis\">obsidionalis</a>.</div>\r\n","<div class=\"hw\">obsidiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[obsideo]</div><div class=\"def\"><num>①</num> 包囲, 攻囲, 封鎖.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 捕われの状態.</div><div class=\"def\"><num>③</num> 差し迫った危険.</div>\r\n","<div class=\"hw\">obsidiōnālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://obsidiō\">obsidiō</a>]</div><div class=\"def\">包囲[攻囲]の, 封鎖の</div><div class=\"ex\"><i>corona ～</i> (<author>L<small>IV</small></author>)<span class=\"ext\">攻囲軍を撃退して包囲を解いた指揮官に与えられる冠.</span></div>\r\n","<div class=\"hw\">obsignātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[obsigno]</div><div class=\"def\">認印を押すこと, 封印.</div>\r\n","<div class=\"hw\">obsignātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://obsignō\">obsignō</a>]</div><div class=\"def\">封印した人;(特に, 遺言状の)封印の証人.</div>\r\n","<div class=\"hw\">obsignō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[ob-/signo]</div><div class=\"def\"><num>①</num> 認印を押す, 封印する.</div><div class=\"def\"><num>②</num> 銘記する, 感銘を与える.</div>\r\n","<div class=\"hw\">obsipō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"ori\">[ob-/supo]</div><div class=\"def\">まきちらす, 振りかける</div><div class=\"ex\"><i>obsipat aquolam</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">《諺》元気が出る, 気分が晴れる.</span></div>\r\n","<div class=\"hw\">obsistō</div><div class=\"pos\">-ere -stitī -stitum, <i>intr</i></div><div class=\"ori\">[ob-/sisto]</div><div class=\"def\"><num>①</num> 立ちはだかる, 道をふさぐ 〈+<i>dat</i>〉.</div><div class=\"def\"><num>②</num> 抵抗する, 逆らう.</div><div class=\"def\"><num>③</num> じゃまをする, 妨害する 〈quominus, quin, ne〉.</div>\r\n","<div class=\"hw\">obsitus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[obsero<SUP>1</SUP>]</div><div class=\"def\">おおわれた, 包まれた 〈re〉.</div>\r\n","<div class=\"hw\">obsolefacere</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://obsolefaciō\">obsolefacio</a>.</div>\r\n","<div class=\"hw\">obsolefaciō</div><div class=\"pos\">-cere -fēcī -factum, <i>tr</i></div><div class=\"ori\">[obsolesco/facio]</div><div class=\"def\"><num>①</num> そこねる.</div><div class=\"def\"><num>②</num> 品位[価値]を低下させる, おとしめる.</div>\r\n","<div class=\"hw\">obsolefactus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obsolefaciō\">obsolefacio</a>, <a href=\"entry://obsolefīō\">obsolefio</a>.</div>\r\n","<div class=\"hw\">obsolefierī</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://obsolefīō\">obsolefio</a>.</div>\r\n","<div class=\"hw\">obsolefēcī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obsolefaciō\">obsolefacio</a>.</div>\r\n","<div class=\"hw\">obsolefīō</div><div class=\"pos\">-fierī -factus sum, <i>intr</i></div><div class=\"def\">(<a href=\"entry://obsolefaciō\">obsolefacio</a> の <i>pass</i> として用いられる).</div>\r\n","<div class=\"hw\">obsolescō</div><div class=\"pos\">-ere -solēvī -solētum, <i>intr</i></div><div class=\"ori\">[ob-/soleo]</div><div class=\"def\"><num>①</num> すたれる, 効力を失う, 衰微する.</div><div class=\"def\"><num>②</num> おとしめられる, 価値が低下する.</div>\r\n","<div class=\"hw\">obsolētus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[obsolesco]</div><div class=\"def\"><num>①</num> 使い古した, すりきれた, ぼろぼろの.</div><div class=\"def\"><num>②</num> ぼろをまとった, みすぼらしい.</div><div class=\"def\"><num>③</num> (色が)くすんだ, 黒ずんだ.</div><div class=\"def\"><num>④</num> 陳腐な, ありきたりの.</div><div class=\"def\"><num>⑤</num> 世に忘れられた, おちぶれた.</div>\r\n","<div class=\"hw\">obsolētē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://obsolētus\">obsolētus</a>]</div><div class=\"def\">みすぼらしく.</div>\r\n","<div class=\"hw\">obsolēvī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obsolescō\">obsolesco</a>.</div>\r\n","<div class=\"hw\">obsonō<SUP>2</SUP></div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"ori\">[ob-/sono]</div><div class=\"def\">(口をはさんで)人の話のじゃまをする.</div>\r\n","<div class=\"hw\">obsorbeō</div><div class=\"pos\">-ēre -uī, <i>tr</i></div><div class=\"ori\">[ob-/sorbeo]</div><div class=\"def\"><num>①</num> ぐいとのむ, のみ込む.</div><div class=\"def\"><num>②</num> 吸い込む.</div>\r\n","<div class=\"hw\">obstantia<SUP>1</SUP></div><div class=\"pos\">-ium, <i>n pl</i></div><div class=\"ori\">[obsto]</div><div class=\"def\">障害(物).</div><hr><div class=\"hw\">obstantia<SUP>2</SUP></div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">抵抗, 妨害.</div>\r\n","<div class=\"hw\">obstetrix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"ori\">[obsto]</div><div class=\"def\">産婆, 助産婦.</div>\r\n","<div class=\"hw\">obstetrīcia</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://obstetrix\">obstetrix</a>]</div><div class=\"def\">(<i>sc. </i> officia)〘医〙産婆術;産科学(=<a href=\"entry://tocologia\">tocologia</a>).</div>\r\n","<div class=\"hw\">obstinātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[obstino]</div><div class=\"def\">不屈, 頑固.</div>\r\n","<div class=\"hw\">obstinātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[↓<a href=\"entry://obstinō\">obstinō</a>]</div><div class=\"def\">断固とした, 不屈の, 頑固な 〈ad alqd;+<i>inf</i>〉</div><div class=\"ex\"><i>obstinati mori</i> (<author>L<small>IV</small></author>)<span class=\"ext\">決死の覚悟をしている男たち.</span></div>\r\n","<div class=\"hw\">obstinātē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[obstinatus]</div><div class=\"def\">頑強に.</div>\r\n","<div class=\"hw\">obstinō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>(<i>intr</i>)</div><div class=\"ori\">[ob-/<SUP>*</SUP>stano(<i>cf</i>. sto)]</div><div class=\"def\">固く決心する, 固執する 〈alqd;ad alqd;+<i>inf</i>〉.</div>\r\n","<div class=\"hw\">obstipescō</div><div class=\"pos\">-ere, <i>intr</i>(<i>tr</i>)</div><div class=\"def\">=<a href=\"entry://obstupescō\">obstupesco</a>.</div>\r\n","<div class=\"hw\">obstita</div><div class=\"pos\">-ōrum, <i>n pl</i>(<i>pp</i>)</div><div class=\"ori\">[obsisto]</div><div class=\"def\">雷に撃たれたもの.</div>\r\n","<div class=\"hw\">obstitus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obsistō\">obsisto</a>.</div>\r\n","<div class=\"hw\">obstitī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obsistō\">obsisto</a>, <a href=\"entry://obstō\">obsto</a>.</div>\r\n","<div class=\"hw\">obstrepitus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obstrepō\">obstrepo</a>.</div>\r\n","<div class=\"hw\">obstrepuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obstrepō\">obstrepo</a>.</div>\r\n","<div class=\"hw\">obstrepō</div><div class=\"pos\">-ere -strepuī -strepitum, <i>intr</i>(<i>tr</i>)</div><div class=\"ori\">[ob-/strepo]</div><div class=\"def\"><num>①</num> 大声を出して妨げる[かき消す], (対抗して)大きな音を立てる 〈+<i>dat</i>〉</div><div class=\"ex\"><i>tympana et plausus obstrepuerunt sono citharae</i> (<author>O<small>V</small></author>)<span class=\"ext\">太鼓と手拍子が竪琴の音をかき消した.</span></div><div class=\"def\"><num>②</num> 大きな音を立てる 〈+<i>dat</i>〉.</div><div class=\"def\"><num>③</num> 激しく抗議[反対]する.</div><div class=\"def\"><num>④</num> 悩ます, うるさがらせる.</div><div class=\"def\"><num>⑤</num> 効果を打ち消す.</div>\r\n","<div class=\"hw\">obstrictus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obstringō\">obstringo</a>.</div>\r\n","<div class=\"hw\">obstri(n)gillō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://obstringō\">obstringō</a>]</div><div class=\"def\">妨害する, じゃまする.</div>\r\n","<div class=\"hw\">obstringō</div><div class=\"pos\">-ere -strinxī -strictum, <i>tr</i></div><div class=\"def\"><num>①</num> 縛る, 締める.</div><div class=\"def\"><num>②</num> 縛りつける.</div><div class=\"def\"><num>③</num> 義務を負わせる, 拘束する 〈alqm re〉.</div><div class=\"def\"><num>④</num> 約束する, 誓う.</div><div class=\"def\"><num>⑤</num> 巻き込む, 巻添えにする 〈alqm re〉.</div><div class=\"def\"><num>⑥</num> 責を負わせる, 罪を帰する.</div>\r\n","<div class=\"hw\">obstrinxī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obstringō\">obstringo</a>.</div>\r\n","<div class=\"hw\">obstructiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[obstruo]</div><div class=\"def\"><num>①</num> 障害(物).</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘病〙閉塞(症).</div>\r\n","<div class=\"hw\">obstructus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obstruō\">obstruo</a>.</div>\r\n","<div class=\"hw\">obstruxī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obstruō\">obstruo</a>.</div>\r\n","<div class=\"hw\">obstruō</div><div class=\"pos\">-ere -struxī -structum, <i>tr</i>, <i>intr</i></div><div class=\"ori\">[ob-/struo]</div><div class=\"def\"><num>①</num> 障害物として置く 〈+<i>acc</i> [<i>dat</i>]〉.</div><div class=\"def\"><num>②</num> (道などを)ふさぐ, 遮断する.</div><div class=\"def\"><num>③</num> (視界・光などを)さえぎる.</div><div class=\"def\"><num>④</num> (機能・活動などを)妨げる</div><div class=\"ex\"><i>obstruere aures</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">耳を聞こえなくさせる.</span></div>\r\n","<div class=\"hw\">obstrāgulum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">サンダルのひも.</div>\r\n","<div class=\"hw\">obstrūdō</div><div class=\"pos\">-ere, <i>tr</i></div><div class=\"def\">=<a href=\"entry://obtrūdō\">obtrudo</a>.</div>\r\n","<div class=\"hw\">obstupefacere</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://obstupefaciō\">obstupefacio</a>.</div>\r\n","<div class=\"hw\">obstupefaciō</div><div class=\"pos\">-cere -fēcī -factum, <i>tr</i></div><div class=\"ori\">[ob-/stupefacio]</div><div class=\"def\"><num>①</num> 唖然とさせる, どぎもを抜く.</div><div class=\"def\"><num>②</num> 無感覚にする, 麻痺させる.</div>\r\n","<div class=\"hw\">obstupefactus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obstupefaciō\">obstupefacio</a>.</div>\r\n","<div class=\"hw\">obstupefēcī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obstupefaciō\">obstupefacio</a>.</div>\r\n","<div class=\"hw\">obstupefīō</div><div class=\"pos\">-fierī, <i>intr</i></div><div class=\"def\">(<a href=\"entry://obstupefaciō\">obstupefacio</a> の <i>pass</i> として用いられる).</div>\r\n","<div class=\"hw\">obstupescō</div><div class=\"pos\">-ere -stupuī, <i>intr</i>(<i>tr</i>)</div><div class=\"ori\">[ob-/stupesco]</div><div class=\"def\"><num>①</num> 麻痺する, 無感覚になる.</div><div class=\"def\"><num>②</num> あっけに取られる, 唖然とする, びっくり仰天する.</div>\r\n","<div class=\"hw\">obstupidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ob-/stupidus]</div><div class=\"def\">あっけに取られた, 唖然とした.</div>\r\n","<div class=\"hw\">obstupuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obstupescō\">obstupesco</a>.</div>\r\n","<div class=\"hw\">obstāculum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://obstantia\">obstantia<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">obstātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obstō\">obsto</a>.</div>\r\n","<div class=\"hw\">obstīpans</div><div class=\"pos\">-antis, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[ob-/stipo]</div><div class=\"def\">〘薬〙止痢剤.</div>\r\n","<div class=\"hw\">obstīpus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ob-/stipo]</div><div class=\"def\"><num>①</num> 斜めの, 傾いた.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 頑固な, つむじ曲がりの.</div>\r\n","<div class=\"hw\">obstīpātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[ob-/stipo]</div><div class=\"def\"><num>①</num> (群衆の)ひしめき, 雑踏.</div><div class=\"def\"><num>②</num> 〘病〙(頑固な)便秘.</div>\r\n","<div class=\"hw\">obstō</div><div class=\"pos\">-āre -stitī(<i>fut p</i> -stātūrus), <i>intr</i></div><div class=\"ori\">[ob-/sto]</div><div class=\"def\"><num>①</num> 立ちはだかる, 道をふさぐ, 行く手をはばむ 〈+<i>dat</i>〉.</div><div class=\"def\"><num>②</num> じゃまする, 妨げる.</div><div class=\"def\"><num>③</num> 抵抗する, 反対する 〈+<i>dat</i>;ne〉.</div>\r\n","<div class=\"hw\">obsufflō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[ob-/sufflo]</div><div class=\"def\">吹きかける 〈alci alqd〉.</div>\r\n","<div class=\"hw\">obsum</div><div class=\"pos\">-esse -fuī, <i>intr</i></div><div class=\"ori\">[ob-/sum]</div><div class=\"def\">じゃまになる, 害になる 〈+<i>dat</i>〉.</div>\r\n","<div class=\"hw\">obsurdescō</div><div class=\"pos\">-ere -surduī, <i>intr</i></div><div class=\"ori\">[ob-/surdus]</div><div class=\"def\"><num>①</num> 耳が聞こえなくなる.</div><div class=\"def\"><num>②</num> (忠告などに)耳をかさなくなる.</div>\r\n","<div class=\"hw\">obsurduī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obsurdescō\">obsurdesco</a>.</div>\r\n","<div class=\"hw\">obsuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obsuō\">obsuo</a>.</div>\r\n","<div class=\"hw\">obsuō</div><div class=\"pos\">-ere -suī -sūtum, <i>tr</i></div><div class=\"ori\">[ob-/suo]</div><div class=\"def\">(穴などを)縫い合わせる, 縫い閉じる.</div>\r\n","<div class=\"hw\">obsēdī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obsideō\">obsideo</a>, <a href=\"entry://obsīdō\">obsido</a>.</div>\r\n","<div class=\"hw\">obsēvī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obserō\">obsero<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">obsīdō</div><div class=\"pos\">-ere -sēdī -sessum, <i>tr</i></div><div class=\"ori\">[ob-/sido]</div><div class=\"def\"><num>①</num> 包囲[攻囲]する, 封鎖する.</div><div class=\"def\"><num>②</num> 占拠[占領]する.</div><div class=\"def\"><num>③</num> (病気が)襲う, 悩ます.</div>\r\n","<div class=\"hw\">obsīpiō</div><div class=\"pos\">-īre, <i>tr</i></div><div class=\"def\">=<a href=\"entry://obsaepiō\">obsaepio</a>.</div>\r\n","<div class=\"hw\">obsōnitō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr freq</i></div><div class=\"ori\">[obsono<SUP>1</SUP>]</div><div class=\"def\">(しばしば)饗宴を催す, ごちそうする.</div>\r\n","<div class=\"hw\">obsōnium, ops-</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> パンといっしょに食べるもの《野菜・魚・果物など》.</div><div class=\"def\"><num>②</num> (<i>pl</i>)褒賞.</div>\r\n","<div class=\"hw\">obsōnor</div><div class=\"pos\">-ārī -ātus sum, <i>tr</i>, <i>intr dep</i></div><div class=\"def\">=<a href=\"entry://obsōnō\">obsono<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">obsōnātor, ops-</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[obsono<SUP>1</SUP>]</div><div class=\"def\">食料を調達する人, まかない人.</div>\r\n","<div class=\"hw\">obsōnātus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[obsono<SUP>1</SUP>]</div><div class=\"def\">食料の買出し.</div>\r\n","<div class=\"hw\">obsōnō<SUP>1</SUP>, ops-</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>, <i>intr</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>tr</i>)(食料を)購入する, 調達する.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>intr</i>)</div><div class=\"def\"><num>①</num> 食料を購入[調達]する.</div><div class=\"def\"><num>②</num> 饗宴を催す, ごちそうを食べる.</div>\r\n","<div class=\"hw\">obsōpiō</div><div class=\"pos\">-īre -īvī [-iī] -ītum, <i>tr</i></div><div class=\"ori\">[ob-/sopio<SUP>1</SUP>]</div><div class=\"def\">眠らせる.</div>\r\n","<div class=\"hw\">obsōpītus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obsōpiō\">obsopio</a>.</div>\r\n","<div class=\"hw\">obsūtus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obsuō\">obsuo</a>.</div>\r\n","<div class=\"hw\">obtaedescit</div><div class=\"pos\">-ere, <i>intr impers</i></div><div class=\"ori\">[ob-/taedet]</div><div class=\"def\">いやになる, 飽きあきする.</div>\r\n","<div class=\"hw\">obtectus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obtegō\">obtego</a>.</div><hr><div class=\"hw\">obtectus<SUP>2</SUP></div><div class=\"pos\">-ūs, <SUP>◇</SUP><i>m</i></div><div class=\"def\">おおい.</div>\r\n","<div class=\"hw\">obtegō</div><div class=\"pos\">-ere -texī -tectum, <i>tr</i></div><div class=\"ori\">[ob-/tego]</div><div class=\"def\"><num>①</num> おおう, 包む 〈alqd re〉.</div><div class=\"def\"><num>②</num> 保護する.</div><div class=\"def\"><num>③</num> 隠す, 見えなくする.</div>\r\n","<div class=\"hw\">obtemperanter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[obtempero]</div><div class=\"def\">従順に, 服従的に.</div>\r\n","<div class=\"hw\">obtemperātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[obtempero]</div><div class=\"def\">服従, 遵守<SUB>じゅんしゅ</SUB>.</div>\r\n","<div class=\"hw\">obtemperātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↓<a href=\"entry://obtemperō\">obtemperō</a>]</div><div class=\"def\">服従者.</div>\r\n","<div class=\"hw\">obtemperō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"ori\">[ob-/tempero]</div><div class=\"def\">要求に応ずる, 従う 〈+<i>dat</i>〉.</div>\r\n","<div class=\"hw\">obtendī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obtendō\">obtendo</a>.</div>\r\n","<div class=\"hw\">obtendō</div><div class=\"pos\">-ere -tendī -tentum, <i>tr</i></div><div class=\"ori\">[ob-/tendo<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 前[上]に広げる.</div><div class=\"def\"><num>②</num> (<i>pass</i>)向かい合う, 面する 〈+<i>dat</i>〉.</div><div class=\"def\"><num>③</num> 隠れみの[口実]にする.</div><div class=\"def\"><num>④</num> おおう, 隠す.</div>\r\n","<div class=\"hw\">obtenebrō</div><div class=\"pos\">-āre -āvī -ātum, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[ob-/tenebro]</div><div class=\"def\">暗くする.</div>\r\n","<div class=\"hw\">obtensus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[obtendo]</div><div class=\"def\">口実.</div>\r\n","<div class=\"hw\">obtentus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obtineō\">obtineo</a>, <a href=\"entry://obtendō\">obtendo</a>.</div><hr><div class=\"hw\">obtentus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[obtendo]</div><div class=\"def\"><num>①</num> おおうこと;隠すこと.</div><div class=\"def\"><num>②</num> 口実.</div>\r\n","<div class=\"hw\">obterō</div><div class=\"pos\">-ere -trīvī -trītum, <i>tr</i></div><div class=\"ori\">[ob-/tero]</div><div class=\"def\"><num>①</num> 踏みつぶす, 押しつぶす.</div><div class=\"def\"><num>②</num> 全滅させる, 粉砕する.</div><div class=\"def\"><num>③</num> 見くだす, 軽蔑する.</div><div class=\"def\"><num>④</num> すりへらす.</div>\r\n","<div class=\"hw\">obtestor</div><div class=\"pos\">-ārī -ātus sum, <i>tr dep</i></div><div class=\"ori\">[ob-/testor]</div><div class=\"def\"><num>①</num> 証人として引合いに出す.</div><div class=\"def\"><num>②</num> 懇願[嘆願]する 〈alqm;alqd;ut, ne;+<i>subj</i>〉.</div><div class=\"def\"><num>③</num> 断言する;誓約する.</div>\r\n","<div class=\"hw\">obtestātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[obtestor]</div><div class=\"def\"><num>①</num> (神々を)証人として呼ぶこと, 祈願.</div><div class=\"def\"><num>②</num> 嘆願, 懇願.</div>\r\n","<div class=\"hw\">obtestātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obtestor\">obtestor</a>.</div>\r\n","<div class=\"hw\">obtextus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obtexō\">obtexo</a>.</div>\r\n","<div class=\"hw\">obtexuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obtexō\">obtexo</a>.</div>\r\n","<div class=\"hw\">obtexī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obtegō\">obtego</a>.</div>\r\n","<div class=\"hw\">obtexō</div><div class=\"pos\">-ere -texuī -textum, <i>tr</i></div><div class=\"ori\">[ob-/texo]</div><div class=\"def\"><num>①</num> (クモが巣を)...の上に張る.</div><div class=\"def\"><num>②</num> おおう, 隠す.</div>\r\n","<div class=\"hw\">obticentia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://obticeō\">obticeō</a>]</div><div class=\"def\">〘修〙頓絶法(=<a href=\"entry://aposiōpēsis\">aposiopesis</a>).</div>\r\n","<div class=\"hw\">obticesco</div><div class=\"pos\">-ere -ticuī, <i>intr inch</i></div><div class=\"ori\">[↑<a href=\"entry://obticeō\">obticeō</a>]</div><div class=\"def\">黙り込む, 沈黙する.</div>\r\n","<div class=\"hw\">obticeō</div><div class=\"pos\">-ēre, <i>intr</i></div><div class=\"ori\">[ob-/taceo]</div><div class=\"def\">黙っている.</div>\r\n","<div class=\"hw\">obticuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obticesco\">obticesco</a>.</div>\r\n","<div class=\"hw\">obtigī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obtingō\">obtingo</a>.</div>\r\n","<div class=\"hw\">obtineō, opt-</div><div class=\"pos\">-ēre -tinuī -tentum, <i>tr</i>(<i>intr</i>)</div><div class=\"ori\">[ob-/teneo]</div><div class=\"def\"><num>①</num> (ある行動・状態を)保つ, 続ける.</div><div class=\"def\"><num>②</num> 支配[管理]する.</div><div class=\"def\"><num>③</num> (場所・地位を)占めている.</div><div class=\"def\"><num>④</num> おおう, 一面に広がる.</div><div class=\"def\"><num>⑤</num> (力・権利などを)もっている, 保持している.</div><div class=\"def\"><num>⑥</num> (目標を)達成する;うまくいく, 成功する.</div>\r\n","<div class=\"hw\">obtingō, opt-</div><div class=\"pos\">-ere -tigī, <i>intr</i></div><div class=\"ori\">[ob-/tango]</div><div class=\"def\">(偶然)起こる, 振りかかる 〈alci;ut〉</div><div class=\"ex\"><i>si quid mihi obtigerit</i> (<author>C<small>IC</small></author>)<span class=\"ext\">もし何事かが私に起こったなら(=万一私が死ぬようなことがあれば).</span></div>\r\n","<div class=\"hw\">obtorpescō</div><div class=\"pos\">-ere -torpuī, <i>intr</i></div><div class=\"ori\">[ob-/torpesco]</div><div class=\"def\">無感覚になる, 麻痺する.</div>\r\n","<div class=\"hw\">obtorpuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obtorpescō\">obtorpesco</a>.</div>\r\n","<div class=\"hw\">obtorqueō</div><div class=\"pos\">-ēre -torsī -tortum, <i>tr</i></div><div class=\"ori\">[ob-/torqueo]</div><div class=\"def\"><num>①</num> 方向を変える, よじる.</div><div class=\"def\"><num>②</num> (通例 <i>pp</i> で)(輪なわで)首を締める.</div>\r\n","<div class=\"hw\">obtorsī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obtorqueō\">obtorqueo</a>.</div>\r\n","<div class=\"hw\">obtortus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obtorqueō\">obtorqueo</a>.</div>\r\n","<div class=\"hw\">obtrectātiō</div><div class=\"pos\">-ōnis</div><div class=\"ori\">[obtrecto]</div><div class=\"def\">けなすこと, 中傷, そしり.</div>\r\n","<div class=\"hw\">obtrectātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://obtrectō\">obtrectō</a>]</div><div class=\"def\">中傷者, そしる[けなす]人.</div>\r\n","<div class=\"hw\">obtrectō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>, <i>tr</i></div><div class=\"ori\">[ob-/tracto]</div><div class=\"def\">(嫉妬・悪意から)けなす, そしる 〈+<i>dat</i> [<i>acc</i>]〉.</div>\r\n","<div class=\"hw\">obtruncātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://obtruncō\">obtruncō</a>]</div><div class=\"def\">(木の)刈り込み, 剪定.</div>\r\n","<div class=\"hw\">obtruncō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[ob-/trunco]</div><div class=\"def\"><num>①</num> (木を)刈り込む, 剪定する.</div><div class=\"def\"><num>②</num> 殺す, 殺戮する.</div>\r\n","<div class=\"hw\">obtrītus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obterō\">obtero</a>.</div><hr><div class=\"hw\">obtrītus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">踏みつぶすこと.</div>\r\n","<div class=\"hw\">obtrīvī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obterō\">obtero</a>.</div>\r\n","<div class=\"hw\">obtrūdō</div><div class=\"pos\">-ere -trūsī -trūsum, <i>tr</i></div><div class=\"ori\">[ob-/trudo]</div><div class=\"def\"><num>①</num> 突き出す.</div><div class=\"def\"><num>②</num> (飲食物を)詰め込む, のみ込む.</div><div class=\"def\"><num>③</num> (無理に[だまして])押しつける.</div>\r\n","<div class=\"hw\">obtrūsus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obtrūdō\">obtrudo</a>.</div>\r\n","<div class=\"hw\">obtrūsī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obtrūdō\">obtrudo</a>.</div>\r\n","<div class=\"hw\">obtudī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obtundō\">obtundo</a>.</div>\r\n","<div class=\"hw\">obtueor</div><div class=\"pos\">-ērī, <i>tr</i>, <i>intr dep</i></div><div class=\"ori\">[ob-/tueor]</div><div class=\"def\">見る, 眺める, 見つめる.</div>\r\n","<div class=\"hw\">obtulī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://offerō\">offero</a>.</div>\r\n","<div class=\"hw\">obtundō</div><div class=\"pos\">-ere -tudī -tūsum [-tunsum], <i>tr</i></div><div class=\"ori\">[ob-/tundo]</div><div class=\"def\"><num>①</num> 強く打つ, たたきのめす.</div><div class=\"def\"><num>②</num> 鈍らせる, 弱める.</div><div class=\"def\"><num>③</num> (耳を)聞こえなくする.</div><div class=\"def\"><num>④</num> やかましく言い立てる;悩ます, 煩わす.</div><div class=\"def\"><num>⑤</num> しゃがれ声にする.</div>\r\n","<div class=\"hw\">obturbātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://obturbō\">obturbō</a>]</div><div class=\"def\">不安, 動揺, 狼狽.</div>\r\n","<div class=\"hw\">obturbō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[ob-/turbo<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> かき乱す, 混乱させる.</div><div class=\"def\"><num>②</num> さえぎる, じゃまする.</div>\r\n","<div class=\"hw\">obturgescō</div><div class=\"pos\">-ere -tursī, <i>intr</i></div><div class=\"ori\">[ob-/turgesco]</div><div class=\"def\">はれる.</div>\r\n","<div class=\"hw\">obtursī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obturgescō\">obturgesco</a>.</div>\r\n","<div class=\"hw\">obtūrāmentum, opt-</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[obturo]</div><div class=\"def\">栓;水をせきとめる壁.</div>\r\n","<div class=\"hw\">obtūrātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[obturo]</div><div class=\"def\"><num>①</num> ふさぐこと.</div><div class=\"def\"><num>②</num> 〘医〙閉鎖, 閉塞.</div>\r\n","<div class=\"hw\">obtūrātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obtūrō\">obturo</a>.</div>\r\n","<div class=\"hw\">obtūrō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[ob-/<i>cf</i>. turgeo]</div><div class=\"def\"><num>①</num> (穴などを)ふさぐ, 栓をする</div><div class=\"ex\"><i>obturare aures</i> (<author>H<small>OR</small></author>)<span class=\"ext\">耳をふさぐ(=聞こうとしない).</span></div><div class=\"def\"><num>②</num> 和らげる, 鎮める.</div>\r\n","<div class=\"hw\">obtūsus, -tunsus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[obtundo]</div><div class=\"def\"><num>①</num> (刃などが)切れ味の悪い, 鈍い, なまくらの.</div><div class=\"def\"><num>②</num> (光が)鈍い, さえない.</div><div class=\"def\"><num>③</num> (感覚・能力などが)鈍い;愚かな.</div><div class=\"def\"><num>④</num> (声が)しゃがれた.</div><div class=\"def\"><num>⑤</num> (行動が)粗野な, 無骨な.</div>\r\n","<div class=\"hw\">obtūsē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://obtūsus\">obtūsus, -tunsus</a>]</div><div class=\"def\">鈍く.</div>\r\n","<div class=\"hw\">obtūtus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[obtueor]</div><div class=\"def\"><num>①</num> 見つめること, 凝視.</div><div class=\"def\"><num>②</num> 思いめぐらすこと.</div>\r\n","<div class=\"hw\">obumbrātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[obumbro]</div><div class=\"def\">暗くすること, 影にすること.</div>\r\n","<div class=\"hw\">obumbrātrix</div><div class=\"pos\">-īcis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://obumbrō\">obumbrō</a>]</div><div class=\"def\">暗くする[影にする]者《女性》.</div>\r\n","<div class=\"hw\">obumbrō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[ob-/umbro]</div><div class=\"def\"><num>①</num> 暗くする, 影にする.</div><div class=\"def\"><num>②</num> 曇らせる.</div><div class=\"def\"><num>③</num> おおい隠す;かばう.</div>\r\n","<div class=\"hw\">obunctus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ob-/ungo]</div><div class=\"def\">香油[香料]を塗った.</div>\r\n","<div class=\"hw\">obuncus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ob-/uncus<SUP>2</SUP>]</div><div class=\"def\">かぎ状の, 曲がった.</div>\r\n","<div class=\"hw\">obustus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ob-/uro]</div><div class=\"def\"><num>①</num> (先端を)焼き焦がした.</div><div class=\"def\"><num>②</num> (霜で)痛められた.</div>\r\n","<div class=\"hw\">obvallō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[ob-/vallo]</div><div class=\"def\">壁[堡塁]で囲う.</div>\r\n","<div class=\"hw\">obvenientia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://obveniō\">obveniō</a>]</div><div class=\"def\">できごと, 事件.</div>\r\n","<div class=\"hw\">obveniō</div><div class=\"pos\">-īre -vēnī -ventum, <i>intr</i></div><div class=\"ori\">[ob-/venio]</div><div class=\"def\"><num>①</num> 向かって行く 〈+<i>dat</i>〉.</div><div class=\"def\"><num>②</num> (偶然)起こる, 振りかかる.</div><div class=\"def\"><num>③</num> 与えられる, 割り当てられる, (所有に)帰する.</div>\r\n","<div class=\"hw\">obventiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↑<a href=\"entry://obveniō\">obveniō</a>]</div><div class=\"def\">収入.</div>\r\n","<div class=\"hw\">obventus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obveniō\">obvenio</a>.</div>\r\n","<div class=\"hw\">obversor</div><div class=\"pos\">-ārī -ātus sum, <i>intr dep</i></div><div class=\"ori\">[ob-/versor]</div><div class=\"def\"><num>①</num> (人目につくように)歩きまわる, うろうろする.</div><div class=\"def\"><num>②</num> (目の前[心の中]に)現われる, ちらつく 〈alci〉.</div>\r\n","<div class=\"hw\">obversus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obvertō\">obverto</a>.</div>\r\n","<div class=\"hw\">obvertī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obvertō\">obverto</a>.</div>\r\n","<div class=\"hw\">obvertō</div><div class=\"pos\">-ere -vertī -versum, <i>tr</i></div><div class=\"ori\">[ob-/verto]</div><div class=\"def\"><num>①</num> (ある方向へ)向ける 〈alqd in [ad] alqd〉.</div><div class=\"def\"><num>②</num> (<i>pass</i>)反対する, 逆らう;没頭する.</div>\r\n","<div class=\"hw\">obviam</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[ob/via]</div><div class=\"def\"><num>①</num> 行く手に, 途中に, 行き会うように 〈+<i>dat</i>〉</div><div class=\"ex\"><i>～ ire [procedere</i>] (<author>P<small>LAUT</small> [C<small>IC</small>]</author>)<span class=\"ext\">出迎える;迎え撃つ</span></div><div class=\"ex\">～ <i>ire</i> (<author>C<small>IC</small></author>)<span class=\"ext\">立ち向かう;手助けする.</span></div><div class=\"def\"><num>②</num> 手近に, 手の届く所に.</div>\r\n","<div class=\"hw\">obvigilō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"ori\">[ob-/vigilo]</div><div class=\"def\">用心する, 油断しない.</div>\r\n","<div class=\"hw\">obvius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ob-/via]</div><div class=\"def\"><num>①</num> 途中[行く手]にある, 行き会う 〈+<i>dat</i>〉.</div><div class=\"def\"><num>②</num> 立ち向かう, 迎え撃つ.</div><div class=\"def\"><num>③</num> じゃまをする, 妨害する.</div><div class=\"def\"><num>④</num> 現われる;(心に)浮かぶ.</div><div class=\"def\"><num>⑤</num> さらされた.</div><div class=\"def\"><num>⑥</num> 手元にある, 手近な;ありふれた.</div><div class=\"def\"><num>⑦</num> 気さくな, 愛想のよい.</div>\r\n","<div class=\"hw\">obviō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"ori\">[↓<a href=\"entry://obvius\">obvius</a>]</div><div class=\"def\"><num>①</num> 反する, 逆らう 〈+<i>dat</i>〉.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 防ぐ, 妨げる.</div>\r\n","<div class=\"hw\">obvolvī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obvolvō\">obvolvo</a>.</div>\r\n","<div class=\"hw\">obvolvō</div><div class=\"pos\">-ere -volvī -volūtum, <i>tr</i></div><div class=\"ori\">[ob-/volvo]</div><div class=\"def\"><num>①</num> 包む, おおう.</div><div class=\"def\"><num>②</num> 取りつくろう, 隠す.</div>\r\n","<div class=\"hw\">obvolūtus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://obvolvō\">obvolvo</a>.</div>\r\n","<div class=\"hw\">obvāgiō</div><div class=\"pos\">-īre, <i>intr</i></div><div class=\"ori\">[ob-/vagio]</div><div class=\"def\">(子供が)泣きわめく.</div>\r\n","<div class=\"hw\">obvēnī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://obveniō\">obvenio</a>.</div>\r\n","<div class=\"hw\">obātrātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ob-/ater]</div><div class=\"def\">黒みがかった.</div>\r\n","<div class=\"hw\">obēd-</div><div class=\"def\">⇒oboed-.</div>\r\n","<div class=\"hw\">obēsitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[obesus]</div><div class=\"def\">肥満(体).</div>\r\n","<div class=\"hw\">obēsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ob-/edo<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 肥えた, 太った.</div><div class=\"def\"><num>②</num> ふくれた, はれた.</div><div class=\"def\"><num>③</num> 鈍い, 鈍感な.</div>\r\n","<div class=\"hw\">obēsō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"ori\">[obesus]</div><div class=\"def\">太らせる.</div>\r\n","<div class=\"hw\">obīrascor</div><div class=\"pos\">-scī -īrātus sum, <i>intr dep</i></div><div class=\"ori\">[ob-/irascor]</div><div class=\"def\">(...に)怒っている 〈alci rei〉.</div>\r\n","<div class=\"hw\">obīrascī</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://obīrascor\">obirascor</a>.</div>\r\n","<div class=\"hw\">obīre</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://obeō\">obeo</a>.</div>\r\n","<div class=\"hw\">obīrātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://obīrascor\">obīrascor</a>]</div><div class=\"def\">怒り, 憤怒.</div>\r\n","<div class=\"hw\">occa</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[occo]</div><div class=\"def\">まぐわ.</div>\r\n","<div class=\"hw\">occaecātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[occaeco]</div><div class=\"def\">隠す[見えなくする]こと.</div>\r\n","<div class=\"hw\">occaecātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://occaecō\">occaeco</a>.</div>\r\n","<div class=\"hw\">occaecō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[ob-/caeco]</div><div class=\"def\"><num>①</num> 盲目にする, 目を見えなくさせる.</div><div class=\"def\"><num>②</num> 暗くする.</div><div class=\"def\"><num>③</num> わかりにくくする.</div><div class=\"def\"><num>④</num> 隠す, 見えなくする.</div>\r\n","<div class=\"hw\">occallescō</div><div class=\"pos\">-ere -caluī, <i>intr</i></div><div class=\"ori\">[ob-/calleo]</div><div class=\"def\"><num>①</num> (表面が)固くなる.</div><div class=\"def\"><num>②</num> 無感覚になる.</div>\r\n","<div class=\"hw\">occallātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ob-/callum]</div><div class=\"def\">無感覚になった.</div>\r\n","<div class=\"hw\">occaluī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://occallescō\">occallesco</a>.</div>\r\n","<div class=\"hw\">occanuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://occanō\">occano</a>.</div>\r\n","<div class=\"hw\">occanō</div><div class=\"pos\">-ere -canuī, <i>intr</i></div><div class=\"ori\">[ob-/cano]</div><div class=\"def\">らっぱを吹く.</div>\r\n","<div class=\"hw\">occecinī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">=<a href=\"entry://occinuī\">occinui</a>(⇒ <a href=\"entry://occinō\">occino</a>).</div>\r\n","<div class=\"hw\">occentus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[occino]</div><div class=\"def\">(トガリネズミが)キーキー鳴く声.</div>\r\n","<div class=\"hw\">occentō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>, <i>tr</i></div><div class=\"ori\">[ob-/canto]</div><div class=\"def\"><num>①</num> (...に向かって)歌う.</div><div class=\"def\"><num>②</num> 魔法をかける.</div>\r\n","<div class=\"hw\">occeptus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://occipiō\">occipio</a>.</div>\r\n","<div class=\"hw\">occeptō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr freq</i></div><div class=\"ori\">[occipio]</div><div class=\"def\">始める.</div>\r\n","<div class=\"hw\">occessus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://occēdō\">occedo</a>.</div>\r\n","<div class=\"hw\">occessī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://occēdō\">occedo</a>.</div>\r\n","<div class=\"hw\">occidens<SUP>1</SUP></div><div class=\"pos\">-entis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[occido<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 日没の, 夕方の.</div><div class=\"def\"><num>②</num> 西の, 西方の.</div><hr><div class=\"hw\">occidens<SUP>2</SUP></div><div class=\"pos\">-entis, <i>m</i></div><div class=\"def\">太陽の没する地域[方角], 西, 西方.</div>\r\n","<div class=\"hw\">occidentālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[occidens<SUP>1</SUP>]</div><div class=\"def\">西の, 西方の.</div>\r\n","<div class=\"hw\">occiduus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[occido<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> (太陽・天体が)没しようとする, 沈みつつある.</div><div class=\"def\"><num>②</num> 西の, 西方の.</div><div class=\"def\"><num>③</num> 終わろうとする;死にそうな.</div>\r\n","<div class=\"hw\">occidī<SUP>1</SUP></div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://occidō\">occido<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">occidō<SUP>1</SUP></div><div class=\"pos\">-ere -cidī -cāsum, <i>intr</i></div><div class=\"ori\">[ob-/cado]</div><div class=\"def\"><num>①</num> 落ちる, 倒れる.</div><div class=\"def\"><num>②</num> (天体が)沈む, 没する</div><div class=\"ex\"><i>ante solem occasum</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">日没前に.</span></div><div class=\"def\"><num>③</num> 死ぬ;絶滅する.</div><div class=\"def\"><num>④</num> 破滅[滅亡]する, 崩壊する;消滅する</div><div class=\"ex\"><i>occidi</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">もうだめだ.</span></div>\r\n","<div class=\"hw\">occillō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"ori\">[occo]</div><div class=\"def\">打ちこわす, 粉砕する.</div>\r\n","<div class=\"hw\">occinuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://occinō\">occino</a>.</div>\r\n","<div class=\"hw\">occinō</div><div class=\"pos\">-ere -cinuī [occecinī], <i>intr</i></div><div class=\"ori\">[ob-/cano]</div><div class=\"def\"><num>①</num> (鳥が)不吉な鳴き方をする.</div><div class=\"def\"><num>②</num> (...に対して)鳴く, さえずる.</div>\r\n","<div class=\"hw\">occipere</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://occipiō\">occipio</a>.</div>\r\n","<div class=\"hw\">occipitium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[ob-/caput]</div><div class=\"def\">後頭部.</div>\r\n","<div class=\"hw\">occipitomastoīdeus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙後頭乳突の.</div>\r\n","<div class=\"hw\">occipitālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://occipitium\">occipitium</a>]</div><div class=\"def\">〘解〙後頭の.</div>\r\n","<div class=\"hw\">occipiō</div><div class=\"pos\">-pere -cēpī -ceptum, <i>tr</i>, <i>intr</i></div><div class=\"ori\">[ob-/capio<SUP>1</SUP>]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>tr</i>)始める, 取りかかる, 着手する 〈alqd;+<i>inf</i>〉.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>intr</i>)始まる, 生ずる.</div>\r\n","<div class=\"hw\">occiput</div><div class=\"pos\">-pitis, <i>n</i></div><div class=\"ori\">[ob-/caput]</div><div class=\"def\">後頭部.</div>\r\n","<div class=\"hw\">occlāmitō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"ori\">[ob-/clamito]</div><div class=\"def\">叫んで妨害する.</div>\r\n","<div class=\"hw\">occlūdō</div><div class=\"pos\">-ere -clūsī -clūsum, <i>tr</i></div><div class=\"ori\">[ob-/claudo<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> (建物・容器などを)閉ざす, 閉める.</div><div class=\"def\"><num>②</num> 閉じ込める.</div><div class=\"def\"><num>③</num> 止める, 抑える.</div>\r\n","<div class=\"hw\">occlūsiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[occludo]</div><div class=\"def\">〘医〙</div><div class=\"def\"><num>①</num> 閉鎖, 閉塞.</div><div class=\"def\"><num>②</num> 咬合.</div>\r\n","<div class=\"hw\">occlūsus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://occlūdō\">occludo</a>.</div>\r\n","<div class=\"hw\">occlūsī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://occlūdō\">occludo</a>.</div>\r\n","<div class=\"hw\">occoepī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">=<a href=\"entry://occēpī\">occepi</a>(⇒ <a href=\"entry://occipiō\">occipio</a>).</div>\r\n","<div class=\"hw\">occubitus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://occumbō\">occumbo</a>.</div>\r\n","<div class=\"hw\">occubuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://occumbō\">occumbo</a>.</div>\r\n","<div class=\"hw\">occubō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"ori\">[ob-/cubo]</div><div class=\"def\"><num>①</num> (前[上]に)横たわっている 〈alci〉.</div><div class=\"def\"><num>②</num> 死んで横たわっている.</div>\r\n","<div class=\"hw\">occucurrī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">=<a href=\"entry://occurrī\">occurri</a>(⇒ <a href=\"entry://occurrō\">occurro</a>).</div>\r\n","<div class=\"hw\">occulcō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[ob-/calco]</div><div class=\"def\">踏みつける, 踏みつぶす.</div>\r\n","<div class=\"hw\">occultum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://occultus\">occultus</a>]</div><div class=\"def\">秘密(にすること)</div><div class=\"ex\"><i>per</i> ～ (<author>S<small>EN</small></author>) =<i>ex occulto</i> (<author>T<small>ER</small></author>)<span class=\"ext\">ひそかに.</span></div>\r\n","<div class=\"hw\">occultus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[occulo]</div><div class=\"def\"><num>①</num> 隠された, (はっきり)見えない.</div><div class=\"def\"><num>②</num> 秘密の, ひそかな.</div><div class=\"def\"><num>③</num> 本心を隠す.</div>\r\n","<div class=\"hw\">occultātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[occulto<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 隠すこと, 秘密にすること.</div><div class=\"def\"><num>②</num> 〘天〙掩蔽<SUB>えんぺい</SUB>, 星食.</div><div class=\"def\"><num>③</num> 〘修〙逆言法.</div>\r\n","<div class=\"hw\">occultātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[occulto<SUP>2</SUP>]</div><div class=\"def\">隠す人.</div>\r\n","<div class=\"hw\">occultātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://occultō\">occulto<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">occultē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[occultus]</div><div class=\"def\"><num>①</num> こっそり, ひそかに.</div><div class=\"def\"><num>②</num> あいまいに, 遠まわしに.</div>\r\n","<div class=\"hw\">occultō<SUP>1</SUP></div><div class=\"pos\"><i>adv</i>(<i>abl</i>)</div><div class=\"ori\">[occultus]</div><div class=\"def\">ひそかに, こっそり.</div><hr><div class=\"hw\">occultō<SUP>2</SUP></div><div class=\"pos\">-āre -āvī -ātum, <i>intr freq</i></div><div class=\"ori\">[occulo]</div><div class=\"def\"><num>①</num> 見えなくする, 隠す;(<i>refl</i>, <i>pass</i>)身を隠す, 隠れる.</div><div class=\"def\"><num>②</num> 聞こえなくする.</div><div class=\"def\"><num>③</num> 秘密にする.</div>\r\n","<div class=\"hw\">occuluī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://occulō\">occulo</a>.</div>\r\n","<div class=\"hw\">occulō</div><div class=\"pos\">-ere -culuī -cultum, <i>tr</i></div><div class=\"ori\">[ob-/celo]</div><div class=\"def\"><num>①</num> 見えなくする, 隠す.</div><div class=\"def\"><num>②</num> 土をかける, 埋める.</div><div class=\"def\"><num>③</num> 知られないようにする, 秘密にする.</div>\r\n","<div class=\"hw\">occumbō</div><div class=\"pos\">-ere -cubuī -cubitum, <i>intr</i>(<i>tr</i>)</div><div class=\"ori\">[ob-/<SUP>*</SUP>cumbo(<i>cf</i>. cubo)]</div><div class=\"def\">倒れる;死ぬ</div><div class=\"ex\"><i>occumbere mortem [morte, morti]</i> (<author>C<small>IC</small> [L<small>IV</small>, V<small>ERG</small>]</author>)<span class=\"ext\">死ぬ.</span></div>\r\n","<div class=\"hw\">occupātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[occupo]</div><div class=\"def\"><num>①</num> 占有, 所有.</div><div class=\"def\"><num>②</num> 仕事, 業務</div><div class=\"ex\"><i>～ rei publicae</i> (<author>C<small>AES</small></author>)<span class=\"ext\">国事, 国務.</span></div>\r\n","<div class=\"hw\">occupātus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[occupo]</div><div class=\"def\">忙しい, 従事している;結婚している 〈(in)re〉.</div><hr><div class=\"hw\">occupātus<SUP>2</SUP></div><div class=\"pos\">-ūs, <SUP>◇</SUP><i>m</i></div><div class=\"def\">仕事, 職務.</div>\r\n","<div class=\"hw\">occupō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[ob-/capio<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> つかむ, つかまえる.</div><div class=\"def\"><num>②</num> 占有[占拠]する;占領する, 支配する.</div><div class=\"def\"><num>③</num> (病気・現象などが)襲う, とらえる.</div><div class=\"def\"><num>④</num> (地位・官職などを)占める, 就く.</div><div class=\"def\"><num>⑤</num> (機会を)利用する, とらえる.</div><div class=\"def\"><num>⑥</num> (場所・時間を)占める, ふさぐ.</div><div class=\"def\"><num>⑦</num> (金銭を)費やす, 投資する.</div><div class=\"def\"><num>⑧</num> 夢中にさせる;専心させる.</div><div class=\"def\"><num>⑨</num> 不意を襲う, 襲撃する.</div><div class=\"def\"><num>⑩</num> 機先を制する, 先んずる.</div>\r\n","<div class=\"hw\">occurrī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://occurrō\">occurro</a>.</div>\r\n","<div class=\"hw\">occurrō</div><div class=\"pos\">-ere -(cu)currī -cursum, <i>intr</i></div><div class=\"ori\">[ob-/curro]</div><div class=\"def\"><num>①</num> 急いで会いに行く.</div><div class=\"def\"><num>②</num> 到着する, やって来る.</div><div class=\"def\"><num>③</num> 襲う, 降りかかる.</div><div class=\"def\"><num>④</num> 立ち向かう, 迎え撃つ, 対抗する.</div><div class=\"def\"><num>⑤</num> 対処する, 阻止する</div><div class=\"ex\"><i>venienti occurrite morbo</i> (<author>P<small>ERS</small></author>)<span class=\"ext\">病には途中で(=手遅れにならないうちに)対処せよ.</span></div><div class=\"def\"><num>⑥</num> (偶然)出会う, でくわす.</div><div class=\"def\"><num>⑦</num> 現われる, 起こる;(心に)浮かぶ.</div>\r\n","<div class=\"hw\">occursiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[occurro]</div><div class=\"def\"><num>①</num> 会うこと, 訪問.</div><div class=\"def\"><num>②</num> (<i>pl</i>)急襲, 襲撃.</div>\r\n","<div class=\"hw\">occursus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://occurrō\">occurro</a>.</div><hr><div class=\"hw\">occursus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 行き会うこと, 遭遇.</div><div class=\"def\"><num>②</num> 襲撃, 攻撃.</div><div class=\"def\"><num>③</num> 衝突, ぶつかること.</div>\r\n","<div class=\"hw\">occursātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[occurso]</div><div class=\"def\">(敬意のしるしとして)走るようにして出迎えること.</div>\r\n","<div class=\"hw\">occursātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[occurso]</div><div class=\"def\">走るようにして出迎える人.</div>\r\n","<div class=\"hw\">occursātrix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://occursātor\">occursātor</a>]</div><div class=\"def\">出迎える人《女性》.</div>\r\n","<div class=\"hw\">occursō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr freq</i></div><div class=\"ori\">[occurro]</div><div class=\"def\"><num>①</num> 急いで会いに行く.</div><div class=\"def\"><num>②</num> さえぎる, 妨げる.</div><div class=\"def\"><num>③</num> 逆らう, 立ち向かう.</div><div class=\"def\"><num>④</num> 現われる, 生ずる, 目に映ずる.</div><div class=\"def\"><num>⑤</num> 襲撃する, 突撃する.</div><div class=\"def\"><num>⑥</num> 機先を制する.</div><div class=\"def\"><num>⑦</num> (心に)浮かぶ.</div>\r\n","<div class=\"hw\">occāsiuncula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[↑<a href=\"entry://occāsiō\">occāsiō</a>]</div><div class=\"def\">好機, 決定的瞬間.</div>\r\n","<div class=\"hw\">occāsiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[occido<SUP>1</SUP>]</div><div class=\"def\">機会, 好機</div><div class=\"ex\"><i>per occasionem</i> (<author>S<small>ALL</small></author>) =<i>ex occasione</i> (<author>S<small>UET</small></author>)<span class=\"ext\">都合のよい時に.</span></div>\r\n","<div class=\"hw\">occāsus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://occidō\">occido<SUP>1</SUP></a>.</div><hr><div class=\"hw\">occāsus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 日没, 沈むこと.</div><div class=\"def\"><num>②</num> 機会, 好機.</div><div class=\"def\"><num>③</num> 西, 西方.</div><div class=\"def\"><num>④</num> 没落, 崩壊, 滅亡;死.</div>\r\n","<div class=\"hw\">occātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[occo]</div><div class=\"def\">(土地を)まぐわでならすこと.</div>\r\n","<div class=\"hw\">occātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[occo]</div><div class=\"def\">まぐわでならす人.</div>\r\n","<div class=\"hw\">occātōrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://occātor\">occātor</a>]</div><div class=\"def\">(土地を)まぐわでならすことの.</div>\r\n","<div class=\"hw\">occēdō</div><div class=\"pos\">-ere -cessī -cessum, <i>intr</i></div><div class=\"ori\">[ob-/cedo<SUP>2</SUP>]</div><div class=\"def\">向かって行く 〈alci obviam〉.</div>\r\n","<div class=\"hw\">occēpī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://occipiō\">occipio</a>.</div>\r\n","<div class=\"hw\">occīdiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[occido<SUP>2</SUP>]</div><div class=\"def\">大虐殺, 根絶.</div>\r\n","<div class=\"hw\">occīdī<SUP>2</SUP></div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://occīdō\">occido<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">occīdō<SUP>2</SUP></div><div class=\"pos\">-ere -cīdī -cīsum, <i>tr</i></div><div class=\"ori\">[ob-/caedo]</div><div class=\"def\"><num>①</num> 打ち倒す;殺す.</div><div class=\"def\"><num>②</num> (死ぬほど)苦しめる, 悩ます.</div><div class=\"def\"><num>③</num> 破滅[滅亡]させる.</div>\r\n","<div class=\"hw\">occīsiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[occido<SUP>2</SUP>]</div><div class=\"def\">殺すこと, 殺害.</div>\r\n","<div class=\"hw\">occīsor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[occido<SUP>2</SUP>]</div><div class=\"def\">殺害者.</div>\r\n","<div class=\"hw\">occīsus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://occīdō\">occido<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">occō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"def\">まぐわでならす, すく.</div>\r\n","<div class=\"hw\">ocellus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[oculus]</div><div class=\"def\"><num>①</num> (小さな)目.</div><div class=\"def\"><num>②</num> (親愛を表わして)いとしい[大事な]人[もの].</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘動〙単眼.</div>\r\n","<div class=\"hw\">ocellātum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://ocellus\">ocellus</a>]</div><div class=\"def\">(目のような斑点のある)小さな石.</div>\r\n","<div class=\"hw\">ocliferius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[oculus/ferio]</div><div class=\"def\">人目をひく, 魅力的な.</div>\r\n","<div class=\"hw\">Ocnus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙オクヌス, <SUP>*</SUP>-ノス《 (1) Mantua 市の建設者.(2) 下界で縄をなってゆくそばからロバにその縄を食われるという罰を受けた男;むだな努力を象徴する寓意的人物》.</div>\r\n","<div class=\"hw\">ocrea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">すね当て.</div>\r\n","<div class=\"hw\">ocreātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://ocrea\">ocrea</a>]</div><div class=\"def\">すね当てを着けた.</div>\r\n","<div class=\"hw\">Ocriculum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">オクリクルム《Umbria 南部の町;現 Otricoli》.</div>\r\n","<div class=\"hw\">Ocriculānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Ocriculum の.</div>\r\n","<div class=\"hw\">ocris</div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\">ごつごつした山.</div>\r\n","<div class=\"hw\">Ocrēsia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">オクレーシア《Tanaquil の奴隷で Servius Tullius の母》.</div>\r\n","<div class=\"hw\">octagōnon</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://octagōnos\">octagōnos</a>]</div><div class=\"def\">8角[辺]形.</div>\r\n","<div class=\"hw\">octagōnos</div><div class=\"pos\">-os -on, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">8角[辺]形の.</div>\r\n","<div class=\"hw\">octangulus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[octo/angulus]</div><div class=\"def\">8角の.</div>\r\n","<div class=\"hw\">octaphoron</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://octaphoros\">octaphoros</a>]</div><div class=\"def\">8人かつぎの輿<SUB>こし</SUB>.</div>\r\n","<div class=\"hw\">octaphoros</div><div class=\"pos\">-os -on, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">8人で運ぶ.</div>\r\n","<div class=\"hw\">octastȳlos</div><div class=\"pos\">-os -on, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘建〙8本の円柱を持つ, 八柱式の.</div>\r\n","<div class=\"hw\">octennis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[octo/annus]</div><div class=\"def\">8歳の.</div>\r\n","<div class=\"hw\">octennium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[octo/annus]</div><div class=\"def\">8年間.</div>\r\n","<div class=\"hw\">octingentiēs, -ens</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://octingentī\">octingentī</a>]</div><div class=\"def\">800回[倍].</div>\r\n","<div class=\"hw\">octingentēsimus</div><div class=\"pos\">-a -um, <i>num ord</i></div><div class=\"ori\">[↓<a href=\"entry://octingentī\">octingentī</a>]</div><div class=\"def\">800番目の.</div>\r\n","<div class=\"hw\">octingentī</div><div class=\"pos\">-ae -a, <i>num card</i></div><div class=\"ori\">[octo/centum]</div><div class=\"def\">800(の).</div>\r\n","<div class=\"hw\">octipēs</div><div class=\"pos\">-pedis, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://octō\">octō</a>/pes]</div><div class=\"def\">8本足の.</div>\r\n","<div class=\"hw\">octiēs, -ens</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[octo]</div><div class=\"def\">8回[倍].</div>\r\n","<div class=\"hw\">Octodūrus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">オクトドゥールス《Gallia Narbonensis の町;現 Martigny》.</div>\r\n","<div class=\"hw\">Octogēsa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">オクトゲーサ《Hispania Tarraconensis の町;Hiberus 河畔にあった》.</div>\r\n","<div class=\"hw\">octuplicātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://octuplus\">octuplus</a>]</div><div class=\"def\">8倍した.</div>\r\n","<div class=\"hw\">octuplus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[octo(<i>cf</i>. duplus)]</div><div class=\"def\">8重の, 8倍の.</div>\r\n","<div class=\"hw\">octussis</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[octo/as]</div><div class=\"def\">8 asses の金額.</div>\r\n","<div class=\"hw\">octāva</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[octavus]</div><div class=\"def\"><num>①</num> (<i>sc. </i> hora)第8時.</div><div class=\"def\"><num>②</num> (<i>sc. </i> pars)八分の一税.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘聖〙祝日から8日目[8日間].</div>\r\n","<div class=\"hw\">Octāvia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">オクターウィア《Octavia 氏族の女;特に (1) Augustus 帝の姉;C. Marcellus の, 後に M. Antonius の妻.(2) Claudius 帝の娘で Nero 帝の妻》.</div>\r\n","<div class=\"hw\">Octāvius<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">オクターウィウス《ローマ人の氏族名;特に <i>C. ～</i>, のちの Augustus 帝》.</div><hr><div class=\"hw\">Octāvius<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Octavius の.</div>\r\n","<div class=\"hw\">Octāviānus<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">オクターウィアーヌス《C. Octavius(のちの Augustus 帝)が Caesar の養子となったときにつけられた名(C. Julius Caesar ～)》.</div><hr><div class=\"hw\">Octāviānus<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Octāvius\">Octavius<SUP>2</SUP></a>.</div><div class=\"hw2\"><b>Octāviānī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Octavius の軍勢.</div>\r\n","<div class=\"hw\">octāvum</div><div class=\"pos\"><i>adv</i>(<i>neut</i>)</div><div class=\"ori\">[↓<a href=\"entry://octāvus\">octāvus</a>]</div><div class=\"def\">8回目に.</div>\r\n","<div class=\"hw\">octāvus</div><div class=\"pos\">-a -um, <i>num ord</i></div><div class=\"ori\">[octo]</div><div class=\"def\">第8の, 8番目の;8分の1の.</div>\r\n","<div class=\"hw\">octāvusdecimus</div><div class=\"pos\">-a -um, <i>num ord</i></div><div class=\"ori\">[↑<a href=\"entry://octāvus\">octāvus</a>/decimus]</div><div class=\"def\">18番目の, 第18の;18分の1の.</div>\r\n","<div class=\"hw\">octāvānus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[octavus]</div><div class=\"def\">第8軍団の兵士.</div>\r\n","<div class=\"hw\">octāvārium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[octavus]</div><div class=\"def\">八分の一税.</div>\r\n","<div class=\"hw\">octō</div><div class=\"pos\"><i>indecl num card</i></div><div class=\"def\">8(の).</div>\r\n","<div class=\"hw\">Octōber<SUP>1</SUP></div><div class=\"pos\">-bris -bre, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://octō\">octō</a>]</div><div class=\"def\">(ローマ古暦の)8月の;(前153年以降)10月の.</div><hr><div class=\"hw\">Octōber<SUP>2</SUP></div><div class=\"pos\">-bris, <i>m</i></div><div class=\"def\">(<i>sc. </i> mensis)(ローマ古暦の)8月;(前153年以降)10月.</div>\r\n","<div class=\"hw\">octōdecim</div><div class=\"pos\"><i>indecl num card</i></div><div class=\"ori\">[octo/decem]</div><div class=\"def\">18(の).</div>\r\n","<div class=\"hw\">octōgintā</div><div class=\"pos\"><i>indecl num card</i></div><div class=\"ori\">[octo]</div><div class=\"def\">80(の).</div>\r\n","<div class=\"hw\">octōgiēs, -ens</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://octōgintā\">octōgintā</a>]</div><div class=\"def\">80回[倍].</div>\r\n","<div class=\"hw\">octōgēnārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://octōgēnī\">octōgēnī</a>]</div><div class=\"def\"><num>①</num> 80から成る.</div><div class=\"def\"><num>②</num> 80歳の.</div>\r\n","<div class=\"hw\">octōgēnī</div><div class=\"pos\">-ae -a, <i>num distrib</i></div><div class=\"ori\">[octoginta]</div><div class=\"def\">80ずつの.</div>\r\n","<div class=\"hw\">octōgēsimus, -gensimus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[octoginta]</div><div class=\"def\">80番目の, 第80の;80分の1の.</div>\r\n","<div class=\"hw\">octōjugis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[octo/jugum]</div><div class=\"def\">8頭立ての;8人いっしょの.</div>\r\n","<div class=\"hw\">octōnārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://octōnī\">octōnī</a>]</div><div class=\"def\">8個から成る.</div>\r\n","<div class=\"hw\">octōnī</div><div class=\"pos\">-ae -a, <i>num distrib</i></div><div class=\"ori\">[octo]</div><div class=\"def\">8ずつ(の).</div>\r\n","<div class=\"hw\">octōvir</div><div class=\"pos\">-virī, <i>m</i></div><div class=\"ori\">[octo/vir]</div><div class=\"def\">《碑》八人委員の一人.</div>\r\n","<div class=\"hw\">oculeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[oculus]</div><div class=\"def\"><num>①</num> 目がたくさんある.</div><div class=\"def\"><num>②</num> 眼力の鋭い.</div>\r\n","<div class=\"hw\">oculissimus</div><div class=\"pos\">-a -um, <i>adj superl</i></div><div class=\"ori\">[oculus]</div><div class=\"def\">最もいとしい, 最愛の《喜劇で用いられる表現》.</div>\r\n","<div class=\"hw\">oculomōtōrius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙眼球運動の;動眼神経の.</div>\r\n","<div class=\"hw\">oculus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 目</div><div class=\"ex\"><i>mundi ～</i> (<author>O<small>V</small></author>)<span class=\"ext\">世界の目(=太陽神).</span></div><div class=\"def\"><num>②</num> (通例 <i>pl</i>)視力, 視覚</div><div class=\"ex\"><i>oculos amittere</i> (<author>C<small>AES</small></author>)<span class=\"ext\">失明する.</span></div><div class=\"def\"><num>③</num> 目つき, まなざし.</div><div class=\"def\"><num>④</num> 見る[見える]こと</div><div class=\"ex\"><i>ante oculos patris facere infanda</i> (<author>L<small>IV</small></author>)<span class=\"ext\">父親の見ている前で言語道断のことをする.</span></div><div class=\"def\"><num>⑤</num> 視界, 視野.</div><div class=\"def\"><num>⑥</num> 注視, 注目.</div><div class=\"def\"><num>⑦</num> 慧眼, 眼識.</div><div class=\"def\"><num>⑧</num> 心の目</div><div class=\"ex\"><i>ponere alqd ante oculos</i> (<author>C<small>IC</small></author>)<span class=\"ext\">あることを眼前に思い描く</span></div><div class=\"ex\"><i>in oculis esse alcis [alci]</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ある人に非常に愛されている</span></div><div class=\"ex\"><i>alqm in oculis ferre</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ある人を愛する.</span></div><div class=\"def\"><num>⑨</num> 際立ったもの, 花形.</div><div class=\"def\"><num>⑩</num> 眼状のもの《くじゃくの尾の羽紋など》.</div><div class=\"def\"><num>⑪</num> 芽, つぼみ.</div>\r\n","<div class=\"hw\">oculāre</div><div class=\"pos\">-is, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↓<a href=\"entry://oculāris\">oculāris</a>]</div><div class=\"def\">眼薬.</div>\r\n","<div class=\"hw\">oculāris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[oculus]</div><div class=\"def\">目の.</div>\r\n","<div class=\"hw\">oculārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[oculus]</div><div class=\"def\">目の.</div><hr><div class=\"hw\">oculārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">(<i>sc. </i> medicus)眼科医.</div>\r\n","<div class=\"hw\">oculāta</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://oculātus\">oculātus</a>]</div><div class=\"def\">〘魚〙目のような模様のある魚.</div>\r\n","<div class=\"hw\">oculātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[oculus]</div><div class=\"def\"><num>①</num> 目の付いている, 目の見える</div><div class=\"ex\"><i>testis</i> ～ (<author>P<small>LAUT</small></author>)<span class=\"ext\">目撃者.</span></div><div class=\"def\"><num>②</num> 目に見える, 目立つ.</div><div class=\"def\"><num>③</num> 人目の多い.</div>\r\n","<div class=\"hw\">oculō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[oculus]</div><div class=\"def\"><num>①</num> 目を与える, 目が見えるようにする.</div><div class=\"def\"><num>②</num> 啓発する.</div><div class=\"def\"><num>③</num> 目に見えるようにする, 目立たせる.</div>\r\n","<div class=\"hw\">odium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[odi]</div><div class=\"def\"><num>①</num> 憎しみ, 嫌悪, 反感.</div><div class=\"def\"><num>②</num> 嫌われていること, 不評</div><div class=\"ex\"><i>in odio esse</i> (<author>C<small>IC</small></author>)<span class=\"ext\">嫌われている</span></div><div class=\"ex\"><i>in</i> ～ <i>venire</i> (<author>C<small>IC</small></author>)<span class=\"ext\">憎しみを買う.</span></div><div class=\"def\"><num>③</num> 憎悪の対象.</div>\r\n","<div class=\"hw\">odiōsicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://odiōsus\">odiosus</a>《喜劇で用いられる表現》.</div>\r\n","<div class=\"hw\">odiōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[odium]</div><div class=\"def\"><num>①</num> 不快感を与える, いやな.</div><div class=\"def\"><num>②</num> うんざりさせる, 退屈な.</div>\r\n","<div class=\"hw\">odiōsē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[odiosus]</div><div class=\"def\">不快感を与えるように, いやらしく.</div>\r\n","<div class=\"hw\">Odomantī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オドマンティー, <SUP>*</SUP>-テス《Thracia にいた一部族》.</div>\r\n","<div class=\"hw\">odontalgia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">歯痛.</div>\r\n","<div class=\"hw\">odontītis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">歯痛に効くといわれる植物《おそらくコゴメグサ》.</div>\r\n","<div class=\"hw\">odor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"def\"><num>①</num> 匂い.</div><div class=\"def\"><num>②</num> 芳香;悪臭.</div><div class=\"def\"><num>③</num> (<i>pl</i>)香料, 香油.</div><div class=\"def\"><num>④</num> 気味, 気配.</div>\r\n","<div class=\"hw\">Odrysae, Odru-</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オドリュサエ, <SUP>*</SUP>-サイ《Thracia の Hebrus 河畔にいた一部族》.</div>\r\n","<div class=\"hw\">Odrysius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Odrysae 族の;《詩》Thracia の.</div>\r\n","<div class=\"hw\">Odyssēa, -īa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オデュッセーア, <SUP>*</SUP>-セイア《 (1) <i>Ilias</i> と並ぶ Homerus の長編叙事詩;Troja 攻略後の Odysseus(=<a href=\"entry://Ulixēs\">Ulixes</a>)の放浪・冒険を語る.(2)  (1) の Livius Andronicus によるラテン語訳》.</div>\r\n","<div class=\"hw\">odōrifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[odor/fero]</div><div class=\"def\"><num>①</num> 芳香を放つ, 香りのよい.</div><div class=\"def\"><num>②</num> 香料を産する.</div>\r\n","<div class=\"hw\">odōror</div><div class=\"pos\">-ārī -ātus sum, <i>tr dep</i></div><div class=\"ori\">[odor]</div><div class=\"def\"><num>①</num> 匂いをかぐ.</div><div class=\"def\"><num>②</num> かぎつける, かぎとる;捜し出す.</div><div class=\"def\"><num>③</num> 熱望する.</div><div class=\"def\"><num>④</num> (学問などを)生かじりする.</div>\r\n","<div class=\"hw\">odōrus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[odor]</div><div class=\"def\"><num>①</num> 芳香を放つ, 香りのよい.</div><div class=\"def\"><num>②</num> 鋭い嗅覚の.</div>\r\n","<div class=\"hw\">odōrābilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[odoror]</div><div class=\"def\">匂いでわかる.</div>\r\n","<div class=\"hw\">odōrāmen</div><div class=\"pos\">-minis, <SUP>◇</SUP><i>n</i></div><div class=\"def\">=<a href=\"entry://odōrāmentum\">odoramentum</a>.</div>\r\n","<div class=\"hw\">odōrāmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">香料, 香油.</div>\r\n","<div class=\"hw\">odōrārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[odor]</div><div class=\"def\">香りづけに用いられる.</div>\r\n","<div class=\"hw\">odōrātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[odoror]</div><div class=\"def\">嗅覚.</div>\r\n","<div class=\"hw\">odōrātus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[odoror]</div><div class=\"def\">匂いのする;香りのよい.</div><hr><div class=\"hw\">odōrātus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 匂いをかぐこと.</div><div class=\"def\"><num>②</num> 嗅覚.</div><div class=\"def\"><num>③</num> 匂い.</div>\r\n","<div class=\"hw\">odōrō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[odor]</div><div class=\"def\">香りをつける, 香りで満たす.</div>\r\n","<div class=\"hw\">odōs</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"def\">《古形》=<a href=\"entry://odor\">odor</a>.</div>\r\n","<div class=\"hw\">Oea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">オエア《Africa の沿岸の町;現 Tripoli》.</div>\r\n","<div class=\"hw\">Oeager, -grus</div><div class=\"pos\">-grī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙オエアゲル, <SUP>*</SUP>オイアグロス《Thracia の王で Orpheus の父》.</div>\r\n","<div class=\"hw\">Oeagrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Oeager(の子孫)の;《詩》Thracia の.</div>\r\n","<div class=\"hw\">Oebalia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">《詩》=<a href=\"entry://Tarentum\">Tarentum</a>.</div>\r\n","<div class=\"hw\">Oebalidēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">Oebalus の子孫(=<a href=\"entry://Hyacinthus\">Hyacinthus</a>;<a href=\"entry://Pollux\">Pollux</a>;(<i>pl</i>)<a href=\"entry://Castor\">Castor</a> と <a href=\"entry://Pollux\">Pollux</a>).</div>\r\n","<div class=\"hw\">Oebalis</div><div class=\"pos\">-idis, <i>adj f</i></div><div class=\"def\">Oebalus の;Sparta の</div><div class=\"ex\"><i>～ nympha</i> (<author>O<small>V</small></author>)<span class=\"ext\">=<a href=\"entry://Helena\">Helena</a>.</span></div>\r\n","<div class=\"hw\">Oebalius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Oebalus の;Sparta の.</div>\r\n","<div class=\"hw\">Oebalus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙オエバルス, <SUP>*</SUP>オイバロス《Sparta の王;Tyndareus の父で Helena の祖父》.</div>\r\n","<div class=\"hw\">Oechalia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オエカリア, <SUP>*</SUP>オイカリアー《 (1) Euboea 島の町.(2) Messenia の町》.</div>\r\n","<div class=\"hw\">Oechalis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"def\">Oechalia の女.</div>\r\n","<div class=\"hw\">Oecleus</div><div class=\"pos\">-eī [-eos], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙オエクレウス, <SUP>*</SUP>オイ-《Amphiaraus の父で Alcmaeon の祖父》.</div>\r\n","<div class=\"hw\">Oeclīdēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Oecleus の息子(=<a href=\"entry://Amphiarāus\">Amphiaraus</a>).</div>\r\n","<div class=\"hw\">oeconomia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(弁論・劇などにおける)素材の配置.</div>\r\n","<div class=\"hw\">oeconomicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 家政の, 家庭経済の.</div><div class=\"def\"><num>②</num> (素材の配置が)秩序立った, 整然とした.</div>\r\n","<div class=\"hw\">Oeconomicus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">「家政論」《Xenophon の著作の題名》.</div>\r\n","<div class=\"hw\">oeconomus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">家政の切り盛りをする人;執事.</div>\r\n","<div class=\"hw\">oecos</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">部屋, 広間.</div>\r\n","<div class=\"hw\">oecūmenicus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> (人の住む)全世界の.</div><div class=\"def\"><num>②</num> 全キリスト教会の.</div>\r\n","<div class=\"hw\">oecūmenē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">人の住む世界.</div>\r\n","<div class=\"hw\">Oedipodēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">=<a href=\"entry://Oedipūs\">Oedipus</a>.</div>\r\n","<div class=\"hw\">Oedipodīonidēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">Oedipus の息子(=<a href=\"entry://Eteoclēs\">Eteocles</a> または <a href=\"entry://Polynīcēs\">Polynices</a>).</div>\r\n","<div class=\"hw\">Oedipodīonius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Oedipus の.</div>\r\n","<div class=\"hw\">Oedipūs</div><div class=\"pos\">-podos [-podis], <B>-us</B> -ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙オエディプース, <SUP>*</SUP>オイ-《Thebae の王 Laius と Iocasta の息子;それとは知らずに父を殺したあと, Sphinx の謎を解いて Thebae の王位を得, 知らずに母と結婚した;のち真相を知ると, 自ら眼をくり抜いた》.</div>\r\n","<div class=\"hw\">oedēma</div><div class=\"pos\">-atis, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘病〙水腫, 浮腫</div><div class=\"ex\"><i>～ malignum</i><span class=\"ext\">悪性水腫</span></div><div class=\"ex\"><i>～ pulmonum</i><span class=\"ext\">肺水腫.</span></div>\r\n","<div class=\"hw\">Oeensēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"def\">Oea の住民.</div>\r\n","<div class=\"hw\">oenanthē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 野ブドウの房.</div><div class=\"def\"><num>②</num> 〘植〙ロクベンシモツケ.</div><div class=\"def\"><num>③</num> 〘鳥〙渡り鳥の一種.</div>\r\n","<div class=\"hw\">Oeneus<SUP>1</SUP></div><div class=\"pos\">-eī [-eos], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙オエネウス, <SUP>*</SUP>オイ-《Calydon の王;Althaea の夫で Meleager や Deianira の父》.</div>\r\n","<div class=\"hw\">Oeniadae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オエニアダエ, <SUP>*</SUP>オイニアダイ《Acarnania の Achelous 川河口の町》.</div>\r\n","<div class=\"hw\">Oenomaus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙オエノマウス, <SUP>*</SUP>オイノマオス《Elis の Pisa の王;Hippodamia の父;Pelops の舅<SUB>しゅうと</SUB>》.</div>\r\n","<div class=\"hw\">oenophorum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ぶどう酒の容器.</div>\r\n","<div class=\"hw\">Oenopia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オエノピア, <SUP>*</SUP>オイノピアー《Aegina 島の古名》.</div>\r\n","<div class=\"hw\">Oenopius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Oenopia の.</div>\r\n","<div class=\"hw\">Oenopiōn</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙オエノピオーン, <SUP>*</SUP>オイ-《Chios 島の王;Merope の父》.</div>\r\n","<div class=\"hw\">oenopōlium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">酒屋.</div>\r\n","<div class=\"hw\">oenus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">《古形》=<a href=\"entry://ūnus\">unus<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">Oenēis</div><div class=\"pos\">-idis [-idos], <i>f</i></div><div class=\"def\">Oeneus の娘(=<a href=\"entry://Dēianīra\">Deianira</a>).</div>\r\n","<div class=\"hw\">Oenēius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Oeneus の.</div>\r\n","<div class=\"hw\">Oenēus<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Oenēius\">Oeneius</a>.</div>\r\n","<div class=\"hw\">Oenīdēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Oeneus の子孫(=息子 Meleager または Tydeus;孫 Diomedes).</div>\r\n","<div class=\"hw\">Oenōnē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙オエノーネー, <SUP>*</SUP>オイ-《予言の術と薬草の知識を持つ Phrygia のニンフ;Paris に愛されたが, 彼の愛が Helena に移って, 捨てられた》.</div>\r\n","<div class=\"hw\">Oenōtria</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オエノートリア, <SUP>*</SUP>オイノートリアー《 (1) イタリア南東端地方の古名.(2) 《詩》=<a href=\"entry://Italia\">Italia</a>》.</div>\r\n","<div class=\"hw\">Oenōtrius, -trus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Oenotria の;《詩》イタリアの.</div>\r\n","<div class=\"hw\">Oenōtrus<SUP>2</SUP></div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙オエノートルス, <SUP>*</SUP>オイノートロス《Oenotria の古い王》.</div>\r\n","<div class=\"hw\">Oenōtrī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イタリア南東端地方の住民;《詩》(一般に)イタリアの住民.</div>\r\n","<div class=\"hw\">Oenūs</div><div class=\"pos\">-untis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オエヌース, <SUP>*</SUP>オイ-《Laconia の川;Eurotas 川に注ぐ;現 Kelefina》.</div>\r\n","<div class=\"hw\">oesophagus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘解〙食道.</div>\r\n","<div class=\"hw\">oestrus, -os</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘昆〙アブ.</div><div class=\"def\"><num>②</num> (予言者・詩人が神から授かる)霊感, 激しい興奮.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘動〙発情(現象), 発情期.</div>\r\n","<div class=\"hw\">oesypum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">未洗浄の羊毛から採取される脂肪性物質《薬や化粧品に用いられた》.</div>\r\n","<div class=\"hw\">Oeta</div><div class=\"pos\">-ae, <B>-ē</B> -ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オエタ, <SUP>*</SUP>オイテー《Thessalia と Aetolia の間の山;その山頂で Hercules が焼身自殺したという》.</div>\r\n","<div class=\"hw\">Oetaeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Oeta 山の.</div>\r\n","<div class=\"hw\">ofella</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[↓<a href=\"entry://offa\">offa</a>]</div><div class=\"def\">(食べ物の)ひと口, 一片.</div>\r\n","<div class=\"hw\">offa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 小麦粉だんご.</div><div class=\"def\"><num>②</num> 一片, 塊り.</div><div class=\"def\"><num>③</num> 腫れ.</div><div class=\"def\"><num>④</num> 堕胎した胎児.</div>\r\n","<div class=\"hw\">offectus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://officiō\">officio</a>.</div><hr><div class=\"hw\">offectus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">有害な影響(力).</div>\r\n","<div class=\"hw\">offendiculum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://offendō\">offendō</a>]</div><div class=\"def\">障害(物), つまずきの石.</div>\r\n","<div class=\"hw\">offendī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://offendō\">offendo</a>.</div>\r\n","<div class=\"hw\">offendō</div><div class=\"pos\">-ere -fendī -fensum, <i>intr</i>, <i>tr</i></div><div class=\"ori\">[ob-/<SUP>*</SUP>fendo(<i>cf. </i> defendo)]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>intr</i>)</div><div class=\"def\"><num>①</num> ぶつかる, 衝突する;座礁する;(困難・災難などに)遭遇する 〈in re [alqd];alci rei〉.</div><div class=\"def\"><num>②</num> 間違いをする, あやまちを犯す.</div><div class=\"def\"><num>③</num> 感情を害する, 怒らせる 〈<i>abs</i>〉.</div><div class=\"def\"><num>④</num> 気を悪くする, 怒る 〈in alqm〉.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>tr</i>)</div><div class=\"def\"><num>①</num> ぶつかる [ぶつける], 衝突する[させる] 〈alqd;alqd ad alqd〉.</div><div class=\"def\"><num>②</num> 食い止める, はばむ.</div><div class=\"def\"><num>③</num> (人を)ぶつ, なぐる.</div><div class=\"def\"><num>④</num> 見つける, 出くわす</div><div class=\"ex\"><i>imparatum te offendam</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私はあなたの不意をつくだろう.</span></div><div class=\"def\"><num>⑤</num> 害する, そこなう.</div><div class=\"def\"><num>⑥</num> 感情を害する, 怒らせる.</div><div class=\"def\"><num>⑦</num> (<i>pass</i>)気を悪くする, 怒る 〈(in)re〉.</div>\r\n","<div class=\"hw\">offensa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://offendō\">offendō</a>]</div><div class=\"def\"><num>①</num> 衝突, ぶつかること.</div><div class=\"def\"><num>②</num> 苦痛, 不快.</div><div class=\"def\"><num>③</num> 損害, 危害, 不正.</div><div class=\"def\"><num>④</num> 感情を害すること, 侮辱, 無礼.</div><div class=\"def\"><num>⑤</num> 憤懣<SUB>ふんまん</SUB>, 恨み, 不興.</div>\r\n","<div class=\"hw\">offensiuncula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[↑<a href=\"entry://offensiō\">offensiō</a>]</div><div class=\"def\"><num>①</num> (小さな)憤懣.</div><div class=\"def\"><num>②</num> (小さな)失敗, 挫折.</div>\r\n","<div class=\"hw\">offensiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[offendo]</div><div class=\"def\"><num>①</num> 衝突, ぶつかること.</div><div class=\"def\"><num>②</num> つまずくこと.</div><div class=\"def\"><num>③</num> 障害(物), じゃま(物).</div><div class=\"def\"><num>④</num> 失敗, 挫折.</div><div class=\"def\"><num>⑤</num> 苦痛, 不快.</div><div class=\"def\"><num>⑥</num> 損害.</div><div class=\"def\"><num>⑦</num> 感情を害すること.</div><div class=\"def\"><num>⑧</num> 憤懣, 恨み, 不興.</div>\r\n","<div class=\"hw\">offensor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[offendo]</div><div class=\"def\">(他人の)感情を害する者[もの].</div>\r\n","<div class=\"hw\">offensus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[offendo]</div><div class=\"def\"><num>①</num> 不快な, いやな, 憎むべき.</div><div class=\"def\"><num>②</num> 感情を害された, 憤慨している 〈alci〉.</div><hr><div class=\"hw\">offensus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 衝突, ぶつかること.</div><div class=\"def\"><num>②</num> 苦痛, 不快.</div>\r\n","<div class=\"hw\">offensāculum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[offenso]</div><div class=\"def\">つまづかせるもの, 障害物.</div>\r\n","<div class=\"hw\">offensātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[offenso]</div><div class=\"def\"><num>①</num> 衝突;つまずくこと.</div><div class=\"def\"><num>②</num> どもる[口ごもる]こと.</div>\r\n","<div class=\"hw\">offensātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[offenso]</div><div class=\"def\">つまずかせるもの.</div>\r\n","<div class=\"hw\">offensō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>, <i>intr freq</i></div><div class=\"ori\">[offendo]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>tr</i>)ぶつかる, 衝突する;ぶつける.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>intr</i>)つまずく;(ことばが)つかえる.</div>\r\n","<div class=\"hw\">offerentia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://offerō\">offerō</a>]</div><div class=\"def\">起こること, 出現.</div>\r\n","<div class=\"hw\">offerre</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://offerō\">offero</a>.</div>\r\n","<div class=\"hw\">offerō</div><div class=\"pos\">offerre obtulī oblātum, <i>tr</i></div><div class=\"ori\">[ob-/fero]</div><div class=\"def\"><num>①</num> 前に置く, 出会わせる;(<i>refl</i>, <i>pass</i>)前に現われる, 出会う.</div><div class=\"def\"><num>②</num> (危険などに)さらす, 投げ出す.</div><div class=\"def\"><num>③</num> 示す, 現わす, 見せる;(<i>refl</i>, <i>pass</i>)現われる.</div><div class=\"def\"><num>④</num> 気づかせる, 目に留めさせる;(<i>refl</i>, <i>pass</i>)(心に)浮かぶ, 思い当たる.</div><div class=\"def\"><num>⑤</num> 差し出す, 提供する;提供を申し出る.</div><div class=\"def\"><num>⑥</num> ひき起こす, もたらす.</div>\r\n","<div class=\"hw\">offerūmenta</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>cf</i>. ferrumen]</div><div class=\"def\">むち打ち傷, みみず腫れ.</div>\r\n","<div class=\"hw\">officere</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://officiō\">officio</a>.</div>\r\n","<div class=\"hw\">officians</div><div class=\"pos\">-antis, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[officium]</div><div class=\"def\">(祭式などの)執行者.</div>\r\n","<div class=\"hw\">officium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[opus/facio]</div><div class=\"def\"><num>①</num> 奉仕, 尽力.</div><div class=\"def\"><num>②</num> 敬意を表すること;表敬[儀礼的]訪問;儀礼, 儀式.</div><div class=\"def\"><num>③</num> 義務, 責務.</div><div class=\"def\"><num>④</num> 務め, 任務.</div><div class=\"def\"><num>⑤</num> 職務に忠実なこと</div><div class=\"ex\"><i>vir summo officio praeditus</i> (<author>C<small>IC</small></author>)<span class=\"ext\">きわめて責任感の強い男.</span></div><div class=\"def\"><num>⑥</num> 職, 地位.</div><div class=\"def\"><num>⑦</num> 官僚, 役人.</div><div class=\"def\"><num>⑧</num> <SUP>◇</SUP>〘キ教〙聖務日課.</div>\r\n","<div class=\"hw\">officiālis<SUP>1</SUP></div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[officium]</div><div class=\"def\">義務[職務]の.</div><hr><div class=\"hw\">officiālis<SUP>2</SUP></div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\"><num>①</num> 高官の従者, 下級役人.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 従者, 従僕.</div>\r\n","<div class=\"hw\">officiō</div><div class=\"pos\">-cere -fēcī -fectum, <i>intr</i>(<i>tr</i>)</div><div class=\"ori\">[ob-/facio]</div><div class=\"def\"><num>①</num> 妨げる, じゃまする 〈+<i>dat</i>〉.</div><div class=\"def\"><num>②</num> (光・視界を)さえぎる.</div>\r\n","<div class=\"hw\">officiōsus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[officium]</div><div class=\"def\"><num>①</num> 義務に忠実な, 律儀な.</div><div class=\"def\"><num>②</num> 礼儀正しい, 親切な.</div><div class=\"def\"><num>③</num> さしでがましい, おせっかいな.</div><hr><div class=\"hw\">officiōsus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">浴場の脱衣場係.</div>\r\n","<div class=\"hw\">officiōsē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://officiōsus\">officiōsus<SUP>1</SUP></a>]</div><div class=\"def\">義務に忠実に, 敬意を表して.</div>\r\n","<div class=\"hw\">officīna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[opificina]</div><div class=\"def\"><num>①</num> 工場, 仕事場.</div><div class=\"def\"><num>②</num> 訓練所, 養成所.</div>\r\n","<div class=\"hw\">officīnātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[↑<a href=\"entry://officīna\">officīna</a>]</div><div class=\"def\">職工長.</div>\r\n","<div class=\"hw\">offirmātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[↓<a href=\"entry://offirmō\">offirmō</a>]</div><div class=\"def\">断固とした, 頑固な.</div>\r\n","<div class=\"hw\">offirmātē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://offirmātus\">offirmātus</a>]</div><div class=\"def\">頑固に.</div>\r\n","<div class=\"hw\">offirmō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>(<i>intr</i>)</div><div class=\"ori\">[ob-/firmo]</div><div class=\"def\"><num>①</num> 強固[堅固]にする.</div><div class=\"def\"><num>②</num> (意志を)固くする.</div><div class=\"def\"><num>③</num> 固く決心する.</div>\r\n","<div class=\"hw\">offixus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://offīgō\">offigo</a>.</div>\r\n","<div class=\"hw\">offixī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://offīgō\">offigo</a>.</div>\r\n","<div class=\"hw\">offla</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://offula\">offula</a>.</div>\r\n","<div class=\"hw\">offlectō</div><div class=\"pos\">-ere, <i>tr</i></div><div class=\"ori\">[ob-/flecto]</div><div class=\"def\">(...の方へ)向ける.</div>\r\n","<div class=\"hw\">offringō</div><div class=\"pos\">-ere -frēgī -fractum, <i>tr</i></div><div class=\"ori\">[ob-/frango]</div><div class=\"def\">再び鋤<SUB>す</SUB>く, 鋤き直す.</div>\r\n","<div class=\"hw\">offrēnātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ob-/freno]</div><div class=\"def\">抑制された;手なずけられた.</div>\r\n","<div class=\"hw\">offula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[offa]</div><div class=\"def\">(肉の)小片.</div>\r\n","<div class=\"hw\">offulcio</div><div class=\"pos\">-īre -fulsī -fultum, <i>tr</i></div><div class=\"ori\">[ob-/fulcio]</div><div class=\"def\">(穴などを)ふさぐ.</div>\r\n","<div class=\"hw\">offulgeō</div><div class=\"pos\">-ēre -fulsī, <i>intr</i></div><div class=\"ori\">[ob-/fulgeo]</div><div class=\"def\">向かって輝く.</div>\r\n","<div class=\"hw\">offulsī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://offulcio\">offulcio</a>, <a href=\"entry://offulgeō\">offulgeo</a>.</div>\r\n","<div class=\"hw\">offundō</div><div class=\"pos\">-ere -fūdī -fūsum, <i>tr</i></div><div class=\"ori\">[ob-/fundo<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> (一面に)注ぎかける 〈alqd alci re〉.</div><div class=\"def\"><num>②</num> おおう 〈alqd re〉.</div><div class=\"def\"><num>③</num> 満たす, 圧倒する 〈alqd re〉.</div>\r\n","<div class=\"hw\">offuscō</div><div class=\"pos\">-āre -ātum, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[ob-/fusco]</div><div class=\"def\"><num>①</num> 暗くする.</div><div class=\"def\"><num>②</num> 堕落させる.</div>\r\n","<div class=\"hw\">offātim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://offa\">offa</a>]</div><div class=\"def\">こまぎれに.</div>\r\n","<div class=\"hw\">offēcī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://officiō\">officio</a>.</div>\r\n","<div class=\"hw\">offīgō</div><div class=\"pos\">-ere -fixī -fixum, <i>tr</i></div><div class=\"ori\">[ob-/figo]</div><div class=\"def\"><num>①</num> (杭などを)打ち込む.</div><div class=\"def\"><num>②</num> 打ちつける, 固定する.</div>\r\n","<div class=\"hw\">offōcō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"ori\">[ob-/fauces]</div><div class=\"def\">首を締める, 窒息させる.</div>\r\n","<div class=\"hw\">offūcia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[ob-/fucus<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> えのぐ, 顔料.</div><div class=\"def\"><num>②</num> 詐欺, ペテン.</div>\r\n","<div class=\"hw\">offūdī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://offundō\">offundo</a>.</div>\r\n","<div class=\"hw\">offūsus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://offundō\">offundo</a>.</div>\r\n","<div class=\"hw\">ogganniō</div><div class=\"pos\">-īre -īvī [-iī] -ītum, <i>intr</i></div><div class=\"ori\">[ob-/gannio]</div><div class=\"def\"><num>①</num> どなる.</div><div class=\"def\"><num>②</num> つぶやく, ブツブツ言う.</div>\r\n","<div class=\"hw\">oggerō</div><div class=\"pos\">-ere, <i>tr</i></div><div class=\"ori\">[ob-/gero]</div><div class=\"def\">(大量に)差し出す, 与える.</div>\r\n","<div class=\"hw\">Ogulnius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">オグルニウス《ローマの氏族名》.</div>\r\n","<div class=\"hw\"><img class=\"font\" src=\"img/A13A.png\">hē</div><div class=\"pos\"><i>int</i></div><div class=\"def\">おーい, おいこら.</div>\r\n","<div class=\"hw\">oiei</div><div class=\"pos\"><i>int</i></div><div class=\"def\">(苦痛・苦悩を表わす)痛い, あいた.</div>\r\n","<div class=\"hw\">Olbia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オルビア《いくつかの町の名;特に Sardinia 島東岸の港町》.</div>\r\n","<div class=\"hw\">Olbiensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">(Sardinia 島の)Olbia の.</div>\r\n","<div class=\"hw\">Olcinium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">オルキニウム《Illyria の港町》.</div>\r\n","<div class=\"hw\">Olciniātae</div><div class=\"pos\">-ārum, <B>-ēs</B> -(i)um, <i>m pl</i></div><div class=\"def\">Olcinium の住民.</div>\r\n","<div class=\"hw\">olea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[oliva]</div><div class=\"def\">〘植〙</div><div class=\"def\"><num>①</num> オリーブ(の実).</div><div class=\"def\"><num>②</num> オリーブの木.</div>\r\n","<div class=\"hw\">oleaster</div><div class=\"pos\">-trī, <i>m</i></div><div class=\"ori\">[olea]</div><div class=\"def\">野生オリーブ.</div>\r\n","<div class=\"hw\">olens</div><div class=\"pos\">-entis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[oleo]</div><div class=\"def\"><num>①</num> 香りの強い[よい].</div><div class=\"def\"><num>②</num> 悪臭を放つ.</div><div class=\"def\"><num>③</num> かび臭い.</div>\r\n","<div class=\"hw\">olentia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↑<a href=\"entry://olens\">olens</a>]</div><div class=\"def\">香り, 香気.</div>\r\n","<div class=\"hw\">olenticētum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[oleo]</div><div class=\"def\">悪臭のする場所.</div>\r\n","<div class=\"hw\">olerāceus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[(h)olus]</div><div class=\"def\">草本状の.</div>\r\n","<div class=\"hw\">oleum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> オリーブ油</div><div class=\"ex\">～ <i>et operam perdere</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">(ランプを灯す)油と骨折り(=時間と労力)を無駄にする.</span></div><div class=\"def\"><num>②</num> 格闘技《レスラーが身体に油を塗ったことから》.</div><div class=\"def\"><num>③</num> (その他の)油</div><div class=\"ex\">～ <i>sesamae</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">ゴマ油</span></div><div class=\"ex\">～ <i>ex rosa</i> (<author>G<small>ELL</small></author>)<span class=\"ext\">ローズ油</span></div><div class=\"ex\"><SUP>◇</SUP>～ <i>jecoris</i><span class=\"ext\">肝油</span></div><div class=\"ex\"><SUP>◇</SUP>～ <i>menthae</i><span class=\"ext\">ハッカ油.</span></div>\r\n","<div class=\"hw\">oleāgineus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://olea\">olea</a>]</div><div class=\"def\"><num>①</num> オリーブの木の.</div><div class=\"def\"><num>②</num> オリーブ材で作った;オリーブの葉で作った.</div><div class=\"def\"><num>③</num> オリーブの実[葉]のような.</div>\r\n","<div class=\"hw\">oleāginus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[olea]</div><div class=\"def\"><num>①</num> オリーブの木の.</div><div class=\"def\"><num>②</num> オリーブ色の.</div>\r\n","<div class=\"hw\">oleāmen</div><div class=\"pos\">-inis, <i>n</i></div><div class=\"ori\">[oleum]</div><div class=\"def\">オリーブ油で作った軟膏.</div>\r\n","<div class=\"hw\">oleāmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://oleāmen\">oleamen</a>.</div>\r\n","<div class=\"hw\">oleāris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[oleum]</div><div class=\"def\">(オリーブ)油の.</div>\r\n","<div class=\"hw\">oleārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[oleum]</div><div class=\"def\"><num>①</num> (オリーブ)油の.</div><div class=\"def\"><num>②</num> オリーブの.</div><hr><div class=\"hw\">oleārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">(オリーブ)油商人[製造人].</div>\r\n","<div class=\"hw\">oleō</div><div class=\"pos\">-ēre -luī, <i>intr</i></div><div class=\"ori\">[<i>cf. </i> odor]</div><div class=\"def\"><num>①</num> 匂いがする;悪臭[芳香]を放つ 〈+<i>adv</i>;re〉.</div><div class=\"def\"><num>②</num> (匂いによって)知れる, ばれる.</div>\r\n","<div class=\"hw\">oleōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[oleum]</div><div class=\"def\">油の多い.</div>\r\n","<div class=\"hw\">olfacere</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://olfaciō\">olfacio</a>.</div>\r\n","<div class=\"hw\">olfaciō</div><div class=\"pos\">-cere -fēcī -factum, <i>tr</i></div><div class=\"ori\">[oleo/facio]</div><div class=\"def\"><num>①</num> 匂い[香り]で知る;かぎつける.</div><div class=\"def\"><num>②</num> 匂いをかぐ.</div>\r\n","<div class=\"hw\">olfactus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://olfaciō\">olfacio</a>.</div><hr><div class=\"hw\">olfactus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 匂いをかぐこと.</div><div class=\"def\"><num>②</num> 嗅覚.</div><div class=\"def\"><num>③</num> 匂うこと.</div>\r\n","<div class=\"hw\">olfactātrix</div><div class=\"pos\">-īcis, <i>adj f</i></div><div class=\"ori\">[↓<a href=\"entry://olfactō\">olfactō</a>]</div><div class=\"def\">鼻がきく.</div>\r\n","<div class=\"hw\">olfactō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr freq</i></div><div class=\"ori\">[olfacio]</div><div class=\"def\">匂いをかぐ.</div>\r\n","<div class=\"hw\">olfactōrium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://olfactōrius\">olfactōrius</a>]</div><div class=\"def\">気付け瓶, かぎ瓶.</div>\r\n","<div class=\"hw\">olfactōrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[olfacio]</div><div class=\"def\">匂いをかぐための.</div>\r\n","<div class=\"hw\">olfēcī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://olfaciō\">olfacio</a>.</div>\r\n","<div class=\"hw\">olidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[oleo]</div><div class=\"def\"><num>①</num> 悪臭を放つ, いやな臭いのする.</div><div class=\"def\"><num>②</num> 芳香を放つ, 香りのよい.</div>\r\n","<div class=\"hw\">oligaemia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙血液過少(症), 乏血(症).</div>\r\n","<div class=\"hw\">oligomēnorrhoea</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙過少月経.</div>\r\n","<div class=\"hw\">oligophrenia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙精神薄弱.</div>\r\n","<div class=\"hw\">oligūria</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙尿量過少(症), 乏尿(症).</div>\r\n","<div class=\"hw\">olit-</div><div class=\"def\">⇒holit-.</div>\r\n","<div class=\"hw\">olla</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 壺, 瓶.</div><div class=\"def\"><num>②</num> 《碑》骨壺.</div>\r\n","<div class=\"hw\">olle, ollus</div><div class=\"pos\">-a -ud, <i>pron</i>, <i>adj</i></div><div class=\"def\">《古形》=<a href=\"entry://ille\">ille</a>.</div>\r\n","<div class=\"hw\">ollicula</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f dim</i></div><div class=\"ori\">[olla]</div><div class=\"def\">(小さな)壺.</div>\r\n","<div class=\"hw\">ollula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[olla]</div><div class=\"def\">(小さな)壺.</div>\r\n","<div class=\"hw\">ollārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://ollārius\">ollārius</a>]</div><div class=\"def\">(墓の中の)骨壺を置く場所.</div>\r\n","<div class=\"hw\">ollārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[olla]</div><div class=\"def\">壺を作るのに用いられる.</div>\r\n","<div class=\"hw\">olor<SUP>1</SUP></div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"def\">〘鳥〙ハクチョウ(白鳥).</div><hr><div class=\"hw\">olor<SUP>2</SUP></div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[oleo]</div><div class=\"def\">=<a href=\"entry://odor\">odor</a>.</div>\r\n","<div class=\"hw\">olus-</div><div class=\"def\">⇒holus-.</div>\r\n","<div class=\"hw\">oluī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://oleō\">oleo</a>.</div>\r\n","<div class=\"hw\">Olympia<SUP>1</SUP></div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オリュンピア(ー)《Elis のZeus(Juppiter)をまつる聖地;Olympia 競技祭の開催地》.</div><hr><div class=\"hw\">Olympia<SUP>2</SUP></div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オリュンピア競技祭《Olympia で4年ごとに行なわれた》.</div>\r\n","<div class=\"hw\">Olympiacus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Olympicus\">Olympicus</a>.</div>\r\n","<div class=\"hw\">Olympiades</div><div class=\"pos\">-um, <i>f pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Olympus 山に住む者たち(=Musae).</div>\r\n","<div class=\"hw\">Olympias<SUP>1</SUP></div><div class=\"pos\">-adis [-ados], <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> Olympia 競技祭の開催.</div><div class=\"def\"><num>②</num> オリュンピア紀《二つの Olympia 競技祭の間の4年間;最初の Olympias は前776年から》.</div><div class=\"def\"><num>③</num> 《詩》5年間(=<a href=\"entry://lustrum\">lustrum</a>).</div><hr><div class=\"hw\">Olympias<SUP>2</SUP></div><div class=\"pos\">-adis [-ados], <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オリュンピアス《Macedonia の王 Philippus II の妻で Alexander 大王の母》.</div><hr><div class=\"hw\">Olympias<SUP>3</SUP></div><div class=\"pos\">-adis [-ados], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(Euboea 島における)西北西の風.</div>\r\n","<div class=\"hw\">Olympicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Olympia 競技祭の.</div>\r\n","<div class=\"hw\">Olympionīcēs, -a</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Olympia 競技祭の勝者.</div>\r\n","<div class=\"hw\">Olympium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(Olympia<SUP>1</SUP> の)Zeus 神殿.</div>\r\n","<div class=\"hw\">Olympius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> Olympus 山の《Zeus(Juppiter)の添え名》.</div><div class=\"def\"><num>②</num> Olympia で開かれる</div><div class=\"ex\"><i>ludi Olympii</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">Olympia 競技.</span></div>\r\n","<div class=\"hw\">Olympiēum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://Olympium\">Olympium</a>.</div>\r\n","<div class=\"hw\">Olympus<SUP>1</SUP>, -os</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> オリュンプス, <SUP>*</SUP>-ポス, <SUP>∥</SUP>オリンポス《 (1) Macedonia と Thessalia の国境の高山;Zeus(Juppiter)を最高神とする神々がその山頂に住んだという.(2) Mysia の山.(3) Galatia の山》.</div><div class=\"def\"><num>②</num> (神々の住む)天.</div><hr><div class=\"hw\">Olympus<SUP>2</SUP>, -os</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オリュンプス, <SUP>*</SUP>-ポス《 (1) Lycia の町.(2) Cilicia の町》.</div><hr><div class=\"hw\">Olympus<SUP>3</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙オリュンプス, <SUP>*</SUP>-ポス《Phrygia の笛の名手;Marsyas の弟子》.</div>\r\n","<div class=\"hw\">Olympēnī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(Lycia の)Olympus の住民.</div>\r\n","<div class=\"hw\">Olynthius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Olynthus の.</div><div class=\"hw2\"><b>Olynthiī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Olynthus の住民.</div>\r\n","<div class=\"hw\">Olynthus, -os</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オリュントゥス, <SUP>*</SUP>-トス《Thracia の町;Philippus II に破壊された(前348)》.</div>\r\n","<div class=\"hw\">olētum<SUP>1</SUP></div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[olea]</div><div class=\"def\">オリーブ園.</div><hr><div class=\"hw\">olētum<SUP>2</SUP></div><div class=\"pos\">-ī, </div><div class=\"ori\">[oleo]</div><div class=\"def\">排泄物, 汚物.</div>\r\n","<div class=\"hw\">olīva</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘植〙オリーブ(の実).</div><div class=\"def\"><num>②</num> オリーブの木;オリーブの葉[枝].</div><div class=\"def\"><num>③</num> オリーブの杖.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>〘解〙(延髄の)オリーブ.</div>\r\n","<div class=\"hw\">olīvifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[oliva/fero]</div><div class=\"def\"><num>①</num> オリーブを産する.</div><div class=\"def\"><num>②</num> オリーブの枝で作られた.</div>\r\n","<div class=\"hw\">olīvitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[oliva]</div><div class=\"def\">オリーブの収穫.</div>\r\n","<div class=\"hw\">olīvum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[oliva]</div><div class=\"def\"><num>①</num> オリーブ油.</div><div class=\"def\"><num>②</num> 香油.</div><div class=\"def\"><num>③</num> 格闘技.</div>\r\n","<div class=\"hw\">olīvārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://olīva\">olīva</a>]</div><div class=\"def\">オリーブ(油)の.</div>\r\n","<div class=\"hw\">olīvētum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[oliva]</div><div class=\"def\">オリーブ園.</div>\r\n","<div class=\"hw\">olōrīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[olor<SUP>1</SUP>]</div><div class=\"def\">白鳥の.</div>\r\n","<div class=\"hw\">omarthrītis</div><div class=\"pos\">-idis, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙肩関節炎.</div>\r\n","<div class=\"hw\">omissiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[omitto]</div><div class=\"def\">省略, 無視.</div>\r\n","<div class=\"hw\">omissus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://omittō\">omitto</a>.</div>\r\n","<div class=\"hw\">omittō</div><div class=\"pos\">-ere -mīsī -missum, <i>tr</i></div><div class=\"ori\">[ob-/mitto]</div><div class=\"def\"><num>①</num> 行かせる, 解放する;逃がす.</div><div class=\"def\"><num>②</num> 捨てる, 放棄する.</div><div class=\"def\"><num>③</num> 退く, 撤退する.</div><div class=\"def\"><num>④</num> やめる, 中止する 〈+<i>inf</i>〉.</div><div class=\"def\"><num>⑤</num> 無視する, 顧みない.</div><div class=\"def\"><num>⑥</num> 言及しない, 省略する, 抜かす.</div><div class=\"def\"><num>⑦</num> ...しそこなう, 怠る 〈+<i>inf</i>;quominus〉.</div>\r\n","<div class=\"hw\">ommateum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘動〙(節足動物の)複眼.</div>\r\n","<div class=\"hw\">ommatidium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘動〙(ommateum を構成する)個眼.</div>\r\n","<div class=\"hw\">omne</div><div class=\"pos\">-is, <i>n</i></div><div class=\"ori\">[omnis]</div><div class=\"def\">あらゆるもの[こと]</div><div class=\"ex\"><i>per omnia</i> (<author>L<small>IV</small></author>)<span class=\"ext\">あらゆる点で</span></div><div class=\"ex\"><i>ante omnia</i> (<author>L<small>IV</small></author>)<span class=\"ext\">万事に先立って, まず第一に.</span></div>\r\n","<div class=\"hw\">omnicanus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[omnis/cano]</div><div class=\"def\">あらゆる調子の音を出す.</div>\r\n","<div class=\"hw\">omnicarpus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[omnis/carpo]</div><div class=\"def\">あらゆるものを摘み取る(=何でも食べる).</div>\r\n","<div class=\"hw\">omnicolor</div><div class=\"pos\">-ōris, <i>adj</i></div><div class=\"ori\">[omnis/color]</div><div class=\"def\">あらゆる色をもつ.</div>\r\n","<div class=\"hw\">omnifāriam</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[omnis/<i>cf</i>. bifariam]</div><div class=\"def\">いたるところで;あらゆる方法で.</div>\r\n","<div class=\"hw\">omnigenus<SUP>1</SUP></div><div class=\"pos\">-a -um または <i>indecl</i>, <i>adj</i></div><div class=\"ori\">[omnis/genus]</div><div class=\"def\">あらゆる種類の.</div><hr><div class=\"hw\">omnigenus<SUP>2</SUP></div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[omnis/gigno]</div><div class=\"def\">あらゆるものを生じさせる.</div>\r\n","<div class=\"hw\">omnimodus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[omnis/modus]</div><div class=\"def\">あらゆる種類の.</div>\r\n","<div class=\"hw\">omnimodīs</div><div class=\"pos\"><i>adv</i>(<i>pl abl</i>)</div><div class=\"ori\">[omnis/modus]</div><div class=\"def\">あらゆる方法で.</div>\r\n","<div class=\"hw\">omnimodō, omnī modō</div><div class=\"pos\"><i>adv</i>(<i>abl</i>)</div><div class=\"ori\">[omnis/modus]</div><div class=\"def\">あらゆる場合に, 常に.</div>\r\n","<div class=\"hw\">omniparens</div><div class=\"pos\">-entis, <i>adj</i></div><div class=\"ori\">[omnis/pario<SUP>2</SUP>]</div><div class=\"def\">万物を生む《通例, 大地を指す》.</div>\r\n","<div class=\"hw\">omnipater</div><div class=\"pos\">-tris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[omnis/pater]</div><div class=\"def\">万物の父.</div>\r\n","<div class=\"hw\">omnipotens<SUP>1</SUP></div><div class=\"pos\">-entis, <i>adj</i></div><div class=\"ori\">[omnis/potens]</div><div class=\"def\">全能の.</div><hr><div class=\"hw\">omnipotens<SUP>2</SUP></div><div class=\"pos\">-entis, <i>m</i></div><div class=\"def\">全能者《 (1) =<a href=\"entry://Juppiter\">Juppiter</a>.(2) <SUP>◇</SUP>〘キ教〙全能の神》.</div>\r\n","<div class=\"hw\">omnipotentia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[omnipotens<SUP>1</SUP>]</div><div class=\"def\">全能.</div>\r\n","<div class=\"hw\">omnis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\"><num>①</num> (<i>sg</i>)全体の</div><div class=\"ex\"><i>Gallia</i> ～ (<author>C<small>AES</small></author>)<span class=\"ext\">全ガリア.</span></div><div class=\"def\"><num>②</num> (<i>pl</i>)すべての, あらゆる.</div><div class=\"def\"><num>③</num> それぞれ[おのおの]の.</div><div class=\"def\"><num>④</num> 可能な限りすべての(種類の).</div>\r\n","<div class=\"hw\">omniscius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://omnis\">omnis</a>/scio]</div><div class=\"def\">全知の.</div>\r\n","<div class=\"hw\">omnituens</div><div class=\"pos\">-entis, <i>adj</i></div><div class=\"ori\">[omnis/tueor]</div><div class=\"def\">すべてを見る.</div>\r\n","<div class=\"hw\">omnivagus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[omnis/vagus<SUP>1</SUP>]</div><div class=\"def\">いたるところをさまよう.</div>\r\n","<div class=\"hw\">omnivolus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[omnis/volo<SUP>2</SUP>]</div><div class=\"def\">すべてをほしがる.</div>\r\n","<div class=\"hw\">omnivorus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[omnis/voro]</div><div class=\"def\">何でも食べる, 雑食性の.</div>\r\n","<div class=\"hw\">omnēs</div><div class=\"pos\">-ium, <i>m</i>, <i>f pl</i></div><div class=\"ori\">[omnis]</div><div class=\"def\">すべての人々.</div>\r\n","<div class=\"hw\">omnīnō</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[omnis]</div><div class=\"def\"><num>①</num> 全く, 完全に, すっかり.</div><div class=\"def\"><num>②</num> 全体[全部]で, 合計で.</div><div class=\"def\"><num>③</num> 全般的に, 概して.</div><div class=\"def\"><num>④</num> (否定辞と)</div><div class=\"ex\"><i>non</i> ～<span class=\"ext\">(通例)全く...というわけではない;(ときに)全く...ではない</span></div><div class=\"ex\">～ <i>non</i><span class=\"ext\">全く...ではない.</span></div><div class=\"def\"><num>⑤</num> (疑問文で)いったい.</div><div class=\"def\"><num>⑥</num> 要するに, 約言すれば.</div><div class=\"def\"><num>⑦</num> </div><div class=\"ex\">～...<i>sed</i><span class=\"ext\">確かに...だがしかし.</span></div>\r\n","<div class=\"hw\">omphalos</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘解〙臍<SUB>へそ</SUB>(=<a href=\"entry://umbilīcus\">umbilicus</a>).</div><div class=\"def\"><num>②</num> 中心.</div>\r\n","<div class=\"hw\">Omphalē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙オンパレー《Lydia の女王;Hercules が女装してその奴隷として仕えた》.</div>\r\n","<div class=\"hw\">Omāna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">オマーナ《Arabia の町》.</div>\r\n","<div class=\"hw\">omāsum, omassum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> 雄牛の第一胃[第二胃].</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘動〙重弁胃.</div>\r\n","<div class=\"hw\">omīsī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://omittō\">omitto</a>.</div>\r\n","<div class=\"hw\">onager, -grus</div><div class=\"pos\">-grī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘動〙野生のロバ.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 投石機.</div>\r\n","<div class=\"hw\">onanismus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\"><num>①</num> 自慰, オナニー.</div><div class=\"def\"><num>②</num> 中絶性交(=coitus interruptus).</div>\r\n","<div class=\"hw\">Onchēsmītēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Epirus の港 Onchesmus から吹く南東風.</div>\r\n","<div class=\"hw\">Onchēstius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Boeotia の町 Onchestus の.</div>\r\n","<div class=\"hw\">oncologia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘医〙腫瘍学.</div>\r\n","<div class=\"hw\">oncō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"ori\">[<i>cf. </i> unco]</div><div class=\"def\">(ロバが)鳴く.</div>\r\n","<div class=\"hw\">oneirodȳnia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙悪夢, 夢魔</div><div class=\"ex\"><i>～ activa</i><span class=\"ext\">夢遊症.</span></div>\r\n","<div class=\"hw\">oneirōgmus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘病〙遺精, 夢精.</div>\r\n","<div class=\"hw\">onerāria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://onerārius\">onerārius</a>]</div><div class=\"def\">(<i>sc. </i> navis)貨物船.</div>\r\n","<div class=\"hw\">onerārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[onus]</div><div class=\"def\">荷物[貨物]を運ぶ.</div>\r\n","<div class=\"hw\">onerātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://onerō\">onero</a>.</div>\r\n","<div class=\"hw\">onerō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[onus]</div><div class=\"def\"><num>①</num> (乗物・動物などに)荷物を載せる[積む] 〈alqd re〉.</div><div class=\"def\"><num>②</num> どっさり載せる, 積み上げる</div><div class=\"ex\"><i>epulis onerare mensas</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">食卓に料理を並べる.</span></div><div class=\"def\"><num>③</num> 負わせる, 重くする</div><div class=\"ex\"><i>alqm armis onerare</i> (<author>T<small>AC</small></author>)<span class=\"ext\">ある人を武装させる.</span></div><div class=\"def\"><num>④</num> 圧倒する.</div><div class=\"def\"><num>⑤</num> 詰め込む 〈alqd re〉</div><div class=\"ex\"><i>epulis onerari</i> (<author>O<small>V</small></author>)<span class=\"ext\">食べすぎる.</span></div><div class=\"def\"><num>⑥</num> あふれるほどに与える, 浴びせる 〈alqd re〉</div><div class=\"ex\"><i>onerare laetitiā senem</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">年寄りを大喜びさせる.</span></div><div class=\"def\"><num>⑦</num> 圧迫する, 悩ます.</div><div class=\"def\"><num>⑧</num> 悪化させる, 深刻化させる.</div>\r\n","<div class=\"hw\">onerōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[onus]</div><div class=\"def\"><num>①</num> 重い, 重すぎる.</div><div class=\"def\"><num>②</num> 負担となる, 煩わしい, 厄介な.</div>\r\n","<div class=\"hw\">oniscus, -os</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘動〙ヤスデ(=<a href=\"entry://mīlipeda\">millepeda</a>).</div>\r\n","<div class=\"hw\">onocentaurus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ロバと Centaurus の合体した怪物.</div>\r\n","<div class=\"hw\">onocrotalus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘鳥〙ペリカン(=<a href=\"entry://pelecānus\">pelecanus</a>).</div>\r\n","<div class=\"hw\">onomatopoeia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 造語.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘修〙擬声[音]語.</div>\r\n","<div class=\"hw\">ontogenesis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘生物〙個体発生.</div>\r\n","<div class=\"hw\">ontogeneticus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://ontogenesis\">ontogenesis</a>]</div><div class=\"def\">〘生物〙個体発生の.</div>\r\n","<div class=\"hw\">onus</div><div class=\"pos\">oneris, <i>n</i></div><div class=\"def\"><num>①</num> 重さ;重いもの.</div><div class=\"def\"><num>②</num> 荷, 荷物.</div><div class=\"def\"><num>③</num> 負担, 重荷;苦しみ</div><div class=\"ex\"><i>～ Babylonis</i> (<author>V<small>ULG</small></author>)<span class=\"ext\">Babylon に対するわざわいの預言.</span></div><div class=\"def\"><num>④</num> 義務, 責任.</div><div class=\"def\"><num>⑤</num> 税.</div>\r\n","<div class=\"hw\">onustus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[onus]</div><div class=\"def\"><num>①</num> (乗物・動物などが)荷を積んだ 〈re;alcis rei〉.</div><div class=\"def\"><num>②</num> (...で)いっぱいの.</div>\r\n","<div class=\"hw\">onustō</div><div class=\"pos\">-āre -āvī -ātum, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://onustus\">onustus</a>]</div><div class=\"def\">荷を負わせる.</div>\r\n","<div class=\"hw\">onyx</div><div class=\"pos\">onychis, <i>m</i>(<i>f</i>)</div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘鉱〙縞大理石.</div><div class=\"def\"><num>②</num> 縞大理石製の容器.</div><div class=\"def\"><num>③</num> 〘鉱〙石英の一種.</div><div class=\"def\"><num>④</num> 〘貝〙マテガイの一種.</div>\r\n","<div class=\"hw\">opalus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘鉱〙蛋白石, オパール.</div>\r\n","<div class=\"hw\">opella</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[↓<a href=\"entry://opera\">opera</a>]</div><div class=\"def\">(小さな)仕事[骨折り].</div>\r\n","<div class=\"hw\">opera</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[opus]</div><div class=\"def\"><num>①</num> 労力, 骨折り</div><div class=\"ex\"><i>operam dare</i> 〈+<i>dat</i>;ut, ne〉<span class=\"ext\">骨折る, 尽力する</span></div><div class=\"ex\"><i>est operae pretium</i> 〈+<i>inf</i>〉 (<author>C<small>IC</small></author>)<span class=\"ext\">骨折りがいがある</span></div><div class=\"ex\"><i>operā meā</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私のおかげで.</span></div><div class=\"def\"><num>②</num> 仕事, 任務.</div><div class=\"def\"><num>③</num> 行為, 行動.</div><div class=\"def\"><num>④</num> 製作物, 作品</div><div class=\"ex\"><i>operae araneorum</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">クモの巣.</span></div><div class=\"def\"><num>⑤</num> 尽力, 助力.</div><div class=\"def\"><num>⑥</num> (一人分の)一日の仕事.</div><div class=\"def\"><num>⑦</num> (日雇い)労働者;雇われごろつき</div><div class=\"ex\"><i>theatrales operae</i> (<author>T<small>AC</small></author>)<span class=\"ext\">(劇場の)雇われ喝采者たち.</span></div>\r\n","<div class=\"hw\">operculum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[operio]</div><div class=\"def\"><num>①</num> ふた, おおい.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘動〙(魚の)鰓蓋<SUB>えらぶた</SUB>;(貝類の殻口の)蓋<SUB>ふた</SUB>;(カブトガニの)蓋板<SUB>がいはん</SUB>.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘解〙弁蓋.</div>\r\n","<div class=\"hw\">operculāris</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙弁蓋の.</div>\r\n","<div class=\"hw\">operiō</div><div class=\"pos\">-īre -eruī -ertum, <i>tr</i></div><div class=\"ori\">[ob-/pario<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 閉める, 閉じる.</div><div class=\"def\"><num>②</num> おおう, ふたをする.</div><div class=\"def\"><num>③</num> 埋める.</div><div class=\"def\"><num>④</num> (衣服などを)まとわせる, 包む.</div><div class=\"def\"><num>⑤</num> 浴びせかける.</div><div class=\"def\"><num>⑥</num> 隠す, おおい隠す.</div>\r\n","<div class=\"hw\">operor</div><div class=\"pos\">-ārī -ātus sum, <i>intr</i>, <i>tr dep</i></div><div class=\"ori\">[opus]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>intr</i>)</div><div class=\"def\"><num>①</num> 従事する, 骨折る 〈alci rei〉.</div><div class=\"def\"><num>②</num> 供犠を行なう.</div><div class=\"def\"><num0>Ⅱ</num0> <SUP>◇</SUP>(<i>tr</i>)</div><div class=\"def\"><num>①</num> 行なう, 遂行する.</div><div class=\"def\"><num>②</num> もたらす, 生じさせる.</div>\r\n","<div class=\"hw\">opertiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[operio]</div><div class=\"def\">おおうこと.</div>\r\n","<div class=\"hw\">opertum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://opertus\">opertus<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> 秘密の[隠された]場所.</div><div class=\"def\"><num>②</num> 秘密.</div><div class=\"def\"><num>③</num> 謎めいた言葉.</div>\r\n","<div class=\"hw\">opertus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[operio]</div><div class=\"def\"><num>①</num> 見えなくされた, 隠された;おおわれた.</div><div class=\"def\"><num>②</num> 秘密の, 知られていない.</div><hr><div class=\"hw\">opertus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">おおう[包む]こと.</div>\r\n","<div class=\"hw\">opertē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[opertus<SUP>1</SUP>]</div><div class=\"def\">遠まわしに, 暗に.</div>\r\n","<div class=\"hw\">opertō</div><div class=\"pos\">-āre, <i>tr freq</i></div><div class=\"ori\">[operio]</div><div class=\"def\">(しばしば)おおう.</div>\r\n","<div class=\"hw\">opertōrium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[operio]</div><div class=\"def\"><num>①</num> おおい.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 衣服.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 墓.</div>\r\n","<div class=\"hw\">operula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[opera]</div><div class=\"def\"><num>①</num> <SUP>◇</SUP>(ちょっとした)尽力, 骨折り.</div><div class=\"def\"><num>②</num> (わずかな)稼ぎ.</div>\r\n","<div class=\"hw\">operuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://operiō\">operio</a>.</div>\r\n","<div class=\"hw\">operārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://opera\">opera</a>]</div><div class=\"def\"><num>①</num> 雇われて働く;労働者の.</div><div class=\"def\"><num>②</num> (家畜・道具が)農耕[作業]に用いられる.</div><hr><div class=\"hw\">operārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> (日雇い)労働者, 職人.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 施物<SUB>せもつ</SUB>分配係.</div>\r\n","<div class=\"hw\">operātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[opera]</div><div class=\"def\"><num>①</num> 仕事, 作業, 活動;(自然力の)はたらき, 作用.</div><div class=\"def\"><num>②</num> (<i>pl</i>)供犠<SUB>くぎ</SUB>.</div>\r\n","<div class=\"hw\">operātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[operor]</div><div class=\"def\">職人;創造者.</div>\r\n","<div class=\"hw\">operātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://operor\">operor</a>.</div>\r\n","<div class=\"hw\">operātōrius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[opera]</div><div class=\"def\">仕事をする, 作り出す.</div>\r\n","<div class=\"hw\">operīmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://operiō\">operiō</a>]</div><div class=\"def\">おおい, ふた.</div>\r\n","<div class=\"hw\">operōsitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://operōsus\">operōsus</a>]</div><div class=\"def\">過度に綿密な仕上げ.</div>\r\n","<div class=\"hw\">operōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[opera]</div><div class=\"def\"><num>①</num> 勤勉な, 労を惜しまない.</div><div class=\"def\"><num>②</num> (薬が)効能のある.</div><div class=\"def\"><num>③</num> 忙しい.</div><div class=\"def\"><num>④</num> 骨の折れる, 面倒な.</div><div class=\"def\"><num>⑤</num> 入念に仕上げられた, 凝った.</div>\r\n","<div class=\"hw\">operōsē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[operosus]</div><div class=\"def\">骨折って, 苦労して.</div>\r\n","<div class=\"hw\">Opheltēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙オペルテース《 (1) Nemea の王 Lycurgus の子;幼くして大蛇に殺された彼の追悼に Nemea 競技祭が始められた;別名 Archemorus.(2) Troja の戦士;Euryalus の父》.</div>\r\n","<div class=\"hw\">ophidismus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">〘病〙蛇毒症.</div>\r\n","<div class=\"hw\">Ophiūsa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オピウーサ《 (1) Cyprus 島の古名.(2) Rhodos 島の古名.(3) Pontus の町》.</div>\r\n","<div class=\"hw\">Ophiūsius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Ophiusa (1) の.</div>\r\n","<div class=\"hw\">ophthalmia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘病〙眼炎</div><div class=\"ex\"><i>～ Aegyptica</i><span class=\"ext\">エジプト眼炎</span></div><div class=\"ex\"><i>～ sympathica</i><span class=\"ext\">交感性眼炎.</span></div>\r\n","<div class=\"hw\">ophthalmicus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">眼の.</div><hr><div class=\"hw\">ophthalmicus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">眼科医.</div>\r\n","<div class=\"hw\">ophthalmiās</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘魚〙ヤツメウナギ(=<a href=\"entry://oculāta\">oculata</a>).</div>\r\n","<div class=\"hw\">ophthalmologia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘医〙眼科学.</div>\r\n","<div class=\"hw\">ophīdion</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘魚〙アナゴに似た魚.</div>\r\n","<div class=\"hw\">Ophīonidēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Centaurus 族の Ophion の息子(=<a href=\"entry://Amycus\">Amycus</a>).</div>\r\n","<div class=\"hw\">Opicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">(Oscus の別称)</div><div class=\"def\"><num>①</num> Osci 人の.</div><div class=\"def\"><num>②</num> 粗野な, 無学の.</div>\r\n","<div class=\"hw\">opifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[ops/fero]</div><div class=\"def\"><num>①</num> 救いをもたらす.</div><div class=\"def\"><num>②</num> (薬が)効能のある.</div>\r\n","<div class=\"hw\">opifex</div><div class=\"pos\">-ficis, <i>m</i>(<i>f</i>)</div><div class=\"ori\">[opus/facio]</div><div class=\"def\"><num>①</num> 製作者, 製造者.</div><div class=\"def\"><num>②</num> 職人, 細工人.</div>\r\n","<div class=\"hw\">opificium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[opifex;<i>cf. </i> officium]</div><div class=\"def\">働くこと, 活動.</div>\r\n","<div class=\"hw\">opificīna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://officīna\">officina</a>.</div>\r\n","<div class=\"hw\">opiparus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ops/paro<SUP>2</SUP>]</div><div class=\"def\">豪華な, ぜいたくな.</div>\r\n","<div class=\"hw\">opiparē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://opiparus\">opiparus</a>]</div><div class=\"def\">豪華に, ぜいたくに.</div>\r\n","<div class=\"hw\">opisthographus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">裏面にも記された, 両面に書かれた.</div>\r\n","<div class=\"hw\">Opitergium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">オピテルギウム《Venetia の町;現 Oderzo》.</div>\r\n","<div class=\"hw\">Opitergīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Opitergium の.</div>\r\n","<div class=\"hw\">opitulor</div><div class=\"pos\">-ārī -ātus sum, <i>intr dep</i></div><div class=\"ori\">[ops/tuli(⇒ <a href=\"entry://ferō\">fero</a>)]</div><div class=\"def\"><num>①</num> 助ける, 援助する 〈alci〉.</div><div class=\"def\"><num>②</num> 和らげる 〈alci rei〉.</div><div class=\"def\"><num>③</num> 役立つ, 有効である.</div>\r\n","<div class=\"hw\">opitulātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[opitulor]</div><div class=\"def\">助力, 援助.</div>\r\n","<div class=\"hw\">opitulātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://opitulor\">opitulor</a>]</div><div class=\"def\">助力[援助]者.</div>\r\n","<div class=\"hw\">opium, -on</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">アヘン(阿片).</div>\r\n","<div class=\"hw\">opobalsamum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">バルサム樹の樹液.</div>\r\n","<div class=\"hw\">opobalsamētum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↓<a href=\"entry://opobalsamum\">opobalsamum</a>]</div><div class=\"def\">バルサム樹が植えてある場所.</div>\r\n","<div class=\"hw\">oportet</div><div class=\"pos\">-ēre -tuit, <i>intr impers</i></div><div class=\"def\"><num>①</num> ...するのが当然である, ...すべきである 〈+<i>inf</i>;+<i>acc c.inf</i>;+<i>subj</i>〉.</div><div class=\"def\"><num>②</num> 必ず起こる, 避けられない.</div><div class=\"def\"><num>③</num> ...に相違ない, ...のはずである.</div><div class=\"def\"><num>④</num> (<i>pers</i>)(...するように)要求する.</div>\r\n","<div class=\"hw\">oportuit</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://oportet\">oportet</a>.</div>\r\n","<div class=\"hw\">oppactus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://oppangō\">oppango</a>.</div>\r\n","<div class=\"hw\">oppandō</div><div class=\"pos\">-ere -pandī -pansum [-passum], <i>tr</i></div><div class=\"ori\">[ob-/pando<SUP>2</SUP>]</div><div class=\"def\">(...に向かって)広げる.</div>\r\n","<div class=\"hw\">oppangō</div><div class=\"pos\">-ere -pēgī -pactum, <i>tr</i></div><div class=\"ori\">[ob-/pango]</div><div class=\"def\">(上に)くっつける</div><div class=\"ex\"><i>suavium oppangere</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">キスする.</span></div>\r\n","<div class=\"hw\">oppectō</div><div class=\"pos\">-ere, <i>tr</i></div><div class=\"ori\">[ob-/pecto]</div><div class=\"def\">櫛をあてがう;むしり取る, 食う.</div>\r\n","<div class=\"hw\">opperior</div><div class=\"pos\">-perīrī -pertus [-perītus] sum, <i>intr</i>, <i>tr dep</i></div><div class=\"ori\">[<i>cf. </i> experior]</div><div class=\"def\">待つ, 待ちうける.</div>\r\n","<div class=\"hw\">oppertus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://opperior\">opperior</a>.</div>\r\n","<div class=\"hw\">oppetītus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://oppetō\">oppeto</a>.</div>\r\n","<div class=\"hw\">oppetīvī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://oppetō\">oppeto</a>.</div>\r\n","<div class=\"hw\">oppetō</div><div class=\"pos\">-ere -petīvī -petītum, <i>tr</i></div><div class=\"ori\">[ob-/peto]</div><div class=\"def\"><num>①</num> でくわす, 遭遇する 〈alqd〉.</div><div class=\"def\"><num>②</num> (<i>sc. </i> mortem)死ぬ 〈<i>abs</i>〉.</div>\r\n","<div class=\"hw\">oppidulum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[↓<a href=\"entry://oppidum\">oppidum</a>]</div><div class=\"def\">(小さな)町.</div>\r\n","<div class=\"hw\">oppidum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> (特に, ローマ市(urbs)以外の)町.</div><div class=\"def\"><num>②</num> 町の住民.</div><div class=\"def\"><num>③</num> (Britannia 人の)要塞化された森.</div>\r\n","<div class=\"hw\">oppidāneus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[oppidum]</div><div class=\"def\">町の.</div>\r\n","<div class=\"hw\">oppidānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[oppidum]</div><div class=\"def\"><num>①</num> (ローマ市以外の)町の, 地方都市の, 田舎町の.</div><div class=\"def\"><num>②</num> (特定の)町の.</div>\r\n","<div class=\"hw\">oppidānī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[↓<a href=\"entry://oppidānus\">oppidānus</a>]</div><div class=\"def\">町の住民.</div>\r\n","<div class=\"hw\">oppidātim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[oppidum]</div><div class=\"def\">町ごとに.</div>\r\n","<div class=\"hw\">oppidō</div><div class=\"pos\"><i>adv</i></div><div class=\"def\"><num>①</num> きわめて, 全く, すっかり</div><div class=\"ex\">～ <i>quam</i> (<author>L<small>IV</small></author>)<span class=\"ext\">きわめて, 全く.</span></div><div class=\"def\"><num>②</num> (返答として)もちろん.</div>\r\n","<div class=\"hw\">oppignerō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[ob-/pignero]</div><div class=\"def\">質[抵当]に入れる.</div>\r\n","<div class=\"hw\">Oppius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">オッピウス《ローマ人の氏族名;特に <i>C</i>. ～, 伝記作家で Caesar の友人》.</div>\r\n","<div class=\"hw\">oppleō</div><div class=\"pos\">-ēre -plēvī -plētum, <i>tr</i></div><div class=\"ori\">[ob-/pleo]</div><div class=\"def\"><num>①</num> 満たす, いっぱいにする 〈alqd re〉.</div><div class=\"def\"><num>②</num> 全面をおおい尽くす, 一面に広がる.</div>\r\n","<div class=\"hw\">opplētus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://oppleō\">oppleo</a>.</div>\r\n","<div class=\"hw\">opplēvī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://oppleō\">oppleo</a>.</div>\r\n","<div class=\"hw\">opplōrō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"ori\">[ob-/ploro]</div><div class=\"def\">(...に向かって)泣き叫ぶ 〈+<i>dat</i>〉.</div>\r\n","<div class=\"hw\">opportūna</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[opportunus]</div><div class=\"def\">(戦略的に)好都合なこと.</div>\r\n","<div class=\"hw\">opportūnitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://opportūnus\">opportūnus</a>]</div><div class=\"def\"><num>①</num> 好都合, 便宜.</div><div class=\"def\"><num>②</num> 時宜を得ていること.</div><div class=\"def\"><num>③</num> 機会, 好機.</div>\r\n","<div class=\"hw\">opportūnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ob-/portus]</div><div class=\"def\"><num>①</num> 便利な, 好都合な.</div><div class=\"def\"><num>②</num> 時宜を得た, 折よい.</div><div class=\"def\"><num>③</num> 役に立つ, 有用な 〈alci rei;ad alqd〉.</div><div class=\"def\"><num>④</num> (危険などに)さらされた, (攻撃を)受けやすい.</div>\r\n","<div class=\"hw\">opportūnē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[opportunus]</div><div class=\"def\">適時に, 都合よく.</div>\r\n","<div class=\"hw\">opposita</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[oppositus<SUP>1</SUP>]</div><div class=\"def\">対立する命題.</div>\r\n","<div class=\"hw\">oppositiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[oppono]</div><div class=\"def\"><num>①</num> 反駁.</div><div class=\"def\"><num>②</num> 〘修〙対照(法).</div>\r\n","<div class=\"hw\">oppositor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[oppono]</div><div class=\"def\">反対者.</div>\r\n","<div class=\"hw\">oppositus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://oppōnō\">oppono</a>.</div><hr><div class=\"hw\">oppositus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 対置, 介在.</div><div class=\"def\"><num>②</num> 反駁.</div>\r\n","<div class=\"hw\">opposuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://oppōnō\">oppono</a>.</div>\r\n","<div class=\"hw\">oppressiuncula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[↑<a href=\"entry://oppressiō\">oppressiō</a>]</div><div class=\"def\">(そっと)もむこと.</div>\r\n","<div class=\"hw\">oppressiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[opprimo]</div><div class=\"def\"><num>①</num> 押しつけること.</div><div class=\"def\"><num>②</num> 力づくで抑えこむ[つかまえる]こと.</div>\r\n","<div class=\"hw\">oppressor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[opprimo]</div><div class=\"def\">破壊者.</div>\r\n","<div class=\"hw\">oppressus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://opprimō\">opprimo</a>.</div><hr><div class=\"hw\">oppressus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">圧迫.</div>\r\n","<div class=\"hw\">oppressī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://opprimō\">opprimo</a>.</div>\r\n","<div class=\"hw\">opprimō</div><div class=\"pos\">-ere -pressī -pressum, <i>tr</i></div><div class=\"ori\">[ob-/premo]</div><div class=\"def\"><num>①</num> 圧迫する, 圧搾する.</div><div class=\"def\"><num>②</num> (口・目を)閉じる.</div><div class=\"def\"><num>③</num> 窒息させる.</div><div class=\"def\"><num>④</num> (火・音を)おおい消す;おおう, おおい隠す.</div><div class=\"def\"><num>⑤</num> 埋める, 沈める.</div><div class=\"def\"><num>⑥</num> 打ちのめす, 圧倒する</div><div class=\"ex\"><i>oppressus somno</i> (<author>C<small>AES</small></author>)<span class=\"ext\">眠りこけている.</span></div><div class=\"def\"><num>⑦</num> 制圧する, 征服する.</div><div class=\"def\"><num>⑧</num> (行動・状態・感情などを)やめさせる, 抑える, 鎮める.</div><div class=\"def\"><num>⑨</num> 不意を襲う, 急襲する.</div><div class=\"def\"><num>⑩</num> (できごと・状況が)突然やって来る[起こる].</div>\r\n","<div class=\"hw\">opprobrium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://opprobrō\">opprobrō</a>]</div><div class=\"def\"><num>①</num> 非難, 侮辱.</div><div class=\"def\"><num>②</num> 恥辱, 不面目.</div>\r\n","<div class=\"hw\">opprobrāmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[opprobro]</div><div class=\"def\">恥辱, 不面目.</div>\r\n","<div class=\"hw\">opprobrātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[opprobro]</div><div class=\"def\">非難.</div>\r\n","<div class=\"hw\">opprobrō</div><div class=\"pos\">-āre -ātum, <i>tr</i></div><div class=\"ori\">[ob-/probrum]</div><div class=\"def\">非難する.</div>\r\n","<div class=\"hw\">oppugnātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[oppugno]</div><div class=\"def\"><num>①</num> 攻囲, 襲撃, 攻撃.</div><div class=\"def\"><num>②</num> 非難, 弾劾.</div>\r\n","<div class=\"hw\">oppugnātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[oppugno]</div><div class=\"def\">襲撃者, 攻撃者.</div>\r\n","<div class=\"hw\">oppugnātōrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://oppugnātor\">oppugnātor</a>]</div><div class=\"def\">攻囲[襲撃]の.</div>\r\n","<div class=\"hw\">oppugnō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"def\"><num>①</num> 攻囲する, 襲撃[攻撃]する.</div><div class=\"def\"><num>②</num> 反対する, 非難する.</div>\r\n","<div class=\"hw\">oppēdō</div><div class=\"pos\">-ere, <i>intr</i></div><div class=\"ori\">[ob-/pedo<SUP>2</SUP>]</div><div class=\"def\">(人に向かって)放屁する;侮辱する 〈alci〉.</div>\r\n","<div class=\"hw\">oppēgī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://oppangō\">oppango</a>.</div>\r\n","<div class=\"hw\">oppīlō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[ob-/pilo<SUP>1</SUP>]</div><div class=\"def\">ふさぐ, せきとめる.</div>\r\n","<div class=\"hw\">oppōnens</div><div class=\"pos\">-entis, <SUP>◇</SUP><i>m</i>(<i>prp</i>)</div><div class=\"ori\">[↓<a href=\"entry://oppōnō\">oppōnō</a>]</div><div class=\"def\">〘解〙対立筋.</div>\r\n","<div class=\"hw\">oppōnō</div><div class=\"pos\">-ere -posuī -positum, <i>tr</i></div><div class=\"ori\">[ob-/pono]</div><div class=\"def\"><num>①</num> 前[向かい側]に置く, 向かい合わせる 〈alqd alci rei;alqd ad alqd〉.</div><div class=\"def\"><num>②</num> 差し出す.</div><div class=\"def\"><num>③</num> (危険などに)さらす, 遭遇させる.</div><div class=\"def\"><num>④</num> 障害物[遮蔽物]として前に置く.</div><div class=\"def\"><num>⑤</num> (部隊などを敵に)対抗[対峙]させる.</div><div class=\"def\"><num>⑥</num> 反対[対立]させる.</div><div class=\"def\"><num>⑦</num> 反論する, 異議を唱える;申し立てる.</div><div class=\"def\"><num>⑧</num> 対比させる.</div><div class=\"def\"><num>⑨</num> 質[抵当]に入れる.</div>\r\n","<div class=\"hw\">ops</div><div class=\"pos\">opis, <i>f</i></div><div class=\"ori\">[<i>cf. </i> opus]</div><div class=\"def\"><num>①</num> 力, 能力</div><div class=\"ex\"><i>summā ope</i> (<author>S<small>ALL</small></author>)<span class=\"ext\">全力をあげて.</span></div><div class=\"def\"><num>②</num> (<i>pl</i>)権力, 勢力.</div><div class=\"def\"><num>③</num> 助け, 助力;助力者</div><div class=\"ex\"><i>opem afferre</i> (<author>O<small>V</small></author>)<span class=\"ext\">助力する.</span></div><div class=\"def\"><num>④</num> (<i>pl</i>)資力, 財産;兵力, 軍勢.</div><div class=\"def\"><num>⑤</num> 手段, 方策.</div>\r\n","<div class=\"hw\">Ops</div><div class=\"pos\">Opis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://ops\">ops</a>]</div><div class=\"def\">〘神話〙オプス《豊穣の女神;Saturnus の妻;ギリシア神話の Rhea と同一視された》.</div>\r\n","<div class=\"hw\">ops-</div><div class=\"def\">⇒obs-.</div>\r\n","<div class=\"hw\">optimus</div><div class=\"pos\"><i>adj superl</i></div><div class=\"ori\">[bonus<SUP>1</SUP>]</div><div class=\"def\">最もよい[すぐれた], 最高の.</div>\r\n","<div class=\"hw\">optimās</div><div class=\"pos\">-ātis, <i>adj</i></div><div class=\"ori\">[optimus]</div><div class=\"def\">貴族の.</div>\r\n","<div class=\"hw\">optimātēs</div><div class=\"pos\">-ium [-um], <i>m pl</i></div><div class=\"ori\">[↑<a href=\"entry://optimās\">optimās</a>]</div><div class=\"def\">貴族;貴族党, 閥族派.</div>\r\n","<div class=\"hw\">optimē</div><div class=\"pos\"><i>adv superl</i></div><div class=\"ori\">[↓<a href=\"entry://optimus\">optimus</a>]</div><div class=\"def\">(原級 bene)最もよく[申し分なく].</div>\r\n","<div class=\"hw\">optiō<SUP>1</SUP></div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[opto]</div><div class=\"def\">選択(権).</div><hr><div class=\"hw\">optiō<SUP>2</SUP></div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[opto]</div><div class=\"def\"><num>①</num> 兵長.</div><div class=\"def\"><num>②</num> 助手, 補佐.</div>\r\n","<div class=\"hw\">optābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[opto]</div><div class=\"def\"><num>①</num> 望ましい, 願わしい.</div><div class=\"def\"><num>②</num> 切望[熱望]された.</div>\r\n","<div class=\"hw\">optābiliter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://optābilis\">optābilis</a>]</div><div class=\"def\">望ましく.</div>\r\n","<div class=\"hw\">optātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[opto]</div><div class=\"def\"><num>①</num> 願望, 願い.</div><div class=\"def\"><num>②</num> 願望を表わすこと.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 選択権.</div>\r\n","<div class=\"hw\">optātum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://optātus\">optātus</a>]</div><div class=\"def\">願望, 願い.</div>\r\n","<div class=\"hw\">optātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[opto]</div><div class=\"def\">願わしい, 望ましい.</div>\r\n","<div class=\"hw\">optātīvus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[opto]</div><div class=\"def\">〘文〙願望を表わす</div><div class=\"ex\"><i>modus ～</i> (<author>D<small>IOM</small></author>)<span class=\"ext\">希求法.</span></div>\r\n","<div class=\"hw\">optātō</div><div class=\"pos\"><i>adv</i>(<i>abl</i>)</div><div class=\"ori\">[↓<a href=\"entry://optātum\">optātum</a>]</div><div class=\"def\">望んだとおりに.</div>\r\n","<div class=\"hw\">optīvus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://optō\">optō</a>]</div><div class=\"def\">選ばれた.</div>\r\n","<div class=\"hw\">optō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"def\"><num>①</num> 選ぶ, 選択する.</div><div class=\"def\"><num>②</num> 願う, 望む 〈alqd;ut;+<i>inf</i>;+<i>acc c. inf</i>〉.</div>\r\n","<div class=\"hw\">opulens</div><div class=\"pos\">-entis, <i>adj</i></div><div class=\"def\">=<a href=\"entry://opulentus\">opulentus</a>.</div>\r\n","<div class=\"hw\">opulentia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[opulentus]</div><div class=\"def\"><num>①</num> 豪華, みごとさ.</div><div class=\"def\"><num>②</num> 勢力.</div><div class=\"def\"><num>③</num> 豊かさ, 富.</div>\r\n","<div class=\"hw\">opulentitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[opulentus]</div><div class=\"def\">富裕, 裕福.</div>\r\n","<div class=\"hw\">opulentus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ops]</div><div class=\"def\"><num>①</num> 富裕な, 裕福な.</div><div class=\"def\"><num>②</num> (...に)富んだ, 豊富な 〈re;alcis rei〉.</div><div class=\"def\"><num>③</num> 豪華な.</div><div class=\"def\"><num>④</num> 強力な, 勢力のある.</div><div class=\"def\"><num>⑤</num> 富をもたらす.</div>\r\n","<div class=\"hw\">opulentē, opulenter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[opulentus]</div><div class=\"def\">豪華に, 豪勢に.</div>\r\n","<div class=\"hw\">opulentō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://opulentus\">opulentus</a>]</div><div class=\"def\"><num>①</num> 富ませる, 豊かにする.</div><div class=\"def\"><num>②</num> 豪華にする.</div>\r\n","<div class=\"hw\">opulescō</div><div class=\"pos\">-ere, <i>intr</i></div><div class=\"ori\">[ops]</div><div class=\"def\">富裕[裕福]になる.</div>\r\n","<div class=\"hw\">Opuntius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Opus の.</div><div class=\"hw2\"><b>Opuntiī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Opus の住民.</div>\r\n","<div class=\"hw\">opus</div><div class=\"pos\">-eris, <i>n</i></div><div class=\"ori\">[<i>cf. </i> ops]</div><div class=\"def\"><num>①</num> 仕事, 務め.</div><div class=\"def\"><num>②</num> 業務, 職業.</div><div class=\"def\"><num>③</num> 活動, 作業.</div><div class=\"def\"><num>④</num> 努力, 骨折り.</div><div class=\"def\"><num>⑤</num> 細工, 作り.</div><div class=\"def\"><num>⑥</num> 業績, 功績.</div><div class=\"def\"><num>⑦</num> 製作物, 作品.</div><div class=\"def\"><num>⑧</num> 建造物, 構築物;保塁.</div><div class=\"def\"><num>⑨</num> ～ <i>est</i> 必要である 〈alci re;+<i>inf</i>;+<i>acc c. inf</i>〉</div><div class=\"ex\">～ <i>est auctoritate tua</i> (<author>C<small>IC</small></author>)<span class=\"ext\">きみの影響力が必要だ</span></div><div class=\"ex\"><i>Quid ～ est tam valde affirmare?</i> (<author>C<small>IC</small></author>)<span class=\"ext\">なぜそんなに強く主張する必要があろうか.</span></div>\r\n","<div class=\"hw\">opusculum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[opus]</div><div class=\"def\">(小さな)仕事[作品].</div>\r\n","<div class=\"hw\">opācitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[opacus]</div><div class=\"def\">陰(になること), 暗がり.</div>\r\n","<div class=\"hw\">opācus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> 陰の, 陰になった.</div><div class=\"def\"><num>②</num> 人目につかない, 引きこもった.</div><div class=\"def\"><num>③</num> 陰をつくる, 暗くする.</div><div class=\"def\"><num>④</num> 暗い, うす暗い.</div>\r\n","<div class=\"hw\">opācō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://opācus\">opācus</a>]</div><div class=\"def\">陰にする, 暗くする.</div>\r\n","<div class=\"hw\">opīmitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[opimus]</div><div class=\"def\">繁栄, 幸福.</div>\r\n","<div class=\"hw\">Opīmius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">オピーミウス《ローマ人の氏族名;特に <i>L. ～</i>, 執政官(前121);C. Gracchus に反対した optimates の指導者》.</div>\r\n","<div class=\"hw\">opīmus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ops]</div><div class=\"def\"><num>①</num> 太った.</div><div class=\"def\"><num>②</num> (土地が)肥えた, 肥沃な.</div><div class=\"def\"><num>③</num> 豊かな, 豊富な;利益をもたらす.</div><div class=\"def\"><num>④</num> (文体が)豊かな.</div>\r\n","<div class=\"hw\">opīmē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[opimus]</div><div class=\"def\">豪華に, ぜいたくに.</div>\r\n","<div class=\"hw\">opīmō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://opīmus\">opīmus</a>]</div><div class=\"def\"><num>①</num> 太らせる, 肥育する.</div><div class=\"def\"><num>②</num> (土地を)肥やす, 肥沃にする.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 豊かにする.</div>\r\n","<div class=\"hw\">opīniō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[opinor]</div><div class=\"def\"><num>①</num> 意見, 見解, 所信</div><div class=\"ex\"><i>ut</i> ～ <i>mea fert</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私の見解では.</span></div><div class=\"def\"><num>②</num> 予測, 予想</div><div class=\"ex\"><i>praeter opinionem</i> (<author>C<small>IC</small></author>)<span class=\"ext\">予想に反して</span></div><div class=\"ex\"><i>celerius opinione</i> (<author>C<small>AES</small></author>)<span class=\"ext\">予想より早く.</span></div><div class=\"def\"><num>③</num> 想像, 推測;心象, 観念.</div><div class=\"def\"><num>④</num> 評価, 評判;悪評;うわさ.</div>\r\n","<div class=\"hw\">opīniōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://opīniō\">opīniō</a>]</div><div class=\"def\">推測に富んだ.</div>\r\n","<div class=\"hw\">opīnor</div><div class=\"pos\">-ārī -ātus sum, <i>tr</i>, <i>intr dep</i></div><div class=\"def\"><num0>Ⅰ</num0> (<i>tr</i>)</div><div class=\"def\"><num>①</num> 思う, 考える 〈alqd;+<i>acc c.inf</i>〉.</div><div class=\"def\"><num>②</num> 想像する, 予想する.</div><div class=\"def\"><num>③</num> 意見を述べる[もつ].</div><div class=\"def\"><num0>Ⅱ</num0> (<i>intr</i>)(人をよく・悪く)評価する 〈de alqo〉.</div>\r\n","<div class=\"hw\">opīnābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[opinor]</div><div class=\"def\">推測に基づく, 想像(上)の.</div>\r\n","<div class=\"hw\">opīnātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[opinor]</div><div class=\"def\"><num>①</num> 想像, 推測.</div><div class=\"def\"><num>②</num> 見解, 意見, 所信.</div>\r\n","<div class=\"hw\">opīnātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[opinor]</div><div class=\"def\"><num>①</num> 推測でものを言う人.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>(帝政期の属州における軍隊の)食糧調達官.</div>\r\n","<div class=\"hw\">opīnātus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[opinor]</div><div class=\"def\"><num>①</num> 想像[推測]された, 仮定の.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 名高い.</div><hr><div class=\"hw\">opīnātus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">推測, 想像.</div>\r\n","<div class=\"hw\">Opūs</div><div class=\"pos\">-untis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オプース《Locris の町》.</div>\r\n","<div class=\"hw\">orbiculus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[orbis]</div><div class=\"def\"><num>①</num> (小さな)円形のもの《輪, 円盤, 滑車など》.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘解〙輪</div><div class=\"ex\"><i>～ ciliaris</i><span class=\"ext\">毛様体輪.</span></div>\r\n","<div class=\"hw\">orbiculāris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[orbiculus]</div><div class=\"def\"><num>①</num> 円形の, 環状の.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘解〙輪状の.</div>\r\n","<div class=\"hw\">orbiculātim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://orbiculātus\">orbiculātus</a>]</div><div class=\"def\">輪をなして, 環状に.</div>\r\n","<div class=\"hw\">orbiculātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://orbiculus\">orbiculus</a>]</div><div class=\"def\">円形の, 環状の.</div>\r\n","<div class=\"hw\">orbificō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"ori\">[orbus/facio]</div><div class=\"def\">(親から)子を奪う.</div>\r\n","<div class=\"hw\">Orbilius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">オルビリウス《ローマ人の氏族名;特に <i>L</i>. ～ <i>Pupillus</i>, 前1世紀の文法学者;Horatius の師》.</div>\r\n","<div class=\"hw\">orbis</div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\"><num>①</num> 円形のもの《円盤, 楯, 盆, 皿, 鏡, 円テーブル, 臼石など》.</div><div class=\"def\"><num>②</num> 車輪.</div><div class=\"def\"><num>③</num> 円.</div><div class=\"def\"><num>④</num> 球, 球体</div><div class=\"ex\">～ <i>caeli</i> (<author>L<small>UCR</small></author>)<span class=\"ext\">天球</span></div><div class=\"ex\">～ <i>luminis</i> [<i>oculi</i>] (<author>L<small>UCR</small></author>)<span class=\"ext\">眼球.</span></div><div class=\"def\"><num>⑤</num> 輪.</div><div class=\"def\"><num>⑥</num> 〘軍〙円陣.</div><div class=\"def\"><num>⑦</num> </div><div class=\"ex\">～ <i>terrarum [terrae]</i> (<author>C<small>IC</small></author>)<span class=\"ext\">全世界.</span></div><div class=\"def\"><num>⑧</num> 地域, 地帯.</div><div class=\"def\"><num>⑨</num> 回転, 旋回.</div><div class=\"def\"><num>⑩</num> 軌道.</div><div class=\"def\"><num>⑪</num> 〘修〙掉尾<SUB>とうび</SUB>文.</div><div class=\"def\"><num>⑫</num> 循環, ひと巡り.</div>\r\n","<div class=\"hw\">orbita</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://orbis\">orbis</a>]</div><div class=\"def\"><num>①</num> 車の跡, わだち.</div><div class=\"def\"><num>②</num> すき跡, あぜ溝.</div><div class=\"def\"><num>③</num> (天体の)軌道.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>〘解〙眼窩.</div>\r\n","<div class=\"hw\">orbitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[orbus]</div><div class=\"def\"><num>①</num> (家族・近親に)先立たれること;孤児であること, 子を失うこと.</div><div class=\"def\"><num>②</num> 子供のないこと.</div><div class=\"def\"><num>③</num> 失うこと, 奪われること.</div>\r\n","<div class=\"hw\">orbitōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[orbita]</div><div class=\"def\">わだちの多い.</div>\r\n","<div class=\"hw\">orbus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> (家族・近親を)失った, 先立たれた.</div><div class=\"def\"><num>②</num> 親のない, 孤児になった.</div><div class=\"def\"><num>③</num> 子供のない.</div><div class=\"def\"><num>④</num> (...を)奪われた, (...が)ない 〈(a)re;+<i>gen</i>〉.</div>\r\n","<div class=\"hw\">orbātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[orbo]</div><div class=\"def\">剥奪, 奪うこと.</div>\r\n","<div class=\"hw\">orbātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[orbo]</div><div class=\"def\">(他人からその子[親]を)奪う者.</div>\r\n","<div class=\"hw\">orbātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://orbō\">orbo</a>.</div>\r\n","<div class=\"hw\">orbō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[orbus]</div><div class=\"def\"><num>①</num> (家族・近親を)死によって奪う;子を失わせる 〈alqm alqo〉</div><div class=\"ex\"><i>orbatus filio</i> (<author>C<small>IC</small></author>)<span class=\"ext\">息子をなくした.</span></div><div class=\"def\"><num>②</num> 奪う, 取り上げる 〈alqm re〉.</div>\r\n","<div class=\"hw\">Orbōna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://orbus\">orbus</a>]</div><div class=\"def\">オルボーナ《子供をなくした親の守護女神》.</div>\r\n","<div class=\"hw\">orca</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘動〙ハナゴンドウ.</div><div class=\"def\"><num>②</num> 大壺.</div>\r\n","<div class=\"hw\">Orcades</div><div class=\"pos\">-um, <i>f pl</i></div><div class=\"def\">オルカデス《Scotia 北方の諸島;現 Orkney Islands》.</div>\r\n","<div class=\"hw\">Orchamus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙オルカムス, <SUP>*</SUP>-モス《Babylonia の王;絶世の美女 Leucothoe の父》.</div>\r\n","<div class=\"hw\">orchas</div><div class=\"pos\">-adis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙オリーブの一種(=<a href=\"entry://orchītēs\">orchites</a>).</div>\r\n","<div class=\"hw\">orchestra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> (ギリシアの劇場の)舞台前の半円形の合唱隊が歌舞する場所.</div><div class=\"def\"><num>②</num> (ローマの劇場の)元老院議員・高官用の貴賓席.</div><div class=\"def\"><num>③</num> 《詩》元老院.</div>\r\n","<div class=\"hw\">orchidotomia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘医〙精巣[睾丸]摘除(術).</div>\r\n","<div class=\"hw\">orchis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘植〙オリーブの一種.</div><div class=\"def\"><num>②</num> 〘植〙ラン.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘解〙精巣, 睾丸.</div>\r\n","<div class=\"hw\">Orchomenius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Orchomenus の.</div>\r\n","<div class=\"hw\">Orchomenus, -os</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オルコメヌス, <SUP>*</SUP>-ノス《 (1) Boeotia の町.(2) Arcadia の町.(3) Thessalia の町》.</div>\r\n","<div class=\"hw\">orchītis<SUP>2</SUP></div><div class=\"pos\">-tidis, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘医〙睾丸[精巣]炎.</div>\r\n","<div class=\"hw\">orchītēs, -a</div><div class=\"pos\">-ae, <i>m</i>, <B>-tis<SUP>1</SUP></B> -is, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙オリーブの一種(=<a href=\"entry://orchis\">orchis</a>).</div>\r\n","<div class=\"hw\">Orcus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">〘神話〙</div><div class=\"def\"><num>①</num> オルクス《冥府の神;ギリシア神話の Pluto に当たる》.</div><div class=\"def\"><num>②</num> 冥府, よみの国.</div><div class=\"def\"><num>③</num> 死.</div>\r\n","<div class=\"hw\">orcīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://Orcus\">Orcus</a>]</div><div class=\"def\">遺言によって定められた.</div>\r\n","<div class=\"hw\">ordeum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://hordeum\">hordeum</a>.</div>\r\n","<div class=\"hw\">ordia prīma</div><div class=\"def\">=primordia(⇒ <a href=\"entry://prīmordium\">primordium</a>).</div>\r\n","<div class=\"hw\">ordinārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ordo]</div><div class=\"def\"><num>①</num> 通常の, 普通の, 正規の.</div><div class=\"def\"><num>②</num> 整然とした, 秩序正しい.</div><hr><div class=\"hw\">ordinārius<SUP>2</SUP></div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">〘教会〙裁治権者.</div>\r\n","<div class=\"hw\">ordinātim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[ordinatus]</div><div class=\"def\">秩序[規則]正しく, 整然と.</div>\r\n","<div class=\"hw\">ordinātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[ordino]</div><div class=\"def\"><num>①</num> 配列, 配置.</div><div class=\"def\"><num>②</num> 秩序づけ, 整理.</div><div class=\"def\"><num>③</num> 任命, 指名.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>〘キ教〙(聖職者の)任職(式).</div>\r\n","<div class=\"hw\">ordinātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[ordino]</div><div class=\"def\"><num>①</num> 規制[支配]者.</div><div class=\"def\"><num>②</num> 訴訟を起こす人, 提訴者.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘キ教〙聖職授任者, 叙階者.</div>\r\n","<div class=\"hw\">ordinātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[↓<a href=\"entry://ordinō\">ordinō</a>]</div><div class=\"def\"><num>①</num> 秩序立った, 整然とした.</div><div class=\"def\"><num>②</num> 平行した.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘キ教〙聖職位を授けられた, 叙階された.</div>\r\n","<div class=\"hw\">ordinātē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[ordinatus]</div><div class=\"def\">整然と, 秩序正しく.</div>\r\n","<div class=\"hw\">ordinō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[ordo]</div><div class=\"def\"><num>①</num> 配列[配置]する.</div><div class=\"def\"><num>②</num> 秩序[組織]立てる, 整える.</div><div class=\"def\"><num>③</num> 支配[統治]する.</div><div class=\"def\"><num>④</num> 管理[監督]する.</div><div class=\"def\"><num>⑤</num> 規定する;任命[指名]する.</div><div class=\"def\"><num>⑥</num> (文書を)作成する.</div><div class=\"def\"><num>⑦</num> 訴訟を起こす, 提訴する.</div><div class=\"def\"><num>⑧</num> <SUP>◇</SUP>〘キ教〙聖職位を授ける, 叙階する.</div>\r\n","<div class=\"hw\">ordior</div><div class=\"pos\">-īrī orsus sum, <i>tr</i>, <i>intr dep</i></div><div class=\"ori\">[<i>cf</i>. ordo]</div><div class=\"def\"><num>①</num> 縦糸を張る.</div><div class=\"def\"><num>②</num> 始める, 開始する, 着手する.</div>\r\n","<div class=\"hw\">Ordovicēs</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"def\">オルドウィケース《Britannia(の現 Wales 中・北部)にいた一部族》.</div>\r\n","<div class=\"hw\">ordō</div><div class=\"pos\">-dinis, <i>m</i></div><div class=\"def\"><num>①</num> 列, 並び.</div><div class=\"def\"><num>②</num> (劇場の)座席列.</div><div class=\"def\"><num>③</num> 戦列, 隊列.</div><div class=\"def\"><num>④</num> 百人隊</div><div class=\"ex\"><i>ordinem ducere</i> (<author>C<small>AES</small></author>)<span class=\"ext\">百人隊長である.</span></div><div class=\"def\"><num>⑤</num> 階級, 地位.</div><div class=\"def\"><num>⑥</num> ひと続き, 連続</div><div class=\"ex\"><i>ex ordine</i> (<author>C<small>IC</small></author>)<span class=\"ext\">次々と, 連続して.</span></div><div class=\"def\"><num>⑦</num> 経過, 段階.</div><div class=\"def\"><num>⑧</num> (話などの)筋道, 脈絡.</div><div class=\"def\"><num>⑨</num> 順序</div><div class=\"ex\"><i>(in)ordine</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">順序正しく</span></div><div class=\"ex\"><i>extra ordinem</i><span class=\"ext\">順序が狂って.</span></div><div class=\"def\"><num>⑩</num> 配列, 整列.</div><div class=\"def\"><num>⑪</num> 秩序, 規則正しさ</div><div class=\"ex\"><i>ordine</i> (<author>C<small>IC</small></author>)<span class=\"ext\">適切に.</span></div><div class=\"def\"><num>⑫</num> <SUP>◇</SUP>〘キ教〙(聖職者の)位階, 聖品.</div><div class=\"def\"><num>⑬</num> <SUP>◇</SUP>〘カト〙修道会.</div><div class=\"def\"><num>⑭</num> <SUP>◇</SUP>〘カト〙年間祭式規程書.</div>\r\n","<div class=\"hw\">oreoselīnum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙セリ科の植物.</div>\r\n","<div class=\"hw\">Orestae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オレスタエ, <SUP>*</SUP>-タイ《Macedonia にいた一部族》.</div>\r\n","<div class=\"hw\">Orestilla</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">オレスティッラ《<i>Aurelia ～</i>, Catilina の妻》.</div>\r\n","<div class=\"hw\">Orestēs</div><div class=\"pos\">-is [-ae], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙オレステース《Agamemnon と Clytaemnestra の息子で Electra の弟;父を殺した母とその情夫 Aegisthus を殺して父のあだを討ち, 復讐の女神たち Furiae に追われた》.</div>\r\n","<div class=\"hw\">Orestēus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Orestes の.</div>\r\n","<div class=\"hw\">orexis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">欲望, 欲求.</div>\r\n","<div class=\"hw\">organicus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[organum]</div><div class=\"def\"><num>①</num> 道具[装置]の.</div><div class=\"def\"><num>②</num> 楽器の.</div><hr><div class=\"hw\">organicus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">楽器奏者, 演奏家.</div>\r\n","<div class=\"hw\">organum, -on</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> 道具, 器具, 装置.</div><div class=\"def\"><num>②</num> 楽器;(オルガンの)音管</div><div class=\"ex\"><i>～ hydraulicum</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">水力オルガン.</span></div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘動・解〙器官, 臓器.</div>\r\n","<div class=\"hw\">orgasmus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘生理〙オルガスムス《性的興奮[快感]の頂点》.</div>\r\n","<div class=\"hw\">Orgetorix</div><div class=\"pos\">-īgis, <i>m</i></div><div class=\"def\">オルゲトリクス《Caesar に敵対した Helvetii 族の指導者》.</div>\r\n","<div class=\"hw\">orgia</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(特に Bacchus の)乱飲乱舞の酒宴を伴う秘儀.</div>\r\n","<div class=\"hw\">orichalcum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">真鍮, 黄銅.</div>\r\n","<div class=\"hw\">oriens<SUP>1</SUP></div><div class=\"pos\">-entis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[orior]</div><div class=\"def\"><num>①</num> (天体が)昇る.</div><div class=\"def\"><num>②</num> 東の.</div><div class=\"def\"><num>③</num> 始まりの, 初期の.</div><hr><div class=\"hw\">oriens<SUP>2</SUP></div><div class=\"pos\">-entis, <i>m</i></div><div class=\"def\"><num>①</num> 昇る太陽;太陽神.</div><div class=\"def\"><num>②</num> 夜明け, 朝.</div><div class=\"def\"><num>③</num> 東;東方.</div>\r\n","<div class=\"hw\">orientālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[orior]</div><div class=\"def\">東の, 東方の.</div>\r\n","<div class=\"hw\">orientālēs</div><div class=\"pos\">-ium, <SUP>◇</SUP><i>m pl</i></div><div class=\"ori\">[↓<a href=\"entry://orientālis\">orientālis</a>]</div><div class=\"def\"><num>①</num> 東方の人たち.</div><div class=\"def\"><num>②</num> 東方教会の信者たち.</div>\r\n","<div class=\"hw\">orior</div><div class=\"pos\">-īrī ortus sum(<i>fut p</i> oritūrus), <i>intr dep</i></div><div class=\"def\"><num>①</num> (天体が)昇る.</div><div class=\"def\"><num>②</num> 起きる, 起き上がる.</div><div class=\"def\"><num>③</num> (川などが)源を発する.</div><div class=\"def\"><num>④</num> 始まる.</div><div class=\"def\"><num>⑤</num> (人・生き物が)生まれる.</div><div class=\"def\"><num>⑥</num> (...の)出である, 由来する 〈a [ex] re〉</div><div class=\"ex\"><i>plerosque Belgas esse ortos ab Germanis</i> (<author>C<small>AES</small></author>)<span class=\"ext\">Belgae 人のほとんどの部族が Germania 起源であること.</span></div><div class=\"def\"><num>⑦</num> (事が)起こる, 生ずる, 発生する;(...に)起因する.</div>\r\n","<div class=\"hw\">oriundus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[orior]</div><div class=\"def\">...に由来する, ...から発する 〈(a [ex])re〉.</div>\r\n","<div class=\"hw\">Oriundus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">オリウンドゥス《Illyria の川》.</div>\r\n","<div class=\"hw\">Ormenis</div><div class=\"pos\">-nidis, <i>adj f</i></div><div class=\"def\">(Amyntor の父)Ormenus の(子孫の).</div>\r\n","<div class=\"hw\">orneus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ornus]</div><div class=\"def\">マンナノキの.</div>\r\n","<div class=\"hw\">ornus</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"def\">〘植〙マンナノキ.</div>\r\n","<div class=\"hw\">ornāmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[orno]</div><div class=\"def\"><num>①</num> 装具, 衣裳.</div><div class=\"def\"><num>②</num> 飾り, 装飾.</div><div class=\"def\"><num>③</num> 顕章, 勲章.</div><div class=\"def\"><num>④</num> 文飾.</div><div class=\"def\"><num>⑤</num> 光彩[栄誉]を添えるもの[人].</div>\r\n","<div class=\"hw\">ornāmentārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://ornāmentum\">ornāmentum</a>]</div><div class=\"def\">《碑》官職には就かずにその標識を保持している, 名誉職の.</div>\r\n","<div class=\"hw\">ornātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[orno]</div><div class=\"def\">飾ること, 装飾.</div>\r\n","<div class=\"hw\">ornātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[orno]</div><div class=\"def\">《碑》</div><div class=\"def\"><num>①</num> 飾る者, 光彩を添える者.</div><div class=\"def\"><num>②</num> 着付けや化粧を手伝う奴隷.</div>\r\n","<div class=\"hw\">ornātrix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://ornātor\">ornātor</a>]</div><div class=\"def\"><num>①</num> 飾る者, 光彩を添える者《女性》.</div><div class=\"def\"><num>②</num> 着付けや化粧を手伝う女奴隷.</div>\r\n","<div class=\"hw\">ornātus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[orno]</div><div class=\"def\"><num>①</num> よく装備された 〈re〉.</div><div class=\"def\"><num>②</num> みごとに飾られた, 華麗な;(文体が)凝った.</div><div class=\"def\"><num>③</num> (...が)与え[授け]られた 〈re〉.</div><hr><div class=\"hw\">ornātus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 装備, 装具, 衣裳.</div><div class=\"def\"><num>②</num> 準備.</div><div class=\"def\"><num>③</num> 飾り, 装飾.</div><div class=\"def\"><num>④</num> 文飾.</div>\r\n","<div class=\"hw\">ornātē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[ornatus<SUP>1</SUP>]</div><div class=\"def\">飾って, 装飾的に, みごとに.</div>\r\n","<div class=\"hw\">ornīthōn</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">鳥小屋(=<a href=\"entry://aviārium\">aviarium</a>).</div>\r\n","<div class=\"hw\">ornō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"def\"><num>①</num> 装備する, 武装させる 〈alqm [alqd] re〉.</div><div class=\"def\"><num>②</num> 支給[調達]する;与える, 授ける.</div><div class=\"def\"><num>③</num> 着飾らせる;飾る, 装飾する;文飾を施す.</div><div class=\"def\"><num>④</num> 敬意を表する, 栄誉を与える.</div>\r\n","<div class=\"hw\">Oroanda</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オロアンダ《Pisidia の町》.</div>\r\n","<div class=\"hw\">Oroandensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Oroanda の.</div><div class=\"hw2\"><b>Oroandensēs</b></div><div class=\"pos2\">-ium, <i>m pl</i></div><div class=\"def2\">Oroanda の住民.</div>\r\n","<div class=\"hw\">Oroandicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Oroanda の.</div>\r\n","<div class=\"hw\">Oroandēs</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オロアンデース《Media の Taurus 山脈の一部》.</div>\r\n","<div class=\"hw\">orobanchē</div><div class=\"pos\">-es, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙ネナシカズラ.</div>\r\n","<div class=\"hw\">Orontēs</div><div class=\"pos\">-is [-ae], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オロンテース《Syria の川》.</div>\r\n","<div class=\"hw\">Orontēus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Orontes 川の;《詩》Syria の.</div>\r\n","<div class=\"hw\">orphanotrophīum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">孤児院.</div>\r\n","<div class=\"hw\">orphanus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">孤児.</div>\r\n","<div class=\"hw\">Orpheus<SUP>1</SUP></div><div class=\"pos\">-eī [-eos], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙オルペウス《Thracia の詩人で竪琴の名手;Eurydice の夫》.</div>\r\n","<div class=\"hw\">Orphicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Orpheus の.</div>\r\n","<div class=\"hw\">Orphēus<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Orphicus\">Orphicus</a>.</div>\r\n","<div class=\"hw\">orsa</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://orsus\">orsus<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> 企て, 企図.</div><div class=\"def\"><num>②</num> ことば, 発言.</div>\r\n","<div class=\"hw\">orsus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://ordior\">ordior</a>.</div><hr><div class=\"hw\">orsus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 織物.</div><div class=\"def\"><num>②</num> 開始, 始め.</div>\r\n","<div class=\"hw\">orthodoxus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">正統の, 正統信仰の.</div>\r\n","<div class=\"hw\">orthographia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘建〙(建物の)立面図.</div><div class=\"def\"><num>②</num> 正書法, 正字法.</div>\r\n","<div class=\"hw\">orthogōnius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">直角の.</div>\r\n","<div class=\"hw\">orthopaedīa</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘医〙整形外科学.</div>\r\n","<div class=\"hw\">orthopteron</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘昆〙直翅類.</div>\r\n","<div class=\"hw\">orthopȳgium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(鳥の)尾.</div>\r\n","<div class=\"hw\">Orthōsia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オルトーシア(ー)《 (1) Caria の町.(2) Phoenicia の町》.</div>\r\n","<div class=\"hw\">ortus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://orior\">orior</a>.</div><hr><div class=\"hw\">ortus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> (天体が)昇ること;日の出, 夜明け.</div><div class=\"def\"><num>②</num> 東;東方.</div><div class=\"def\"><num>③</num> 生まれること, 誕生.</div><div class=\"def\"><num>④</num> 始まり.</div><div class=\"def\"><num>⑤</num> 出現, 起こり.</div><div class=\"def\"><num>⑥</num> 生まれ, 出自;起源, 源.</div>\r\n","<div class=\"hw\">Ortygia</div><div class=\"pos\">-ae, <B>-ē</B> -ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オルテュギア(ー)《 (1) Delos 島の古名.(2) Syracusae の港の入口にあった島.(3) Ephesus の古名》.</div>\r\n","<div class=\"hw\">Ortygius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Ortygia (1)  (2) の.</div>\r\n","<div class=\"hw\">ortygomētra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘鳥〙ウズラクイナ.</div>\r\n","<div class=\"hw\">ortyx</div><div class=\"pos\">-ygis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙オオバコ属の植物.</div>\r\n","<div class=\"hw\">oryx</div><div class=\"pos\">-ygis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘動〙レイヨウの一種.</div>\r\n","<div class=\"hw\">oryza</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙米.</div>\r\n","<div class=\"hw\">Orēas</div><div class=\"pos\">-adis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙オレーアス, <SUP>*</SUP>オレイアス《山のニンフ》.</div>\r\n","<div class=\"hw\">Orēos</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">山に住む者《Bacchus の添え名》.</div>\r\n","<div class=\"hw\">orīganum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙ハナハッカ.</div>\r\n","<div class=\"hw\">orīginālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[origo]</div><div class=\"def\">原初の, 最初の</div><div class=\"ex\"><i>peccatum originale</i> (<author>A<small>UG</small></author>)<span class=\"ext\">原罪.</span></div>\r\n","<div class=\"hw\">orīginātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://orīgō\">orīgō</a>]</div><div class=\"def\">〘文〙語源.</div>\r\n","<div class=\"hw\">orīgō</div><div class=\"pos\">-ginis, <i>f</i></div><div class=\"ori\">[orior]</div><div class=\"def\"><num>①</num> 始まり, 起こり, 出現.</div><div class=\"def\"><num>②</num> 発端, 起源.</div><div class=\"def\"><num>③</num> 血統, 系統.</div><div class=\"def\"><num>④</num> 創始者;祖先.</div><div class=\"def\"><num>⑤</num> (<i>pl</i>)「起源論」《Cato Major 作の史書》.</div><div class=\"def\"><num>⑥</num> <SUP>◇</SUP>〘解〙(筋肉・末梢神経の)起始, 起点.</div>\r\n","<div class=\"hw\">orīpelargus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘動〙大型猛禽類の一種(=<a href=\"entry://percnopterus\">percnopterus</a>).</div>\r\n","<div class=\"hw\">Orōdēs</div><div class=\"pos\">-is [-ī], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オローデース《数人の東方の王;特に Parthia 王(在位前57‐37);彼の将軍がローマの Crassus を Carrhae で破った(前53)》.</div>\r\n","<div class=\"hw\">os<SUP>2</SUP></div><div class=\"pos\">ossis, <i>n</i></div><div class=\"def\"><num>①</num> 骨;(<i>pl</i>)骨身, 髄.</div><div class=\"def\"><num>②</num> (<i>pl</i>)遺骨, 遺骸.</div><div class=\"def\"><num>③</num> (木の)髄;(果実の)仁.</div>\r\n","<div class=\"hw\">Osca</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">オスカ《Hispania Tarraconensis の町;現 Huesca》.</div>\r\n","<div class=\"hw\">oscen</div><div class=\"pos\">-cinis, <i>m</i></div><div class=\"ori\">[obs-(=<a href=\"entry://ob-\">ob-</a>)/cano]</div><div class=\"def\">鳴き声によって前兆を告げる鳥;鳴禽<SUB>めいきん</SUB>.</div>\r\n","<div class=\"hw\">Oscensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Osca の.</div>\r\n","<div class=\"hw\">oscillum<SUP>1</SUP></div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[os<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> (小さな)口.</div><div class=\"def\"><num>②</num> (小さな)仮面, 面.</div><hr><div class=\"hw\">oscillum<SUP>2</SUP></div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ぶらんこ(に似たもの).</div>\r\n","<div class=\"hw\">oscillātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://oscillō\">oscillō</a>]</div><div class=\"def\">揺すること, 振動させること.</div>\r\n","<div class=\"hw\">oscillō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"ori\">[oscillum<SUP>2</SUP>]</div><div class=\"def\">ぶらんこに乗る.</div>\r\n","<div class=\"hw\">oscitans</div><div class=\"pos\">-antis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[oscito]</div><div class=\"def\">ものうげな, 気乗りしない.</div>\r\n","<div class=\"hw\">oscitanter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://oscitans\">oscitans</a>]</div><div class=\"def\">ものうげに, 気乗りしない様子で.</div>\r\n","<div class=\"hw\">oscitor</div><div class=\"pos\">-ārī, <i>intr dep</i></div><div class=\"def\">=<a href=\"entry://oscitō\">oscito</a>.</div>\r\n","<div class=\"hw\">oscitātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://oscitō\">oscitō</a>]</div><div class=\"def\"><num>①</num> 口を大きく開けること.</div><div class=\"def\"><num>②</num> あくび;退屈なこと.</div>\r\n","<div class=\"hw\">oscitō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"ori\">[os<SUP>1</SUP>/cieo]</div><div class=\"def\"><num>①</num> 口を大きく開ける;(花・葉が)開く.</div><div class=\"def\"><num>②</num> あくびをする.</div>\r\n","<div class=\"hw\">osculor</div><div class=\"pos\">-ārī -ātus sum, <i>tr</i>(<i>intr</i>)<i>dep</i></div><div class=\"ori\">[↓<a href=\"entry://osculum\">osculum</a>]</div><div class=\"def\"><num>①</num> 接吻する.</div><div class=\"def\"><num>②</num> かわいがる, 大事にする.</div>\r\n","<div class=\"hw\">osculum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[os<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> (小さな)口.</div><div class=\"def\"><num>②</num> 接吻, キス.</div>\r\n","<div class=\"hw\">osculābundus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[osculor]</div><div class=\"def\">接吻する.</div>\r\n","<div class=\"hw\">osculātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[osculor]</div><div class=\"def\">接吻, キス.</div>\r\n","<div class=\"hw\">osculātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://osculor\">osculor</a>.</div>\r\n","<div class=\"hw\">Oscus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Osci 族の.</div>\r\n","<div class=\"hw\">Oscī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">オスキー《Campania にいた古いイタリアの民族の一つ;ローマ人に征服された》.</div>\r\n","<div class=\"hw\">Osdroēna</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オスドロエーナ, <SUP>*</SUP>-ネー《Mesopotamia の西部地域》.</div>\r\n","<div class=\"hw\">Osdroēnī</div><div class=\"pos\">-ōrum, <SUP>◇</SUP><i>m pl</i></div><div class=\"def\">Osdroena の住民.</div>\r\n","<div class=\"hw\">Osismī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">オシスミー《Gallia 北西部にいたケルト系一部族》.</div>\r\n","<div class=\"hw\">Ossa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オッサ《Thessalia の山》.</div>\r\n","<div class=\"hw\">Ossaeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Ossa 山の.</div>\r\n","<div class=\"hw\">osseus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[os<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 骨の(ような), 骨から成る.</div><div class=\"def\"><num>②</num> 骨と皮の, やせこけた.</div>\r\n","<div class=\"hw\">ossiculum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[os<SUP>2</SUP>]</div><div class=\"def\">(小さな)骨.</div>\r\n","<div class=\"hw\">ossificātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[os<SUP>2</SUP>/facio]</div><div class=\"def\">〘生理〙骨化(作用).</div>\r\n","<div class=\"hw\">ossifraga</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘鳥〙ミサゴ.</div>\r\n","<div class=\"hw\">ossifragus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[os<SUP>2</SUP>/frango]</div><div class=\"def\"><num>①</num> 骨を砕く者.</div><div class=\"def\"><num>②</num> =<a href=\"entry://ossifraga\">ossifraga</a>.</div>\r\n","<div class=\"hw\">ossua</div><div class=\"pos\">-uum, <i>m pl</i></div><div class=\"ori\">[os<SUP>2</SUP>]</div><div class=\"def\">遺骨, 遺骸.</div>\r\n","<div class=\"hw\">ossulum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n dim</i></div><div class=\"ori\">[os<SUP>2</SUP>]</div><div class=\"def\">(小さな)骨.</div>\r\n","<div class=\"hw\">ossuārium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[os<SUP>2</SUP>]</div><div class=\"def\">納骨堂.</div>\r\n","<div class=\"hw\">ostendī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://ostendō\">ostendo</a>.</div>\r\n","<div class=\"hw\">ostendō</div><div class=\"pos\">-ere -tendī -tentum [-tensum], <i>tr</i></div><div class=\"ori\">[obs-(=<a href=\"entry://ob-\">ob-</a>)/tendo<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 差し出す, 見せる 〈alci alqd〉;(<i>refl</i>)進み出る, 名のりを上げる.</div><div class=\"def\"><num>②</num> 現わす;あらわにする, さらす;(<i>refl</i>)姿を現わす, 現われる.</div><div class=\"def\"><num>③</num> 指し示す;注意を向けさせる, 指摘する;(道・方法を)教える.</div><div class=\"def\"><num>④</num> (力・好意などを)示す, 表わす</div><div class=\"ex\"><i>auctoritatem suam ostendere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">自分の権威を示す.</span></div><div class=\"def\"><num>⑤</num> 知らせる, 明らかにする</div><div class=\"ex\"><i>omnem animum ostendere</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">心の内をすべて明かす.</span></div><div class=\"def\"><num>⑥</num> 証明[立証]する.</div><div class=\"def\"><num>⑦</num> 意志を表明する, 約束する.</div><div class=\"def\"><num>⑧</num> 予期させる</div><div class=\"ex\"><i>tum spem, tum metum ostendere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ある時は希望をもたせ, ある時は恐れを抱かせる.</span></div>\r\n","<div class=\"hw\">ostensiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://ostendō\">ostendō</a>]</div><div class=\"def\">示すこと, 明示.</div>\r\n","<div class=\"hw\">ostensus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://ostendō\">ostendo</a>.</div>\r\n","<div class=\"hw\">ostensōrium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[ostendo]</div><div class=\"def\">〘カト〙(聖体)顕示台.</div>\r\n","<div class=\"hw\">ostentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://ostentus\">ostentus<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> 兆し, 前兆.</div><div class=\"def\"><num>②</num> 怪異, 不可思議なもの.</div>\r\n","<div class=\"hw\">ostentus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://ostendō\">ostendo</a>.</div><hr><div class=\"hw\">ostentus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i>(通例 <i>sg dat</i> で用いられる)</div><div class=\"def\"><num>①</num> 見せること</div><div class=\"ex\"><i>ostentui</i> (<author>T<small>AC</small></author>)<span class=\"ext\">見せしめ[見世物]として.</span></div><div class=\"def\"><num>②</num> 誇示.</div><div class=\"def\"><num>③</num> 証拠.</div>\r\n","<div class=\"hw\">ostentātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[ostento]</div><div class=\"def\"><num>①</num> 見せること, 表明, 表示.</div><div class=\"def\"><num>②</num> 見せびらかし, 誇示;自慢.</div><div class=\"def\"><num>③</num> 見せかけ, ふり.</div>\r\n","<div class=\"hw\">ostentātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://ostentō\">ostentō</a>]</div><div class=\"def\">見せびらかす者;ほら吹き.</div>\r\n","<div class=\"hw\">ostentō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr freq</i></div><div class=\"ori\">[ostendo]</div><div class=\"def\"><num>①</num> 差し出す, 見せる.</div><div class=\"def\"><num>②</num> 見せびらかす, 誇示する.</div><div class=\"def\"><num>③</num> (行為によって感情・性質などを)示す, 表わす</div><div class=\"ex\"><i>ostentare patientiam</i> (<author>C<small>IC</small></author>)<span class=\"ext\">忍耐力を示す.</span></div><div class=\"def\"><num>④</num> 自慢する, 大言壮語する;ふりをする, 装う.</div><div class=\"def\"><num>⑤</num> 指し示す;注意を向けさせる.</div><div class=\"def\"><num>⑥</num> 知らせる, 明らかにする.</div><div class=\"def\"><num>⑦</num> 予期させる</div><div class=\"ex\"><i>capitis periculum ostentare</i> (<author>C<small>IC</small></author>)<span class=\"ext\">死罪を予期させて脅す.</span></div>\r\n","<div class=\"hw\">osteologia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘医〙骨学.</div>\r\n","<div class=\"hw\">osteomalacia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙骨軟化症.</div>\r\n","<div class=\"hw\">osteomyelītis</div><div class=\"pos\">-tidis, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙骨髄炎.</div>\r\n","<div class=\"hw\">osteōma</div><div class=\"pos\">-atis, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘病〙骨腫.</div>\r\n","<div class=\"hw\">Ostia</div><div class=\"pos\">-ae, <i>f</i>, <B>-a</B> -ōrum, <i>n pl</i></div><div class=\"def\">オスティア《Tiberis 川の河口にあったローマ市の外港》.</div>\r\n","<div class=\"hw\">Ostiensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Ostia の.</div>\r\n","<div class=\"hw\">ostiolum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[↓<a href=\"entry://ostium\">ostium</a>]</div><div class=\"def\">(小さな)門, 戸.</div>\r\n","<div class=\"hw\">ostium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[os<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 戸, 門.</div><div class=\"def\"><num>②</num> 開口部.</div><div class=\"def\"><num>③</num> 河口, 港口.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>〘解〙口.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>〘動〙(節足動物の)心門.</div>\r\n","<div class=\"hw\">ostiāria</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[ostiarius]</div><div class=\"def\">女門番.</div>\r\n","<div class=\"hw\">ostiārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://ostiārius\">ostiārius</a>]</div><div class=\"def\">玄関税.</div>\r\n","<div class=\"hw\">ostiārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[ostium]</div><div class=\"def\"><num>①</num> 門番.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘カト〙守門《最下級の聖職者》.</div>\r\n","<div class=\"hw\">ostiātim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[ostium]</div><div class=\"def\">一軒ごとに, 各戸に.</div>\r\n","<div class=\"hw\">ostraceum, -ium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘貝〙ムラサキガイ.</div>\r\n","<div class=\"hw\">ostracismus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(Athenae の)陶片追放《危険人物を市民の陶片による投票で10年間国外へ追放した》.</div>\r\n","<div class=\"hw\">ostrea</div><div class=\"pos\">-ae, <i>f</i>, <B>-um</B> -ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘貝〙</div><div class=\"def\"><num>①</num> 二枚貝.</div><div class=\"def\"><num>②</num> カキ(牝蠣).</div>\r\n","<div class=\"hw\">ostreārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://ostreārius\">ostreārius</a>]</div><div class=\"def\">カキ養殖場.</div>\r\n","<div class=\"hw\">ostreārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ostrea]</div><div class=\"def\">カキの.</div>\r\n","<div class=\"hw\">ostreōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ostrea]</div><div class=\"def\">カキの多い.</div>\r\n","<div class=\"hw\">ostrifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[ostrea/fero]</div><div class=\"def\">カキを産する, カキの多い.</div>\r\n","<div class=\"hw\">ostrum, austrum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 深紅色の染料;深紅色.</div><div class=\"def\"><num>②</num> 深紅色の衣[上掛け].</div>\r\n","<div class=\"hw\">ostrīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://ostrum\">ostrum, austrum</a>]</div><div class=\"def\">深紅色の.</div>\r\n","<div class=\"hw\">Ostōrius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">オストーリウス《ローマ人の氏族名;特に <i>P. ～ Scapula</i>, Britannia の総督(後47‐52)》.</div>\r\n","<div class=\"hw\">Osī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">オシー《Germania にいた一部族》.</div>\r\n","<div class=\"hw\">Osīris</div><div class=\"pos\">-is [-idis], <i>m</i></div><div class=\"ori\">[<i>Gk</i><<i>Egypt</i>.]</div><div class=\"def\">〘神話〙オシーリス《エジプトの冥府の神;Isis の夫》.</div>\r\n","<div class=\"hw\">Othryadēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙オトリュアデース《Thyrea の領有をめぐって Sparta と Argos の各300人が戦った(前545頃)ときの Sparta 側の唯一の生存者》.</div>\r\n","<div class=\"hw\">Othrys</div><div class=\"pos\">-yos, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オトリュス《Thessalia 南部の山》.</div>\r\n","<div class=\"hw\">Othō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">オトー《ローマ人の家名;特に (1) <i>L. Roscius ～</i>, Cicero の友人で護民官(前67).(2) <i>M. Salvius ～</i>, 皇帝(後69)》.</div>\r\n","<div class=\"hw\">Othōniānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Otho 帝の.</div>\r\n","<div class=\"hw\">Otācilius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">オターキリウス《ローマ人の氏族名;特に <i>T. ～ Crassus</i>, Sicilia の propraetor で第2次 Poeni 戦争の際 Sicilia の艦隊の指揮官をつとめた》.</div>\r\n","<div class=\"hw\">ovanter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[ovo]</div><div class=\"def\">歓喜して.</div>\r\n","<div class=\"hw\">ovicula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[ovis]</div><div class=\"def\">〘動〙(小さな)羊.</div>\r\n","<div class=\"hw\">Ovidius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">オウィディウス《ローマ人の氏族名;特に <i>P. ～ Naso</i>, Augustus 帝時代の詩人(前43‐後17);Augustus 帝に追放され配所の Tomi で没した》.</div>\r\n","<div class=\"hw\">Ovidiānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Ovidius の.</div>\r\n","<div class=\"hw\">ovilla</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://ovillus\">ovillus</a>]</div><div class=\"def\">羊肉.</div>\r\n","<div class=\"hw\">ovillus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ovis]</div><div class=\"def\">羊の.</div>\r\n","<div class=\"hw\">ovis</div><div class=\"pos\">-is, <i>f</i>(<i>m</i>)</div><div class=\"def\"><num>①</num> 〘動〙ヒツジ(羊).</div><div class=\"def\"><num>②</num> 羊毛.</div><div class=\"def\"><num>③</num> だまされやすい人, まぬけ.</div>\r\n","<div class=\"hw\">oviārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ovis]</div><div class=\"def\">羊の.</div>\r\n","<div class=\"hw\">ovālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[ovo]</div><div class=\"def\">小凱旋式の.</div>\r\n","<div class=\"hw\">ovātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[ovo]</div><div class=\"def\">小凱旋式.</div>\r\n","<div class=\"hw\">ovātus<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[ovo]</div><div class=\"def\">小凱旋式の.</div><hr><div class=\"hw\">ovātus<SUP>3</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">歓声.</div>\r\n","<div class=\"hw\">ovīle</div><div class=\"pos\">-is, <i>n</i></div><div class=\"ori\">[ovilis]</div><div class=\"def\"><num>①</num> 羊小屋, 羊のおり.</div><div class=\"def\"><num>②</num> (Campus Martius にあった, 民会の)投票所.</div>\r\n","<div class=\"hw\">ovīlio</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://ovīlis\">ovīlis</a>]</div><div class=\"def\">羊飼い, 牧羊者.</div>\r\n","<div class=\"hw\">ovīlis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[ovis]</div><div class=\"def\">羊の.</div>\r\n","<div class=\"hw\">ovīna</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://ovīnus\">ovīnus</a>]</div><div class=\"def\">=<a href=\"entry://ovilla\">ovilla</a>.</div>\r\n","<div class=\"hw\">ovīnus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">=<a href=\"entry://ovillus\">ovillus</a>.</div>\r\n","<div class=\"hw\">ovō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>(主に <i>prp</i> ovans で)</div><div class=\"def\"><num>①</num> 歓喜する, 大喜びする.</div><div class=\"def\"><num>②</num> 小凱旋式をする.</div>\r\n","<div class=\"hw\">oxalis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙スイバ.</div>\r\n","<div class=\"hw\">oxydātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘化〙酸化.</div>\r\n","<div class=\"hw\">oxygarum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">酢入りの魚のソース.</div>\r\n","<div class=\"hw\">oxygenium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘化〙酸素.</div>\r\n","<div class=\"hw\">oxygōnius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">鋭角の.</div>\r\n","<div class=\"hw\">oxymeli</div><div class=\"pos\">-itis, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">酢蜜《蜂蜜と酢を混ぜたもので薬として用いられた》.</div>\r\n","<div class=\"hw\">oxymōron</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘修〙撞着語法《反意語を組み合わせること》.</div>\r\n","<div class=\"hw\">oxyporum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">消化剤.</div>\r\n","<div class=\"hw\">ozaena</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘動〙タコの一種.</div><div class=\"def\"><num>②</num> 〘病〙蓄膿症.</div>\r\n","<div class=\"hw\">ozaenītis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"def\">〘植〙甘松の一種.</div>\r\n","<div class=\"hw\">Oīleus</div><div class=\"pos\">-eī [-eos], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙オイーレウス《Locris の Opus の王;Argonautae の一人;小 Ajax の父》.</div>\r\n","<div class=\"hw\">Oīliadēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Oileus の息子(=小 Ajax).</div>\r\n","<div class=\"hw\">ō</div><div class=\"pos\"><i>int</i></div><div class=\"def\">(呼びかけ・感嘆・喜び・恐怖・願望などを表わす)おお, ああ</div><div class=\"ex\"><i>o mi Furni</i> (<author>C<small>IC</small></author>)<span class=\"ext\">おお, わが Furnius よ.</span></div>\r\n","<div class=\"hw\">ōariōn</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">《詩》=<a href=\"entry://ōrīōn\">Orion</a>.</div>\r\n","<div class=\"hw\">ōceanicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[Oceanus]</div><div class=\"def\">大洋の.</div>\r\n","<div class=\"hw\">ōceanidēs</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>m</i></div><div class=\"def\">Oceanus の息子.</div>\r\n","<div class=\"hw\">ōceanis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"def\">=<a href=\"entry://ōceanītis\">Oceanitis</a>.</div>\r\n","<div class=\"hw\">ōceanus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘神話〙オーケアヌス, <SUP>*</SUP>-ノス《大洋神;天空神 Uranus と大地の女神 Gaea の子で Tethys の夫;多くの河川と Oceanitis たちの父》.</div><div class=\"def\"><num>②</num> 大地を取り巻いている大洋.</div>\r\n","<div class=\"hw\">ōceanītis</div><div class=\"pos\">-tidis [-idos], <i>f</i></div><div class=\"def\">Oceanus の娘.</div>\r\n","<div class=\"hw\">ōcelum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">オーケルム《Gallia Cisalpina の町》.</div>\r\n","<div class=\"hw\">ōchra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">黄土《顔料として用いられる》.</div>\r\n","<div class=\"hw\">ōchus</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オークス, <SUP>*</SUP>-コス《 (1) Bactria の川;Oxos 川に注ぐ.(2) ペルシア王 Artaxerxes III の添え名.(3) ペルシア王 Dareus II の添え名》.</div>\r\n","<div class=\"hw\">ōcimum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙メボウキ.</div>\r\n","<div class=\"hw\">ōcinum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">飼料の一種.</div>\r\n","<div class=\"hw\">ōcior</div><div class=\"pos\">-ior -ius, <i>adj comp</i></div><div class=\"def\"><num>①</num> よりすばやい[迅速な].</div><div class=\"def\"><num>②</num> (時間的に)より早い.</div>\r\n","<div class=\"hw\">ōciter</div><div class=\"pos\">(<i>comp</i> ōcius, <i>superl</i> ōcissimē)<i>adv</i></div><div class=\"def\"><num>①</num> すばやく, 迅速に.</div><div class=\"def\"><num>②</num> 即座に, 直ちに.</div>\r\n","<div class=\"hw\">ōcyrhoē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙オーキュロエー《Chiron の娘;神々の秘密をもらしたため馬に変えられた》.</div>\r\n","<div class=\"hw\">ōdarium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(短い)歌.</div>\r\n","<div class=\"hw\">ōdisse</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://ōdī\">odi</a>.</div>\r\n","<div class=\"hw\">ōdē</div><div class=\"pos\">-ēs, <B>-a</B> -ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">歌;抒情詩.</div>\r\n","<div class=\"hw\">ōdēum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">音楽堂.</div>\r\n","<div class=\"hw\">ōdī</div><div class=\"pos\">ōdisse ōsum(<i>fut p</i> ōsūrus), <i>tr</i>(<i>pf</i> で現在時称を表わす)</div><div class=\"def\">憎む, (ひどく)嫌う 〈+<i>acc</i>;+<i>inf</i>〉.</div>\r\n","<div class=\"hw\">ōgygia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙オーギュギア(ー)《Calypso が住んでいたという島》.</div>\r\n","<div class=\"hw\">ōgygidae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Ogyges の子孫(=<a href=\"entry://Thēbae\">Thebae</a> 人).</div>\r\n","<div class=\"hw\">ōgygius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Ogyges の;《詩》Thebae の.</div>\r\n","<div class=\"hw\">ōgygos, -us</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://ōgygēs\">Ogyges</a>.</div>\r\n","<div class=\"hw\">ōgygēs</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙オーギュゲース 《Thebae の創建者で王;その治世中に大洪水があった》.</div>\r\n","<div class=\"hw\">ōh, ō</div><div class=\"pos\"><i>int</i></div><div class=\"def\">(喜び・苦痛・悲嘆・非難・驚きなどを表わす)おお, ああ.</div>\r\n","<div class=\"hw\">ōlearos, ōlia-</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オーレアロス《Cyclades 諸島の Paros 島対岸の島;現 Andíparos》.</div>\r\n","<div class=\"hw\">ōlecrānon</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘解〙肘頭<SUB>ちゅうとう</SUB>.</div>\r\n","<div class=\"hw\">ōlenius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">(Aetolia の)Olenus の;《詩》Aetolia の.</div>\r\n","<div class=\"hw\">ōlenus</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オーレヌス, <SUP>*</SUP>-ノス《いくつかの町の名;特に Aetolia 南部の町》.</div>\r\n","<div class=\"hw\">ōlim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[<i>cf</i>. olle, ille]</div><div class=\"def\"><num>①</num> 以前に, かつて.</div><div class=\"def\"><num>②</num> 久しく, 以前から.</div><div class=\"def\"><num>③</num> 将来いつか, 他日.</div><div class=\"def\"><num>④</num> 時々, 時折.</div>\r\n","<div class=\"hw\">ōmen</div><div class=\"pos\">ōminis, <i>n</i></div><div class=\"def\"><num>①</num> 前兆, 予兆.</div><div class=\"def\"><num>②</num> 吉兆;凶兆.</div><div class=\"def\"><num>③</num> 縁起のよい[悪い]ことば.</div><div class=\"def\"><num>④</num> </div><div class=\"ex\"><i>prima omina</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">結婚を是とする吉兆.</span></div>\r\n","<div class=\"hw\">ōmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> (腸をおおう)脂肪膜.</div><div class=\"def\"><num>②</num> 腸, はらわた.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘解〙大網《胃から出て腸に至る腹膜のひだ》.</div>\r\n","<div class=\"hw\">ōminor</div><div class=\"pos\">-ārī -ātus sum, <i>tr dep</i></div><div class=\"ori\">[omen]</div><div class=\"def\">(前兆によって)予知する, 予言する 〈+<i>acc c. inf</i>;+間接疑問〉</div><div class=\"ex\"><i>male ominata verba</i> (<author>H<small>OR</small></author>)<span class=\"ext\">不吉なことば.</span></div>\r\n","<div class=\"hw\">ōminālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[omen]</div><div class=\"def\">不吉な, 縁起の悪い.</div>\r\n","<div class=\"hw\">ōminātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[ominor]</div><div class=\"def\">予兆, 前兆.</div>\r\n","<div class=\"hw\">ōminātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[ominor]</div><div class=\"def\">予言者.</div>\r\n","<div class=\"hw\">ōminātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://ōminor\">ominor</a>.</div>\r\n","<div class=\"hw\">ōminō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"def\">=<a href=\"entry://ōminor\">ominor</a>.</div>\r\n","<div class=\"hw\">ōminōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[omen]</div><div class=\"def\">凶兆の, 不吉な.</div>\r\n","<div class=\"hw\">ōmohyoīdeus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙肩甲舌骨の.</div>\r\n","<div class=\"hw\">ōmophorion</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(東方教会の)主教用肩衣.</div>\r\n","<div class=\"hw\">ōoecium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘動〙(コケムシ類の)卵室.</div>\r\n","<div class=\"hw\">ōogenesis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘生物〙卵形成.</div>\r\n","<div class=\"hw\">ōogonium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\"><num>①</num> 〘植〙生卵器.</div><div class=\"def\"><num>②</num> 〘生物〙卵原細胞.</div>\r\n","<div class=\"hw\">ōophoron</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘解〙卵巣(=<a href=\"entry://ōvārium\">ovarium</a>).</div>\r\n","<div class=\"hw\">ōpiliō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[ovis]</div><div class=\"def\">(羊・山羊の)番人.</div>\r\n","<div class=\"hw\">ōpis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙オーピス《Diana に仕えるニンフの一人》.</div>\r\n","<div class=\"hw\">ōra<SUP>1</SUP></div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">(船をつなぐ)太綱, 大索<SUB>だいさく</SUB>.</div><hr><div class=\"hw\">ōra<SUP>2</SUP></div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[os<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 縁, へり.</div><div class=\"def\"><num>②</num> 海岸, 沿岸;沿岸の住民.</div><div class=\"def\"><num>③</num> 国土, 地方</div><div class=\"ex\"><i>orae luminis</i> (<author>L<small>UCR</small></author>)<span class=\"ext\">光明の世界, 生あるものたちの世.</span></div><div class=\"def\"><num>④</num> <SUP>◇</SUP>〘解〙縁</div><div class=\"ex\"><i>～ serrata</i><span class=\"ext\">(網膜の)鋸状縁.</span></div>\r\n","<div class=\"hw\">ōreae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"ori\">[os<SUP>1</SUP>]</div><div class=\"def\">(くつわの)はみ.</div>\r\n","<div class=\"hw\">ōreus, -eos</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オーレウス, <SUP>*</SUP>-オス《Euboea 島の町》.</div>\r\n","<div class=\"hw\">ōricilla</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[auris]</div><div class=\"def\">耳たぶ.</div>\r\n","<div class=\"hw\">ōricius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Oricos の.</div>\r\n","<div class=\"hw\">ōricos</div><div class=\"pos\">-ī, <i>f</i>, <B>-um</B> -ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オーリコス《Illyria の港町》.</div>\r\n","<div class=\"hw\">ōricula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://auricula\">auricula</a>.</div>\r\n","<div class=\"hw\">ōricīnī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">Oricos の住民.</div>\r\n","<div class=\"hw\">ōrificium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[os<SUP>1</SUP>/facio]</div><div class=\"def\">開口部, 口.</div>\r\n","<div class=\"hw\">ōrigenēs</div><div class=\"pos\">-is, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オーリゲネース《Alexandria 生まれの神学者で教父(185?‐?254)》.</div>\r\n","<div class=\"hw\">ōrāculum, ōrāclum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[oro]</div><div class=\"def\"><num>①</num> 神託, 託宣;予言.</div><div class=\"def\"><num>②</num> 託宣者;神託所.</div><div class=\"def\"><num>③</num> 神託めいた発言, 教え, 格言.</div>\r\n","<div class=\"hw\">ōrālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[os<SUP>1</SUP>]</div><div class=\"def\">口の, 口頭の.</div>\r\n","<div class=\"hw\">ōrāmen</div><div class=\"pos\">-minis, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[oro]</div><div class=\"def\">祈り.</div>\r\n","<div class=\"hw\">ōrārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ora<SUP>2</SUP>]</div><div class=\"def\">沿岸航行の.</div>\r\n","<div class=\"hw\">ōrāta</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">オーラータ《ローマ人の家名;特に <i>C. Sergius ～</i>, 法務官(前97年);奢侈な生活で有名》.</div>\r\n","<div class=\"hw\">ōrātiuncula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[↑<a href=\"entry://ōrātiō\">ōrātiō</a>]</div><div class=\"def\">(短い)話[演説].</div>\r\n","<div class=\"hw\">ōrātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[oro]</div><div class=\"def\"><num>①</num> 話すこと;会話, 談義.</div><div class=\"def\"><num>②</num> 話し方, 言いまわし;文体</div><div class=\"ex\">～ <i>soluta [prorsa</i>] (<author>V<small>ARR</small> [P<small>LIN</small>]</author>)<span class=\"ext\">散文.</span></div><div class=\"def\"><num>③</num> 発言, 陳述;声明.</div><div class=\"def\"><num>④</num> 演説, 弁論;雄弁術.</div><div class=\"def\"><num>⑤</num> 伝言.</div><div class=\"def\"><num>⑥</num> 単語</div><div class=\"ex\"><i>pars orationis</i> (<author>Q<small>UINT</small></author>)<span class=\"ext\">〘文〙品詞.</span></div><div class=\"def\"><num>⑦</num> 言語;方言.</div><div class=\"def\"><num>⑧</num> 勅令, 勅諭.</div><div class=\"def\"><num>⑨</num> <SUP>◇</SUP> 祈り, 祈祷</div><div class=\"ex\">～ <i>dominica</i><span class=\"ext\">主の祈り.</span></div><div class=\"def\"><num>⑩</num> <SUP>◇</SUP>〘文〙話法</div><div class=\"ex\">～ <i>recta</i><span class=\"ext\">直接話法</span></div><div class=\"ex\">～ <i>obliqua</i><span class=\"ext\">間接話法.</span></div>\r\n","<div class=\"hw\">ōrātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[oro]</div><div class=\"def\"><num>①</num> 代弁者, 代理人.</div><div class=\"def\"><num>②</num> 演説者, 弁論家.</div>\r\n","<div class=\"hw\">ōrātrix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"ori\">[orator]</div><div class=\"def\"><num>①</num> 嘆願[懇願]者《女性》.</div><div class=\"def\"><num>②</num> 雄弁術, 修辞学.</div>\r\n","<div class=\"hw\">ōrātum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://ōrātus\">ōrātus<SUP>1</SUP></a>]</div><div class=\"def\">願い(ごと).</div>\r\n","<div class=\"hw\">ōrātus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://ōrō\">oro</a>.</div><hr><div class=\"hw\">ōrātus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">懇願, 要請.</div>\r\n","<div class=\"hw\">ōrātōria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[oratorius]</div><div class=\"def\">(<i>sc. </i> ars)雄弁術, 修辞学.</div>\r\n","<div class=\"hw\">ōrātōriolum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n dim</i></div><div class=\"ori\">[↓<a href=\"entry://ōrātōrium\">ōrātōrium</a>]</div><div class=\"def\">小礼拝堂.</div>\r\n","<div class=\"hw\">ōrātōrium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↓<a href=\"entry://ōrātōrius\">ōrātōrius</a>]</div><div class=\"def\">祈祷室, 礼拝堂.</div>\r\n","<div class=\"hw\">ōrātōrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[orator]</div><div class=\"def\">演説の, 雄弁の;演説家の</div><div class=\"ex\"><i>ars oratoria</i> (<author>Q<small>UINT</small></author>)<span class=\"ext\">雄弁術.</span></div>\r\n","<div class=\"hw\">ōrātōriē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[oratorius]</div><div class=\"def\">演説風に, 雄弁に.</div>\r\n","<div class=\"hw\">ōrētānī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">Hispania の町 Oretum の住民.</div>\r\n","<div class=\"hw\">ōrītae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オーリータエ, <SUP>*</SUP>オーレイタイ《魚を常食とする India の一部族》.</div>\r\n","<div class=\"hw\">ōrīthyia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙オーリーテュイア, <SUP>*</SUP>オーレイ-《Athenae の王 Erechtheus の娘;北風神 Aquilo にさらわれて妻となり, Calais と Zetes を生んだ》.</div>\r\n","<div class=\"hw\">ōrīōn</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘伝説〙オーリーオーン《巨漢で美男の猟師;Diana に殺され, 死後星座となった》.</div><div class=\"def\"><num>②</num> 〘天〙オリオン座.</div>\r\n","<div class=\"hw\">ōrō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>, <i>intr</i></div><div class=\"def\"><num>①</num> 懇願[嘆願]する, 祈る 〈alqm;alqd;ut, ne;+<i>subj</i>〉.</div><div class=\"def\"><num>②</num> 論ずる, 弁ずる</div><div class=\"ex\"><i>orare causam [litem]</i> (<author>T<small>ER</small> [C<small>IC</small>]</author>)<span class=\"ext\">事件を弁護する.</span></div>\r\n","<div class=\"hw\">ōrōpus, -os</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オーロープス, <SUP>*</SUP>-ポス《Attica との境にある Boeotia の町》.</div>\r\n","<div class=\"hw\">ōs<SUP>1</SUP></div><div class=\"pos\">ōris, <i>n</i></div><div class=\"def\"><num>①</num> 口;(鳥の)くちばし</div><div class=\"ex\"><i>uno ore</i> (<author>T<small>ER</small></author>)<span class=\"ext\">異口同音に</span></div><div class=\"ex\"><i>semper in ore habere alqm</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ある人の名前をいつも口にする.</span></div><div class=\"def\"><num>②</num> 話し方, 発音;ことば, 発言.</div><div class=\"def\"><num>③</num> 開口部, 口;河口, 入口.</div><div class=\"def\"><num>④</num> 顔;顔つき, 表情</div><div class=\"ex\">～ <i>durum</i> (<author>C<small>IC</small></author>)<span class=\"ext\">厚顔(無恥).</span></div><div class=\"def\"><num>⑤</num> 仮面.</div><div class=\"def\"><num>⑥</num> 見えるところ, 面前</div><div class=\"ex\"><i>in ore parentium</i> (<author>S<small>EN</small></author>)<span class=\"ext\">両親の目の前で.</span></div><div class=\"def\"><num>⑦</num> 正面, 前面.</div>\r\n","<div class=\"hw\">ōsmotaxis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘生物〙走濃性.</div>\r\n","<div class=\"hw\">ōsmōsis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘理〙浸透.</div>\r\n","<div class=\"hw\">ōsor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[odi]</div><div class=\"def\">憎む人, 嫌う人.</div>\r\n","<div class=\"hw\">ōsus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://ōdī\">odi</a>.</div>\r\n","<div class=\"hw\">ōsūrus</div><div class=\"pos\">-a -um, <i>fut p</i></div><div class=\"def\">⇒<a href=\"entry://ōdī\">odi</a>.</div>\r\n","<div class=\"hw\">ōticus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">耳の.</div>\r\n","<div class=\"hw\">ōtiolum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[otium]</div><div class=\"def\">(少しの)暇.</div>\r\n","<div class=\"hw\">ōtion</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘貝〙アワビ.</div>\r\n","<div class=\"hw\">ōtior</div><div class=\"pos\">-ārī -ātus sum, <i>intr dep</i></div><div class=\"ori\">[otium]</div><div class=\"def\">閑暇を楽しむ, くつろぐ.</div>\r\n","<div class=\"hw\">ōtis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘鳥〙ノガン(野雁).</div>\r\n","<div class=\"hw\">ōtium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> ひま, 閑暇;休暇.</div><div class=\"def\"><num>②</num> 休息, くつろぎ.</div><div class=\"def\"><num>③</num> 余暇の産物(=詩).</div><div class=\"def\"><num>④</num> 平安, 平穏, 平和.</div>\r\n","<div class=\"hw\">ōtiābundus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[otior]</div><div class=\"def\">閑暇を楽しんでいる.</div>\r\n","<div class=\"hw\">ōtiōsus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[otium]</div><div class=\"def\"><num>①</num> ひまな, 仕事のない, 有閑の.</div><div class=\"def\"><num>②</num> 無関心な, 無為の.</div><div class=\"def\"><num>③</num> 無用の, 無益な.</div><div class=\"def\"><num>④</num> (人が)静かな, 落ちついた.</div><div class=\"def\"><num>⑤</num> 乱されない, 悩まされない</div><div class=\"ex\">～ <i>esse</i> (<author>C<small>IC</small></author>)<span class=\"ext\">平穏に暮らす.</span></div><div class=\"def\"><num>⑥</num> (文体が)単調な, 退屈な.</div><div class=\"def\"><num>⑦</num> (時間・役職などが)空いている, 使われていない.</div><hr><div class=\"hw\">ōtiōsus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 私人, 公職に就いていない人.</div><div class=\"def\"><num>②</num> 非戦闘員, 一般市民.</div>\r\n","<div class=\"hw\">ōtiōsē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://ōtiōsus\">ōtiōsus<SUP>1</SUP></a>]</div><div class=\"def\">のんびりと, 落ちついて.</div>\r\n","<div class=\"hw\">ōtoconia</div><div class=\"pos\">-ōrum, <SUP>◇</SUP><i>n pl</i></div><div class=\"def\">〘医〙耳塵<SUB>じじん</SUB>, 平衡砂.</div>\r\n","<div class=\"hw\">ōtologia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘医〙耳科学.</div>\r\n","<div class=\"hw\">ōtorrhoea</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙耳漏.</div>\r\n","<div class=\"hw\">ōtos, -us</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙オートス《Ephialtes の兄で巨人》.</div>\r\n","<div class=\"hw\">ōtus</div><div class=\"pos\">-i, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘鳥〙フクロウの一種.</div>\r\n","<div class=\"hw\">ōtītis</div><div class=\"pos\">otītidis, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙耳炎</div><div class=\"ex\"><i>～ externa</i><span class=\"ext\">外耳炎</span></div><div class=\"ex\"><i>～ interna</i><span class=\"ext\">内耳炎</span></div><div class=\"ex\"><i>～ media</i><span class=\"ext\">中耳炎.</span></div>\r\n","<div class=\"hw\">ōviparus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[ovum/pario<SUP>2</SUP>]</div><div class=\"def\">〘動〙卵生の.</div>\r\n","<div class=\"hw\">ōvogenesis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘生物〙卵形成.</div>\r\n","<div class=\"hw\">ōvotestis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘生物〙卵精巣.</div>\r\n","<div class=\"hw\">ōvulum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n dim</i></div><div class=\"ori\">[↓<a href=\"entry://ōvum\">ōvum</a>]</div><div class=\"def\"><num>①</num> 〘生物〙卵<SUB>らん</SUB>.</div><div class=\"def\"><num>②</num> 〘植〙胚珠.</div>\r\n","<div class=\"hw\">ōvum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> 卵</div><div class=\"ex\"><i>ab ovo usque ad mala</i><span class=\"ext\">(⇒ <a href=\"entry://mālum\">malum<SUP>1</SUP></a>).</span></div><div class=\"def\"><num>②</num> (特に, 競技場で何周走ったかを数えるために用いられた)卵形の計数装置.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘生物〙卵<SUB>らん</SUB>, 卵子.</div>\r\n","<div class=\"hw\">ōvārium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\"><num>①</num> 〘解〙卵巣(=<a href=\"entry://ōophoron\">oophoron</a>).</div><div class=\"def\"><num>②</num> 〘植〙子房.</div>\r\n","<div class=\"hw\">ōvātus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ovum]</div><div class=\"def\">卵形の.</div>\r\n","<div class=\"hw\">ōxos, -us</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オークソス《Sogdiana の川;アラル海に注ぐ(古代人はカスピ海に注ぐと考えた);現 Amu Darya》.</div>\r\n"]);
